private enum ProviderChoice: String, CaseIterable, Codable, Identifiable, Sendable {
    case auto
    case codex
    case claude

    var id: String { rawValue }
    var title: String {
        switch self {
        case .auto: return "Auto"
        case .codex: return "Codex"
        case .claude: return "Claude Code"
        }
    }
    var subtitle: String {
        switch self {
        case .auto: return "RCC chooses"
        case .codex: return "OpenAI agent"
        case .claude: return "Anthropic agent"
        }
    }
    var symbol: String {
        switch self {
        case .auto: return "sparkles"
        case .codex: return "chevron.left.forwardslash.chevron.right"
        case .claude: return "sun.max.fill"
        }
    }
    var tint: Color {
        switch self {
        case .auto: return Color(red: 0.96, green: 0.58, blue: 0.74)
        case .codex: return Color(red: 0.95, green: 0.64, blue: 0.80)
        case .claude: return Color(red: 0.98, green: 0.53, blue: 0.68)
        }
    }
}

private func explicitlyRequestedProvider(in request: String) -> ProviderChoice? {
    let value = request
        .lowercased()
        .replacingOccurrences(of: "[\\p{P}\\p{S}]+", with: " ", options: .regularExpression)
        .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)

    // Voice dictation frequently turns 코덱스 into 코덱세/코덱센트/코덱선트.
    // This recognizes only directed backend requests; merely discussing a
    // provider keeps the private RCC auto route in control.
    let codexPatterns = [
        #"코덱(?:스|세|센트|선트)?\s*(?:(?:한테|에게|로|으로)(?:\s|\S){0,24}(?:시켜|시키|맡겨|보내|돌려|실행|해|하게|말|부탁)|(?:가|이)?\s*(?:뭐\s*)?(?:시켜|시키|맡겨|보내|돌려|실행|해|하게|말|부탁))"#,
        #"(?:시켜|시키|맡겨|보내|돌려|실행|부탁)(?:\s|\S){0,18}코덱(?:스|세|센트|선트)?"#,
        #"(?:use|ask|route|send|run|delegate)(?:\s+\w+){0,3}\s+codex\b"#,
        #"\bcodex\b(?:\s+\w+){0,3}\s+(?:do|run|handle|execute)\b"#,
    ]
    let claudePatterns = [
        #"클(?:로드|로더)\s*(?:코드)?\s*(?:(?:한테|에게|로|으로)(?:\s|\S){0,24}(?:시켜|시키|맡겨|보내|돌려|실행|해|하게|말|부탁)|(?:가|이)?\s*(?:뭐\s*)?(?:시켜|시키|맡겨|보내|돌려|실행|해|하게|말|부탁))"#,
        #"(?:시켜|시키|맡겨|보내|돌려|실행|부탁)(?:\s|\S){0,18}클(?:로드|로더)(?:\s*코드)?"#,
        #"(?:use|ask|route|send|run|delegate)(?:\s+\w+){0,3}\s+claude(?:\s+code)?\b"#,
        #"\bclaude(?:\s+code)?\b(?:\s+\w+){0,3}\s+(?:do|run|handle|execute)\b"#,
    ]
    func lastMatch(in patterns: [String]) -> String.Index? {
        patterns.compactMap { pattern in
            value.range(of: pattern, options: .regularExpression)?.lowerBound
        }.max()
    }
    let codex = lastMatch(in: codexPatterns)
    let claude = lastMatch(in: claudePatterns)
    switch (codex, claude) {
    case (.some(let codexIndex), .some(let claudeIndex)):
        return codexIndex > claudeIndex ? .codex : .claude
    case (.some, .none): return .codex
    case (.none, .some): return .claude
    case (.none, .none): return nil
    }
}

private func providerDisplayName(_ provider: String?, surface: String? = nil) -> String {
    if let route = ProviderSurface.resolveExecuted(rawSurface: surface, provider: provider) { return route.routeTitle }
    let value = provider?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    return value == nil || value == "" || value == "local" ? "OS-1" : value!.uppercased()
}

/// Route identity is the executed surface, not its quota or model family.
/// Bounded GPT/Claude lanes retain their own name while transport details stay
/// separate. Legacy backend-only records remain full-lane records: neither a
/// model name nor a requested fan-out target is evidence of the executed lane.
private struct ExecutionRoutePresentation: Equatable {
    let executionLine: String
    let modelLine: String?
    let reasoningLine: String?
    let detail: String

    init(activity: RuntimeActivity?) {
        let provider = activity?.provider?.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let route = ProviderSurface.resolveExecuted(rawSurface: activity?.surface, provider: provider)
        switch provider {
        case _ where activity?.phase == .waitingForSource:
            executionLine = os1Tr("백엔드 시작 전 · 소스 접근 대기", "Backend not started · waiting for source access")
            detail = os1Tr("OS-1 소스 수리·업데이트를 기다리고 있습니다. 모델 선택 지연이 아닙니다. 요청은 보존되며 소스 접근이 가능해지면 자동으로 이어갑니다.",
                           "Waiting for OS-1 source repair or update. This is not a model-selection delay. The request is preserved and continues when source access is available.")
        case _ where activity == nil:
            executionLine = os1Tr("라우팅 결과: 실행 기록 없음", "Route: no execution recorded")
            detail = os1Tr("이 대화에는 현재 실행 백엔드 기록이 없습니다.", "This conversation has no running backend record.")
        case "codex", "claude":
            executionLine = os1Tr("라우팅: \(route!.routeTitle)", "Route: \(route!.routeTitle)")
            detail = route!.executionLine + " " + os1Tr("모델은 별도로 표시합니다.", "The model is shown separately.")
        case "local":
            executionLine = os1Tr("라우팅 결과: OS-1 내부 처리", "Route: handled inside OS-1")
            detail = os1Tr("외부 Codex·Claude Code 실행 없이 OS-1이 처리했습니다.", "OS-1 handled this without a Codex or Claude Code run.")
        case nil, "", "routing":
            executionLine = os1Tr("라우팅 결과: 아직 선택 전", "Route: not selected yet")
            detail = os1Tr("실행 백엔드가 정해지기 전입니다. 모델 이름만으로 경로를 판단하지 않습니다.",
                           "No backend is selected yet. A model name alone does not decide the route.")
        default:
            executionLine = os1Tr("라우팅 결과: \(provider!.uppercased()) 실행", "Route: \(provider!.uppercased())")
            detail = os1Tr("기록된 실행 백엔드와 모델 이름을 따로 표시합니다.", "The recorded backend and model are shown separately.")
        }
        modelLine = activity?.model.flatMap { $0.isEmpty ? nil : os1Tr("모델: \($0)", "Model: \($0)") }
        // Display the recorded effort, never infer it from the model, provider
        // preference or another conversation. A missing value is not "none".
        if let activity, activity.phase != .waitingForSource {
            let effort = activity.effort?.trimmingCharacters(in: .whitespacesAndNewlines)
            let value: String
            if let effort, !effort.isEmpty {
                value = effort
            } else if provider == nil || provider == "" || provider == "routing" {
                value = os1Tr("아직 선택 전", "not selected yet")
            } else {
                value = os1Tr("기록 없음", "not recorded")
            }
            reasoningLine = os1Tr("추론: \(value)", "Reasoning: \(value)")
        } else {
            reasoningLine = nil
        }
    }

    var governanceLine: String { [executionLine, modelLine, reasoningLine].compactMap { $0 }.joined(separator: " · ") }
}

/// Backend records created by OS-1 contain a bounded execution envelope. The
/// native inspector shows the user's request, never that control/source blob.
private func visibleBackendUserRequest(_ value: String) -> String? {
    let marker = "--- CURRENT USER REQUEST ---"
    if let range = value.range(of: marker, options: .backwards) {
        let request = value[range.upperBound...].trimmingCharacters(in: .whitespacesAndNewlines)
        return request.isEmpty ? nil : request.precomposedStringWithCanonicalMapping
    }
    let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else { return nil }
    let lower = trimmed.lowercased()
    guard !lower.hasPrefix("continue the same user-selected work session."),
          !lower.hasPrefix("os-1 executor contract ") else { return nil }
    return trimmed.precomposedStringWithCanonicalMapping
}

private func nativeSessionURL(provider: ProviderChoice, sessionID: String?) -> URL? {
    guard provider != .auto, let sessionID,
          UUID(uuidString: sessionID) != nil else { return nil }
    switch provider {
    case .codex:
        return URL(string: "codex://threads/\(sessionID)")
    case .claude:
        var components = URLComponents()
        components.scheme = "claude"
        components.host = "resume"
        components.queryItems = [URLQueryItem(name: "session", value: sessionID)]
        return components.url
    case .auto:
        return nil
    }
}

private func visibleAdoptedSteps(_ steps: [AppRunStep]) -> [AppRunStep] {
    steps.filter {
        $0.revasDisposition == "adopted" || $0.revasDisposition == "control_verified"
    }
}

/// Adopted answers a review replaced (ReviewPass): never shown, but their
/// native sessions belong to the conversation.
private func reviewedDrafts(_ steps: [AppRunStep]) -> [AppRunStep] {
    steps.filter { $0.revasDisposition == "reviewed_draft" && stepRecordIsVerified($0) }
}

@MainActor
private func taskContextSelfTest() throws {
    // v3 handoff carries the OS-1 task context through the session codec.
    var session = ConversationSession(workspace: "/tmp")
    var context = TaskContext.migrated(conversationID: session.id, request: "야 인스타그램 수정 좀 하자 준비해", workspace: "/tmp",
        sourceContext: nil, codexSessionID: nil, claudeSessionID: nil)
    context.decideSemantic("Node 20.20.2 only")
    session.taskContext = context
    session.messages = [ChatMessage(role: .user, text: "야 인스타그램 수정 좀 하자 준비해")]
    let restored = try JSONDecoder().decode(ConversationSession.self, from: JSONEncoder().encode(session))
    let handoff = try SessionHandoff.decode(sessionHandoff(restored))
    guard handoff.format == SessionHandoff.currentFormat, handoff.taskContext?.conversationID == session.id,
          handoff.taskContext?.activeDecisions.map(\.text) == ["Node 20.20.2 only"] else {
        throw RunnerError.message("OS-1 v3 handoff lost the task context")
    }
    var ingested = restored
    ingested.messages.append(ChatMessage(role: .assistant, text: "native answer", provider: "codex", nativeIngestedID: "codex:abc"))
    guard try SessionHandoff.decode(sessionHandoff(ingested)).transcript.contains("[native session, outside OS-1]") else {
        throw RunnerError.message("Native-ingested turns must be labeled in the handoff")
    }
    // Adoption against the handed revision.
    var runtime = context
    runtime.bind(provider: "codex", nativeSessionID: UUID().uuidString)
    let handed = context.contextRevision
    guard context.adopting(runtime, handedRevision: handed).bindings.count == 1 else {
        throw RunnerError.message("Unchanged context must adopt the runtime result")
    }
    var changed = context
    changed.setObjective(TaskContext.Objective(requestText: "다른 요청"))
    let merged = changed.adopting(runtime, handedRevision: handed)
    guard merged.objective.requestText == "다른 요청", merged.bindings.count == 1, !changed.acceptsLateResult(fromRevision: handed) else {
        throw RunnerError.message("Changed context must keep its objective and treat the handed revision as late")
    }
    // Legacy and partially unreadable envelopes.
    let good = "{\"id\":\"\(UUID().uuidString)\",\"title\":\"t\",\"workspace\":\"/tmp\",\"provider\":\"auto\",\"messages\":[],\"updatedAt\":0}"
    let legacy = try JSONDecoder().decode(SessionEnvelope.self, from: Data("{\"schema\":4,\"sessions\":[\(good)]}".utf8))
    guard legacy.sessions.count == 1, legacy.sessions[0].taskContext == nil,
          migratedTaskContext(legacy.sessions[0], sourceContext: nil).conversationID == legacy.sessions[0].id else {
        throw RunnerError.message("Legacy envelope migration failed")
    }
    let broken = Data("{\"schema\":4,\"sessions\":[{\"id\":\"not-a-uuid\"},\(good)]}".utf8)
    guard (try? JSONDecoder().decode(SessionEnvelope.self, from: broken)) == nil,
          try JSONDecoder().decode(LenientSessionEnvelope.self, from: broken).sessions.compactMap(\.value).count == 1 else {
        throw RunnerError.message("Lenient envelope must keep the readable conversation")
    }
    guard TaskContext.explicitDecisions(in: "결정: Node 20으로 간다\n그리고 수정해") == ["Node 20으로 간다"] else {
        throw RunnerError.message("Explicit decision capture failed")
    }
}

/// The activity strip must flow at zero when nothing runs: a fixed window
/// anchored to the detector tick, one sample per bucket, both edges pinned,
/// sliding by exactly the tick advance. This is the Activity-Monitor behaviour
/// the owner asked for; it never fabricates a receipt.
private func governanceActivityStripSelfTest() throws {
    let now = Date(timeIntervalSince1970: 1_800_000_000)
    let idle = GovernanceActivityStrip.build(tasks: [], until: now, span: 1_800, bucketSeconds: 10)
    guard idle.points.count == 182, idle.points.first?.id == now.addingTimeInterval(-1_800),
          idle.points.last?.id == now, idle.maxValue == 0,
          zip(idle.points, idle.points.dropFirst()).allSatisfy({ $0.id < $1.id }) else {
        throw RunnerError.message("OS-1 governance activity strip does not flow at zero across its full window")
    }
    let next = GovernanceActivityStrip.build(tasks: [], until: now.addingTimeInterval(1), span: 1_800, bucketSeconds: 10)
    guard next.start == idle.start.addingTimeInterval(1), next.end == idle.end.addingTimeInterval(1),
          next.points.count == idle.points.count,
          next.points.dropFirst().dropLast().map(\.id) == idle.points.dropFirst().dropLast().map(\.id) else {
        throw RunnerError.message("OS-1 governance activity strip does not slide with the detector tick")
    }
    let week = GovernanceActivityStrip.build(tasks: [], until: now, span: 604_800, bucketSeconds: 3_600)
    guard week.points.count == 170, week.points.first?.id == now.addingTimeInterval(-604_800), week.points.last?.id == now else {
        throw RunnerError.message("OS-1 governance activity strip 7-day window is not dense and pinned")
    }
}

/// Build 329 governance monitor, run by the staged `app-self-test` gate: the
/// Δ figures sit on evidence time (one point per matched scope, the last one
/// equal to the headline value, times strictly increasing), the monitor opens
/// on the newest pair over a 7-day period, two-week-old evidence collapses the
/// comparison cards into one stale card, thin evidence is "too few", a token
/// cut reads as minus, and the goal card never shows a "0/N" ratio.
private func governanceEvidenceMonitorSelfTest() throws {
    func fail(_ message: String) -> Error { RunnerError.message("OS-1 governance monitor: " + message) }
    guard GovernanceMonitorView.defaultWindow == "7일" else { throw fail("the period does not open on 7 days") }
    let fm = FileManager.default
    let root = fm.temporaryDirectory.appendingPathComponent("os1-governance-self-test-" + UUID().uuidString)
    defer { try? fm.removeItem(at: root) }
    let store = GovernanceActivityStore(root: root)
    func scope(_ fill: Character) -> CompletionFeedbackScope {
        CompletionFeedbackScope(objectiveSHA256: String(repeating: fill, count: 64), sourceSHA256: nil,
            executorContractSHA256: String(repeating: "b", count: 64), assembledInputSHA256: String(repeating: "c", count: 64))
    }
    func task(_ bound: CompletionFeedbackScope, _ effort: String, adopted: Bool, tokens: Int?, at: Date) throws {
        let id = UUID().uuidString.lowercased(), remote = UUID().uuidString.lowercased()
        try store.begin(id: id, now: at)
        let usage = tokens.map {
            CompletionMeasuredUsage(inputTokens: $0, outputTokens: 0, cacheTokens: 0,
                resource: CompletionUsageResourceMetadata(format: .codexRolloutJSONL, byteCount: 100,
                    sha256: String(repeating: "e", count: 64), usageRecordCount: 1, accountingVersion: 2))
        }
        let observation = CompletionFeedbackObservation(executionID: remote, sequence: 1, provider: "codex", model: "gpt-test",
            effort: effort, outcome: adopted ? .adopted : .qualityFailure, usage: usage, durationMS: 1_000)
        try store.attempt(id: id, executionID: remote, sequence: 1, scope: bound, provider: "codex", model: "gpt-test",
            effort: effort, startedAt: at.addingTimeInterval(0.1), observation: observation)
        try store.finish(id: id, adopted: adopted, now: at.addingTimeInterval(2))
    }
    // The luna shape: low always first and failed, medium later; 6 matched
    // scopes, 2 fully measured, all of it two weeks old.
    let now = Date()
    let old = now.addingTimeInterval(-14 * 86_400)
    for (index, fill) in ["1", "2", "3", "4", "5", "6"].enumerated() {
        let at = old.addingTimeInterval(Double(index) * 600)
        let measured = index < 2
        try task(scope(Character(fill)), "low", adopted: false, tokens: measured ? 700_000 : nil, at: at)
        try task(scope(Character(fill)), "medium", adopted: index % 2 == 0, tokens: measured ? 212_000 : nil, at: at.addingTimeInterval(120))
    }
    let snapshot = store.snapshot(legacyRoot: nil)
    let allTime = snapshot.dashboardProjection(provider: nil, since: nil, includeHistorical: false, now: now)
    guard let pair = allTime.defaultComparison(), pair.baseline == "codex / gpt-test / low", pair.id == "codex / gpt-test / medium" else {
        throw fail("the default pair is not the newest comparison")
    }
    guard pair.completionEvidence.count == 6, pair.tokenEvidence.count == 2,
          zip(pair.completionEvidence, pair.completionEvidence.dropFirst()).allSatisfy({ $0.id < $1.id }),
          pair.completionEvidence.last?.value == pair.taskCompletionDelta,
          pair.tokenEvidence.last?.value == pair.tokenSavings else {
        throw fail("the Δ series is not on evidence time or does not end at the headline value")
    }
    let week = now.addingTimeInterval(-604_800)
    let period = snapshot.dashboardProjection(provider: nil, since: week, includeHistorical: false, now: now)
    let periodPair = period.comparisonsByBaseline[pair.baseline]?.first { $0.id == pair.id }
    let cards = GovernanceMonitorDeltaCards(period: periodPair, reference: pair, freshAfter: week)
    guard periodPair == nil, cards.isStale, cards.staleTitle.contains(GovernanceMonitorText.shortDate(pair.latestEvidenceAt!)),
          cards.staleNote.contains(GovernanceMonitorText.tokenChange(savings: pair.tokenSavings)) else {
        throw fail("two-week-old evidence is shown as a current headline")
    }
    let allCards = GovernanceMonitorDeltaCards(period: pair, reference: pair, freshAfter: week)
    guard allCards.isStale else { throw fail("under All, evidence older than 7 days is not stale") }
    let fresh = GovernanceMonitorDeltaCards(period: pair, reference: pair, freshAfter: old.addingTimeInterval(-60))
    guard !fresh.isStale, fresh.token == .tooFew(scopes: 2), fresh.completion == .value(pair.taskCompletionDelta!) else {
        throw fail("fresh n=2 tokens are not 'too few' or the 6-scope adoption Δ is hidden")
    }
    guard pair.completionDeltaIsSelectionBiased, cards.adoptionSummary(pair).contains("3/6") else {
        throw fail("a candidate that only ran after the baseline failed is not labelled as such")
    }
    guard GovernanceMonitorText.tokenChange(savings: pair.tokenSavings) == "\u{2212}69.7%" else {
        throw fail("a token cut does not read as minus: \(GovernanceMonitorText.tokenChange(savings: pair.tokenSavings))")
    }
    let goal = GovernanceMonitorText.goalValue(snapshot.quality(since: nil))
    guard !goal.contains("0/"), !goal.contains("%") else { throw fail("the goal card shows a ratio without verdicts") }
}

@MainActor
private func providerIntentSelfTest() throws {
    let sourceRef = SourceReference(kind: .snapshot, id: UUID(), sha256: String(repeating: "b", count: 64))
    var sourceSession = ConversationSession(workspace: "/tmp")
    sourceSession.sourceContext = sourceRef
    sourceSession.messages = (0..<42).map { index in
        ChatMessage(role: index.isMultiple(of: 2) ? .user : .assistant,
            text: "다음 요청 \(index)\n\n거기서 가져왔던 자료를 계속 사용합니다.",
            provider: index.isMultiple(of: 2) ? nil : "claude")
    }
    let restoredSession = try JSONDecoder().decode(ConversationSession.self, from: JSONEncoder().encode(sourceSession))
    let actualHandoff = try SessionHandoff.decode(sessionHandoff(restoredSession))
    guard actualHandoff.source == sourceRef,
          actualHandoff.transcript.contains("다음 요청 0\n"),
          actualHandoff.transcript.contains("다음 요청 41\n"),
          migratedSourceReference(ConversationSession(workspace: "/tmp")) == nil else {
        throw RunnerError.message("OS-1 persisted conversation source handoff failed")
    }
    var pendingSession = ConversationSession(workspace: "/tmp")
    pendingSession.messages = [ChatMessage(role: .assistant, text: "provisional fixture", provider: "claude", nativeRecordVerified: false)]
    guard try SessionHandoff.decode(sessionHandoff(pendingSession)).transcript.contains("UNVERIFIED BACKEND OUTPUT") else {
        throw RunnerError.message("Pending output lost its verification boundary in context")
    }
    let codexRequests = [
        "코덱스한테 말시켜봐",
        "코덱세한테 뭐 시켜봐",
        "1 더하기 1 코덱선트 시켜라니까",
        "코덱센트 시켜서 확인해",
        "ask Codex to run the tests",
        "use Codex for this task",
    ]
    let claudeRequests = [
        "클로드한테 레드팀 시켜",
        "이거 클로더 코드로 해",
        "ask Claude Code to review this",
        "use Claude for this task",
    ]
    let autoRequests = [
        "코덱스 사용량과 클로드 사용량을 비교해줘",
        "Codex and Claude are both backends",
        "이 버그를 고치고 테스트해",
    ]
    let failures = codexRequests.filter { explicitlyRequestedProvider(in: $0) != .codex }
        + claudeRequests.filter { explicitlyRequestedProvider(in: $0) != .claude }
        + autoRequests.filter { explicitlyRequestedProvider(in: $0) != nil }
        + (explicitlyRequestedProvider(in: "코덱스한테 시키지 말고 클로드한테 시켜") == .claude
            ? [] : ["last directed provider"])
    guard failures.isEmpty else {
        throw RunnerError.message("OS-1 provider intent self-test failed: \(failures.joined(separator: " | "))")
    }

    let codexSessionID = "01a060ab-f53b-71c3-a38e-e77b1b98ea74"
    let claudeSessionID = "bae5987c-3fd1-4d08-a85c-6d9c18d41e86"
    let manualSessionID = "17db0272-fc3c-402b-9f09-2cda62056a9a"
    let wrappedBackendPrompt = """
    Continue the same user-selected work session.
    --- PRIOR SESSION ---
    USER:
    hidden history
    --- CURRENT USER REQUEST ---
    실제 사용자 요청
    """
    guard nativeSessionURL(provider: .codex, sessionID: codexSessionID)?.absoluteString
            == "codex://threads/\(codexSessionID)",
          nativeSessionURL(provider: .claude, sessionID: claudeSessionID)?.absoluteString
            == "claude://resume?session=\(claudeSessionID)",
          nativeSessionURL(provider: .auto, sessionID: claudeSessionID) == nil,
          nativeSessionURL(provider: .codex, sessionID: "not-a-session") == nil,
          visibleBackendUserRequest(wrappedBackendPrompt) == "실제 사용자 요청",
