/// The Dock image OS-1 hands the Dock while it runs: OmarAGI.png's ring alone,
/// transparent around it and through its hole. macOS 26 shows a running app's
/// own image as given (no squircle plate), so this is the one place the Dock
/// can show through the logo (owner 2026-10-05: "동그라미 최대한 꽉 채우고 뒤에
/// 배경 투명색으로 빼. 너무 작아졌어"). The ring spans 900 of 1024 px: a circle
/// must be a little wider than the 824 px squircle body of the neighbouring
/// icons to read as the same size, and the smaller ring is what was rejected.
private enum OS1DockIcon {
    static let canvas = 1024
    static let ringDiameter: CGFloat = 900
    /// Ring outer diameter inside OmarAGI.png: 500 px of 512, centred.
    static let markRingFraction: CGFloat = 500.0 / 512.0

    static func transparentRing(markURL: URL? = Bundle.main.url(forResource: "OmarAGI", withExtension: "png")) -> NSImage? {
        guard let markURL, let mark = NSImage(contentsOf: markURL),
              let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: canvas, pixelsHigh: canvas,
                                         bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                                         colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0),
              let context = NSGraphicsContext(bitmapImageRep: rep) else { return nil }
        let side = ringDiameter / markRingFraction
        let origin = (CGFloat(canvas) - side) / 2
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = context
        context.imageInterpolation = .high
        NSColor.clear.set()
        NSRect(x: 0, y: 0, width: canvas, height: canvas).fill(using: .copy)
        mark.draw(in: NSRect(x: origin, y: origin, width: side, height: side),
                  from: .zero, operation: .sourceOver, fraction: 1)
        NSGraphicsContext.restoreGraphicsState()
        let image = NSImage(size: NSSize(width: canvas, height: canvas))
        image.addRepresentation(rep)
        return image
    }
}

/// Measures the image the running app hands the Dock: no plate at the corners
/// or in the hole, and the ring 900 px across. Only the app bundle carries
/// OmarAGI.png, so the release self-test measures it and a bare debug binary
/// reports the skip.
@MainActor
private func dockIconSelfTest() throws {
    guard Bundle.main.url(forResource: "OmarAGI", withExtension: "png") != nil else {
        print("Dock icon: skipped, OmarAGI.png is bundled only in the app"); return
    }
    guard let bitmap = OS1DockIcon.transparentRing()?.representations.first as? NSBitmapImageRep else {
        throw RunnerError.message("Dock icon: the transparent ring was not drawn")
    }
    let side = OS1DockIcon.canvas, mid = side / 2
    func alpha(_ x: Int, _ y: Int) -> CGFloat { bitmap.colorAt(x: x, y: y)?.alphaComponent ?? 1 }
    guard [(0, 0), (side - 1, 0), (0, side - 1), (side - 1, side - 1), (mid, mid)].allSatisfy({ alpha($0.0, $0.1) == 0 }) else {
        throw RunnerError.message("Dock icon: a corner or the ring's hole is not transparent")
    }
    let ring = (0..<side).filter { alpha($0, mid) > 0.5 }
    guard let left = ring.first, let right = ring.last,
          abs(CGFloat(right - left + 1) - OS1DockIcon.ringDiameter) <= 4 else {
        throw RunnerError.message("Dock icon: ring spans \(ring.first ?? -1)…\(ring.last ?? -1) of \(side) px")
    }
    print("Dock icon: ring \(right - left + 1) of \(side) px; corners and hole transparent")
}

private struct OmarAGILogo: View {
    let size: CGFloat

    var body: some View {
        Group {
            if let url = Bundle.main.url(forResource: "OmarAGI", withExtension: "png"),
               let image = NSImage(contentsOf: url) {
                Image(nsImage: image)
                    .resizable()
                    .interpolation(.high)
                    .antialiased(true)
                    .scaledToFit()
            } else {
                // Inside the frame like the PNG's ring: the rail self-test
                // measures the ring from its tile's top edge.
                ZStack {
                    Circle().strokeBorder(Theme.pink, lineWidth: max(4, size * 0.18))
                    Circle().fill(Color.white.opacity(0.94)).frame(width: max(4, size * 0.12))
                }
            }
        }
        .frame(width: size, height: size)
        .contentShape(Circle())
    }
}

private struct ProviderBrandIcon: View {
    let provider: ProviderChoice
    let size: CGFloat
    var filled = true

    private var resourceName: String {
        provider == .claude ? "ClaudeCode" : "Codex"
    }

    var body: some View {
        Group {
            if let url = Bundle.main.url(forResource: resourceName, withExtension: "png"),
               let image = NSImage(contentsOf: url) {
                Image(nsImage: image)
                    .resizable()
                    .interpolation(.high)
                    .antialiased(true)
                    .scaledToFit()
            } else {
                Image(systemName: provider == .claude ? "sun.max.fill" : "chevron.left.forwardslash.chevron.right")
                    .resizable()
                    .scaledToFit()
                    .foregroundStyle(provider.tint)
                    .padding(size * 0.2)
            }
        }
        .frame(width: size, height: size)
        .opacity(filled ? 1 : 0.96)
        .accessibilityHidden(true)
    }
}

/// Synthetic, headless fixture for the provider rail/inspector states. It
/// never reads the user's session store or native backend indexes.
@MainActor
private func renderBackendInspectorPreview(to output: URL) throws {
    let fileManager = FileManager.default
    try fileManager.createDirectory(at: output, withIntermediateDirectories: true,
        attributes: [.posixPermissions: 0o700])
    let fixtureRoot = fileManager.temporaryDirectory
        .appendingPathComponent("os1-backend-inspector-" + UUID().uuidString, isDirectory: true)
    try fileManager.createDirectory(at: fixtureRoot, withIntermediateDirectories: true)
    defer { try? fileManager.removeItem(at: fixtureRoot) }

    let currentID = "01a060ab-f53b-71c3-a38e-e77b1b98ea74"
    let missingID = "bae5987c-3fd1-4d08-a85c-6d9c18d41e86"
    let unrelatedID = "17db0272-fc3c-402b-9f09-2cda62056a9a"
    var current = NativeSessionSummary(id: currentID, provider: .codex,
        title: "Current recorded backend", workspace: "/tmp/os1-fixture", workspaceLabel: nil,
        updatedAt: Date(), sourcePath: nil, linkedTitle: "Inspector fixture")
    current.isPinned = true; current.pinPosition = 1
    var unrelated = NativeSessionSummary(id: unrelatedID, provider: .codex,
        title: "Unlinked local record", workspace: "/tmp/unlinked", workspaceLabel: nil,
        updatedAt: Date().addingTimeInterval(-120), sourcePath: nil, linkedTitle: nil)
    unrelated.isPinned = true; unrelated.pinPosition = 0

    func makeStore(
        name: String,
        recordedID: String?,
        nativeSessions: [NativeSessionSummary],
        selectedID: String?,
        messages: [NativeSessionMessage]
    ) throws -> SessionStore {
        let root = fixtureRoot.appendingPathComponent(name, isDirectory: true)
        let store = SessionStore(storageRoot: root, nativeSessionOpener: { _ in false })
        guard let selectedIndex = store.selectedIndex else { throw SourceContextError.invalid }
        store.sessions[selectedIndex].title = "Inspector fixture"
        store.sessions[selectedIndex].codexSessionID = recordedID
        store.surface = .codex
        store.nativeSessions = nativeSessions
        store.selectedNativeSessionID = selectedID
        store.nativeMessages = messages
        return store
    }

    func render(_ name: String, store: SessionStore) throws {
        let content = NativeSessionBrowser(store: store, provider: .codex)
            .frame(width: 1_120, height: 760)
            .background(Theme.background)
            .environment(\.colorScheme, .dark)
        let view = NSHostingView(rootView: content)
        view.frame = NSRect(x: 0, y: 0, width: 1_120, height: 760)
        // SwiftUI installs glyph runs on the next main-loop pass. Capturing
        // synchronously can otherwise produce a partially painted text layer.
        RunLoop.main.run(until: Date().addingTimeInterval(0.05))
        view.layoutSubtreeIfNeeded()
        view.needsDisplay = true
        view.displayIfNeeded()
        guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else {
            throw SourceContextError.invalid
        }
        view.cacheDisplay(in: view.bounds, to: bitmap)
        guard let data = bitmap.representation(using: .png, properties: [:]) else {
            throw SourceContextError.invalid
        }
        try data.write(to: output.appendingPathComponent(name), options: .atomic)
    }

    let currentStore = try makeStore(name: "current", recordedID: currentID,
        nativeSessions: [current, unrelated], selectedID: currentID, messages: [
        NativeSessionMessage(id: "fixture-user", role: .user,
            text: "현재 대화의 Codex 기록을 보여 줘.", timestamp: Date()),
        NativeSessionMessage(id: "fixture-assistant", role: .assistant,
            text: "이 패널은 현재 대화에 기록된 정확한 backend ID만 읽습니다.", timestamp: Date()),
    ])
    try render("backend-current.png", store: currentStore)

    let missingStore = try makeStore(name: "missing", recordedID: missingID,
        nativeSessions: [unrelated], selectedID: nil, messages: [])
    try render("backend-missing.png", store: missingStore)

    let noSessionStore = try makeStore(name: "no-session", recordedID: nil,
        nativeSessions: [unrelated], selectedID: nil, messages: [])
    try render("backend-no-session.png", store: noSessionStore)

    let manifest: [String: Any] = [
        "fixtureOnly": true,
        "provider": "codex",
        "refreshPolicy": [
            "intervalSeconds": 2,
            "decisionCoveredBy": "OS1App --self-test",
            "liveSwiftUITaskSchedulingCovered": false,
        ],
        "states": [
            ["image": "backend-current.png", "caption": "CURRENT RECORD · AVAILABLE", "selectedID": currentID],
            ["image": "backend-missing.png", "caption": "CURRENT RECORD · NOT FOUND", "recordedID": missingID],
            ["image": "backend-no-session.png", "caption": "THIS CONVERSATION · NO SESSION"],
        ],
    ]
    try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
        .write(to: output.appendingPathComponent("backend-inspector-preview.json"), options: .atomic)
}

@MainActor
private func renderQueuePreview(to output: URL) throws {
    try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true, attributes: [.posixPermissions: 0o700])
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-queue-preview-" + UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: root) }
    let store = SessionStore(storageRoot: root, runOperation: { _, _, _, _, _ in
        throw RunnerError.message("Preview cannot execute a backend")
    }, nativeSessionOpener: { _ in false })
    let id = store.selectedSessionID!
    store.sessions[0].title = "큐·포크 인터페이스 검증 — 실제 고객 작업 아님"
    store.sessions[0].taskContext = TaskContext(conversationID: id,
        objective: TaskContext.Objective(requestText: "격리된 스티어링 미리보기", kind: .other))
    store.activeRuns[id] = .init(submissionID: UUID(), started: Date().addingTimeInterval(-16),
        activity: RuntimeActivity(.executing, provider: "codex"), provider: .codex,
        handedRevision: store.sessions[0].taskContext!.contextRevision)
    try ExecutionSteering(root: root.appendingPathComponent("run-steering")).open(submissionID: store.activeRuns[id]!.submissionID,
        threadID: "preview-thread", turnID: "preview-turn")
    for text in ["첫 번째 결과를 바탕으로 문제 원인을 설명해 줘.", "그 다음 수정안을 검증하고 결과를 같은 대화에 정리해 줘.",
                 "마지막으로 남은 작업과 변경된 파일을 알려 줘. 먼저 보낸 요청의 결과를 기다려야 합니다."] {
        store.composer = text; store.send()
    }
    store.composer = "새 입력은 앞선 작업을 끊지 않고 대기열로 갑니다."
    for (name, width, paused) in [("queue-running.png", 960.0, false), ("queue-paused-compact.png", 660.0, true)] {
        store.sessions[0].queuePaused = paused
        let content = ComposerView(store: store, session: store.sessions[0])
            .frame(width: width, height: 470).background(Theme.background).environment(\.colorScheme, .dark)
        let view = NSHostingView(rootView: content)
        view.frame = NSRect(x: 0, y: 0, width: width, height: 470)
        RunLoop.main.run(until: Date().addingTimeInterval(0.1))
        view.layoutSubtreeIfNeeded(); view.displayIfNeeded()
        guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { throw SourceContextError.invalid }
        view.cacheDisplay(in: view.bounds, to: bitmap)
        guard let data = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
        try data.write(to: output.appendingPathComponent(name), options: .atomic)
    }
    print("Queue previews: running/paused compact; isolated fixture; model calls 0; live state unchanged")
}

@MainActor
private func renderComposerPreview(to output: URL) throws {
    try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true)
    let fixtures: [(String, String, Bool, Bool, VoiceDictationPhase, Bool)] = [
        ("idle-empty", "", false, false, .idle, false), ("idle-draft", "요청을 보내 주세요", false, false, .idle, false),
        ("idle-attachments", "첨부 미리보기를 확인해 줘", false, false, .idle, true),
        ("running-empty", "", true, false, .idle, false), ("running-draft", "이어서 결과를 설명해 줘", true, false, .idle, false),
        ("stopping-empty", "", true, true, .idle, false), ("stopping-draft", "이 입력은 보존됩니다", true, true, .idle, false),
        ("dictation-finalizing", "음성 입력 마무리 중", true, false, .finalizing, false)
    ]
    var report: [[String: Any]] = []
    for (name, draft, running, stopping, voice, includesAttachments) in fixtures {
        let action = ComposerPrimaryAction.resolve(draft: draft, running: running, stopping: stopping, voice: voice)
        // Paint the production composer, not an approximation of its old layout.
        let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-composer-preview-" + UUID().uuidString)
        defer { try? FileManager.default.removeItem(at: root) }
        let store = SessionStore(storageRoot: root, runOperation: { _, _, _, _, _ in
            throw RunnerError.message("Preview cannot execute a backend")
        }, nativeSessionOpener: { _ in false })
        store.composer = draft
        if includesAttachments {
            let image = root.appendingPathComponent("미리보기 이미지.png")
            let document = root.appendingPathComponent("검토 메모.txt")
            let fixtureImage = NSImage(size: NSSize(width: 96, height: 72))
            fixtureImage.lockFocus()
            NSColor(calibratedRed: 0.93, green: 0.70, blue: 0.80, alpha: 1).setFill()
            NSBezierPath(roundedRect: NSRect(x: 0, y: 0, width: 96, height: 72), xRadius: 14, yRadius: 14).fill()
            NSColor.black.withAlphaComponent(0.65).setFill()
            NSBezierPath(ovalIn: NSRect(x: 28, y: 16, width: 40, height: 40)).fill()
            fixtureImage.unlockFocus()
            guard let tiff = fixtureImage.tiffRepresentation,
                  let bitmap = NSBitmapImageRep(data: tiff),
                  let png = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
            try png.write(to: image, options: .atomic)
            try "OS-1 attachment preview fixture".write(to: document, atomically: true, encoding: .utf8)
            store.addAttachments([image, document])
        }
        if running {
            let id = store.selectedSessionID!
            store.activeRuns[id] = .init(submissionID: UUID(), started: Date().addingTimeInterval(-16),
                activity: RuntimeActivity(.executing, provider: "codex"), provider: .codex, handedRevision: 0)
            store.activeRuns[id]?.cancellationRequested = stopping
        }
        // The finalizing microphone requires a live audio session; its primary
        // button resolution is tested separately, never open a microphone here.
        let height: CGFloat = includesAttachments ? 330 : 250
        let content = ComposerView(store: store, session: store.selectedSession!)
            .frame(width: 660, height: height).background(Theme.background).environment(\.colorScheme, .dark)
        let view = NSHostingView(rootView: content)
        view.frame = NSRect(x: 0, y: 0, width: 660, height: height)
        RunLoop.main.run(until: Date().addingTimeInterval(includesAttachments ? 0.25 : 0.1))
        view.layoutSubtreeIfNeeded(); view.displayIfNeeded()
        guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { throw SourceContextError.invalid }
        view.cacheDisplay(in: view.bounds, to: bitmap)
        guard let data = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
        try data.write(to: output.appendingPathComponent(name + ".png"), options: .atomic)
        report.append(["fixture": name, "action": action.rawValue, "label": action.label, "enabled": action.enabled,
                       "primaryControlCount": 1, "controlSize": 32,
                       "attachmentPreview": includesAttachments,
                       "audioPhasePainted": voice == .idle ? "idle" : "not activated; action resolver tested only"])
    }
    try JSONSerialization.data(withJSONObject: report, options: [.prettyPrinted, .sortedKeys])
        .write(to: output.appendingPathComponent("states.json"), options: .atomic)
    print("Composer previews: 8 state fixtures including inline attachments; shared primary component; model calls 0")
}

@MainActor
private func codexShellSelfTest() throws {
    try reasoningVisibilitySelfTest()
    try sourceWaitPresentationSelfTest()
    var checks = 0
    func check(_ condition: Bool, _ name: String) throws {
        guard condition else { throw RunnerError.message("Shell regression: " + name) }
        checks += 1
    }
    // Route identity, executor transport and model remain separate facts.
    let codexRoute = ExecutionRoutePresentation(activity: RuntimeActivity(.executing, provider: "codex", model: "gpt-5.6-luna"))
    try check(codexRoute.executionLine.contains("Codex") && !codexRoute.executionLine.lowercased().contains("gpt"), "Codex executor is explicit, not a GPT route")
    try check(codexRoute.modelLine?.contains("gpt-5.6-luna") == true && codexRoute.governanceLine.contains("gpt-5.6-luna"), "the GPT model name stays beside the Codex executor")
    let claudeRoute = ExecutionRoutePresentation(activity: RuntimeActivity(.executing, provider: "claude", model: "claude-fixture"))
    try check(claudeRoute.executionLine.contains("Claude Code"), "Claude Code executor is explicit")
    try check(codexRoute.executionLine.contains("OpenAI") && claudeRoute.executionLine.contains("Anthropic")
              && !codexRoute.executionLine.contains("ChatGPT"), "the route names its provider, and never claims ChatGPT")
    for surface in [ProviderSurface.gptChat, .codex, .claudeChat, .claude] {
        let route = ExecutionRoutePresentation(activity: RuntimeActivity(.executing,
            provider: surface.backend!.rawValue, surface: surface.rawValue, model: "model-fixture"))
        try check(route.executionLine == os1Tr("라우팅: \(surface.routeTitle)", "Route: \(surface.routeTitle)"),
            "the actual executed \(surface.rawValue) route owns its primary identity")
        try check(!["usage", "limit", "한도", "사용량"].contains(where: route.executionLine.contains),
            "quota is never part of the primary \(surface.rawValue) identity")
        try check(route.detail.contains(surface.executionLine), "the real \(surface.rawValue) transport stays in details")
        try check(route.modelLine?.contains("model-fixture") == true,
            "model remains distinct from \(surface.rawValue)")
    }
    let mismatched = ExecutionRoutePresentation(activity: RuntimeActivity(.executing, provider: "codex",
        surface: "claude-chat", model: "gpt-fixture"))
    try check(mismatched.executionLine == codexRoute.executionLine, "a foreign surface cannot rename the actual executor")
    let falseHandoff = ExecutionRoutePresentation(activity: RuntimeActivity(.executing, provider: "codex", surface: "chatgpt"))
    try check(falseHandoff.executionLine == codexRoute.executionLine, "an executed Codex turn cannot be renamed ChatGPT")
    let pendingRoute = ExecutionRoutePresentation(activity: RuntimeActivity(.routing))
    try check(pendingRoute.modelLine == nil && !pendingRoute.executionLine.contains("Codex") && !pendingRoute.executionLine.contains("Claude"),
              "unresolved routing never impersonates an executor")
    let id = UUID()
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-shell-test-" + UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: root) }
    let store = SessionStore(storageRoot: root, runOperation: { _, _, _, _, _ in
        throw RunnerError.message("Shell test cannot execute a backend")
    }, nativeSessionOpener: { _ in false })
    let selected = store.selectedSessionID!
    let alternate = ConversationSession(title: "Selection fixture", workspace: root.path, updatedAt: .distantPast)
    store.sessions.append(alternate)
    store.select(alternate.id)
    try check(store.selectedSessionID == alternate.id, "session selection moves to the clicked row")
    store.select(selected)
    try check(store.selectedSessionID == selected, "session selection returns to the previously selected row")
    store.activeRuns[selected] = .init(submissionID: id, started: Date(),
        activity: RuntimeActivity(.executing, provider: "codex"), provider: .codex, handedRevision: 0)
    for request in ["QUEUED_ONLY_FIRST_SENTINEL", "QUEUED_ONLY_SECOND_SENTINEL"] {
        store.composer = request; store.send()
    }
    let queueBefore = store.queuedSubmissions
    let messages = [ChatMessage(role: .user, text: "SENT_USER_SENTINEL"),
                    ChatMessage(role: .assistant, text: "ANSWER_SENTINEL", provider: "codex")]
    for running in [false, true] {
        let text = timelineAttributedDocument(messages: messages, queuedSubmissions: store.queuedSubmissions,
            isRunning: running, workspace: "/tmp", sourceStore: SourceContextStore(root: root),
            publicProgress: running ? "PROGRESS_SENTINEL" : nil).string
        try check(!text.contains("QUEUED_ONLY"), "pending requests excluded from sent transcript")
        try check(text.contains("SENT_USER_SENTINEL") && text.contains("ANSWER_SENTINEL"), "actual messages retained")
        try check(!text.contains("작업 진행 중") && !text.contains("queued"), "no duplicate activity summary")
        try check(text.contains("PROGRESS_SENTINEL") == running, "progress preserved only while running")
    }
    try check(store.queuedSubmissions == queueBefore, "presentation never mutates queue")
    try check(store.queuedSubmissions.map(\.request) == ["QUEUED_ONLY_FIRST_SENTINEL", "QUEUED_ONLY_SECOND_SENTINEL"], "FIFO payload intact")
    let paths = ["/tmp/a b.txt", "/tmp/한글\"file\n.txt"]
    let appended = appendingFileReferences(paths, to: "기존 초안")
    try check(appended.hasPrefix("기존 초안\n\n"), "existing draft preserved")
    let decoded = try appended.split(separator: "\n").suffix(2).map { try JSONDecoder().decode(String.self, from: Data($0.utf8)) }
    try check(decoded == paths, "file-reference quoting round-trips Unicode, quote and newline")
    try check(appendingFileReferences([], to: "그대로") == "그대로", "cancel/no files leaves draft unchanged")
    let previewURL = root.appendingPathComponent("os1-inline-preview.png")
    let previewImage = NSImage(size: NSSize(width: 1600, height: 900))
    previewImage.lockFocus()
    NSColor.black.setFill()
    NSRect(x: 0, y: 0, width: 1600, height: 900).fill()
    previewImage.unlockFocus()
    guard let previewTIFF = previewImage.tiffRepresentation,
          let previewRep = NSBitmapImageRep(data: previewTIFF),
          let previewPNG = previewRep.representation(using: .png, properties: [:]) else {
        throw RunnerError.message("Shell regression: image fixture could not be encoded")
    }
    try previewPNG.write(to: previewURL)
    let visibleAttachmentPaths = [previewURL.path, "/tmp/os1-notes.pdf", "/tmp/os1-plan.txt"]
    let attachedMessage = ChatMessage(role: .user, text: appendingFileReferences(visibleAttachmentPaths, to: "첨부를 확인해 줘"))
    let attachmentDocument = timelineAttributedDocument(
        messages: [attachedMessage], queuedSubmissions: [], isRunning: false, workspace: "/tmp",
        sourceStore: SourceContextStore(root: root)
    )
    let attachmentText = attachmentDocument.string
    try check(!attachmentText.contains(PromptAttachments.marker)
        && !attachmentText.contains(previewURL.path)
        && !attachmentText.contains("/tmp/os1-notes.pdf"),
        "attachment transport paths never leak into the visible transcript")
    try check(!attachmentText.contains("os1-inline-preview.png")
        && attachmentText.contains("PDF · os1-notes.pdf")
        && attachmentText.contains("TXT · os1-plan.txt"),
        "image cards hide redundant filenames while document cards keep labels")
    var renderedAttachments: [(NSTextAttachment, Int)] = []
    attachmentDocument.enumerateAttribute(
        .attachment,
        in: NSRange(location: 0, length: attachmentDocument.length)
    ) { value, range, _ in
        if let attachment = value as? NSTextAttachment {
            renderedAttachments.append((attachment, range.location))
        }
    }
    try check(renderedAttachments.count == 3, "every accepted attachment remains visible")
    let imageBounds = renderedAttachments[0].0.bounds
    try check(abs(max(imageBounds.width, imageBounds.height) - Theme.attachmentPreviewMaxEdge) < 0.5,
        "image card uses the 360-point Codex convergence edge")
    let imageRole = attachmentDocument.attribute(
        .os1TimelineRole,
        at: renderedAttachments[0].1,
        effectiveRange: nil
    ) as? NSString
    try check(imageRole == "userAttachment", "image card renders outside the pink user bubble")
    store.addAttachments(visibleAttachmentPaths.map(URL.init(fileURLWithPath:)))
    try check(PromptAttachments.paths(in: store.composedRequest(from: "")) == visibleAttachmentPaths,
        "shared drop path becomes attachments instead of composer text")
    // The composer's text view must not be a drag destination for files:
    // AppKit would insert the path as text. Files fall through to the
    // composer's own drop target and become attachments.
    // The registration must survive the real code path — the editor hosted
    // by SwiftUI in a visible window, laid out and drawn — because AppKit
    // re-registers a text view's drag types lazily and a one-shot call
    // before hosting proved worthless in build143.
    // The trigger is a view joining a window that is ALREADY on screen —
    // what SwiftUI does with a representable — so build the window first
    // (off-screen, invisible), then add the production editor and let the
    // run loop turn. This sequence takes a plain NSTextView from 1
    // registered type to 20, file types included; the editor must stay at 1.
    // Without a shared NSApplication the window never gets a display pass
    // and the lazy registration never fires, which is why an earlier
    // version of this check could not catch the bug it was written for.
    _ = NSApplication.shared
    let (composerScroll, hostedTextView) = NativeComposerEditor.makeConfiguredEditor(text: "첨부 확인")
    composerScroll.frame = NSRect(x: 0, y: 0, width: 400, height: 80)
    let composerWindow = NSWindow(contentRect: NSRect(x: -20_000, y: -20_000, width: 400, height: 80), styleMask: [], backing: .buffered, defer: false)
    composerWindow.alphaValue = 0
    composerWindow.orderFront(nil)
    RunLoop.main.run(until: Date().addingTimeInterval(0.2))
    composerWindow.contentView?.addSubview(composerScroll)
    RunLoop.main.run(until: Date().addingTimeInterval(0.5))
    composerWindow.contentView?.display(); hostedTextView.display()
    composerWindow.makeFirstResponder(hostedTextView)
    RunLoop.main.run(until: Date().addingTimeInterval(0.2))
    // Sanity: the same sequence must move an unguarded NSTextView off [.string],
    // or this check proves nothing.
    let unguarded = NSTextView(frame: NSRect(x: 0, y: 0, width: 280, height: 60))
    unguarded.unregisterDraggedTypes(); unguarded.registerForDraggedTypes([.string])
    unguarded.isRichText = false
    let unguardedScroll = NSScrollView(frame: NSRect(x: 0, y: 0, width: 280, height: 60)); unguardedScroll.documentView = unguarded
    composerWindow.contentView?.addSubview(unguardedScroll)
    RunLoop.main.run(until: Date().addingTimeInterval(0.5))
    composerWindow.contentView?.display(); unguarded.display()
    RunLoop.main.run(until: Date().addingTimeInterval(0.2))
    try check(unguarded.registeredDraggedTypes.count > 1,
        "the drag re-registration trigger did not fire in this process (unguarded view kept \(unguarded.registeredDraggedTypes.count) type); the composer check below proves nothing")
    // Now the composer's own class through the identical sequence that just
    // flipped the unguarded view: it must hold at [.string].
    let bare = ComposerDropTextView(frame: NSRect(x: 0, y: 0, width: 280, height: 60))
    bare.acceptTextDragsOnly()
    bare.isRichText = false
    let bareScroll = NSScrollView(frame: NSRect(x: 0, y: 0, width: 280, height: 60)); bareScroll.documentView = bare
    composerWindow.contentView?.addSubview(bareScroll)
    RunLoop.main.run(until: Date().addingTimeInterval(0.5))
    composerWindow.contentView?.display(); bare.display()
    RunLoop.main.run(until: Date().addingTimeInterval(0.2))
    try check(bare.registeredDraggedTypes == [.string],
        "composer text view class re-registered file drags on the trigger that flips a plain NSTextView: \(bare.registeredDraggedTypes.map(\.rawValue))")
    try check(hostedTextView.registeredDraggedTypes == [.string],
        "composer text view accepts file drags after joining a visible window: \(hostedTextView.registeredDraggedTypes.map(\.rawValue))")
    composerWindow.orderOut(nil)
    try check(Theme.conversationWidth == 760 && Theme.sidebarWidth == 256, "shared layout dimensions")
    print("Codex-oriented shell: \(checks) checks passed; model calls 0; live state writes 0")
}

@MainActor
private func sourceWaitPresentationSelfTest() throws {
    var checks = 0
    func check(_ condition: Bool, _ message: String) throws {
        guard condition else { throw RunnerError.message("Source wait presentation: " + message) }
        checks += 1
    }
    let activity = RuntimeActivity(.waitingForSource, provider: "codex", model: "stale-model", effort: "ultra",
        publicText: "source writer fixture", nativeSessionID: UUID().uuidString)
    let data = try JSONEncoder().encode(activity)
    let decoded = try JSONDecoder().decode(RuntimeActivity.self, from: data)
    try check(decoded == activity && decoded.phase == .waitingForSource, "explicit source wait round trip")
    try check(decoded.provider == nil && decoded.model == nil && decoded.effort == nil && decoded.nativeSessionID == nil,
        "pre-backend source wait discards stale executed identity")
    struct LegacyActivity: Decodable {
        enum Phase: String, Decodable { case preparing, source, authorizing, routing, executing, verifying, syncing, recovering }
        let phase: Phase
    }
    try check(try JSONDecoder().decode(LegacyActivity.self, from: data).phase == .preparing,
        "old installed app can observe new runtime source waits during staged update")
    let object = try JSONSerialization.jsonObject(with: data) as! [String: Any]
    try check(object["waitingReason"] as? String == "source_write", "wire records specific wait reason")
    let legacy = RuntimeActivity(.preparing, publicText: "Waiting for an OS-1 repair to finish · fixture")
    let legacyDecoded = try JSONDecoder().decode(RuntimeActivity.self, from: JSONEncoder().encode(legacy))
    try check(legacyDecoded.phase == .waitingForSource, "new app recognizes installed runtime's exact legacy source wait notice")
    let ordinary = RuntimeActivity(.preparing, publicText: "Checking fixture source files")
    try check(try JSONDecoder().decode(RuntimeActivity.self, from: JSONEncoder().encode(ordinary)).phase == .preparing,
        "arbitrary source prose does not manufacture a lock wait")
    let route = ExecutionRoutePresentation(activity: activity)
    try check(route.executionLine.contains("백엔드 시작 전") && !route.executionLine.contains("선택 전"),
        "source contention is not presented as slow routing")
    try check(route.modelLine == nil && route.reasoningLine == nil, "source wait invents neither executed model nor effort")
    try check(activity.executionBadgeTitle == "실행 대기" && activity.backendConnectionLabel == "백엔드 아직 시작하지 않음",
        "badge never claims a native session is connecting before dispatch")
    try check(activity.convergenceLabel == "소스 접근 대기", "source wait has an explicit public stage")
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-source-wait-rail-" + UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: root) }
    let store = SessionStore(storageRoot: root, runOperation: { _, _, _, _, _ in throw RunnerError.message("presentation fixture must not dispatch") })
    let conversationID = store.selectedSessionID!, nativeID = UUID().uuidString.lowercased()
    store.sessions[0].provider = .codex; store.sessions[0].codexSessionID = nativeID
    store.activeRuns[conversationID] = .init(submissionID: UUID(), started: Date(), activity: activity, provider: .codex)
    try check(store.runningNativeSessionIDs(for: .codex).isEmpty,
        "source wait cannot mark a saved native backend session as running")
    store.activeRuns[conversationID]?.activity = RuntimeActivity(.executing, provider: "codex", nativeSessionID: nativeID)
    try check(store.runningNativeSessionIDs(for: .codex) == [nativeID], "executing native identity remains visible after source wait")
    print("Source-wait presentation: \(checks) checks; model calls 0")
}

@MainActor
private func sourceWaitSchedulingSelfTest() async throws {
    var checks = 0
    func check(_ condition: Bool, _ message: String) throws {
        guard condition else { throw RunnerError.message("Source wait scheduling: " + message) }
        checks += 1
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-source-wait-" + UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: root) }
    var blocked = true
    var dispatched: [String] = [], contexts: [String] = []
    let store = SessionStore(storageRoot: root, runOperation: { submission, context, _, _, _ in
        dispatched.append(submission.request); contexts.append(context)
        try await Task.sleep(for: .milliseconds(90))
        return AppRunSummary(status: "complete", steps: [AppRunStep(sequence: 1, provider: "local", action: "test",
            model: nil, effort: "none", revasDisposition: "adopted", sessionID: UUID().uuidString, permissionProfile: "read_only",
            exitCode: 0, output: "fixture " + submission.request, stderr: "", durationMS: 90, nativeRecord: nil)])
    }, sourceAdmissionCheck: { submission, _ in blocked && submission.request.hasPrefix("SOURCE") })
    store.updateSettings { $0.parallelRunLimit = 1 }
    let sourceID = store.selectedSessionID!
    store.composer = "SOURCE first"; store.send()
    let firstID = store.queuedSubmissions.first!.id
    store.composer = "SOURCE second"; store.send()
    let originalQueue: [PendingSubmission] = store.queuedSubmissions
    try check(store.activeRuns.isEmpty && dispatched.isEmpty && originalQueue.count == 2,
        "source wait creates no backend run and consumes no concurrency slot")
    try check(store.sourceWaitingActivity(sourceID)?.phase == .waitingForSource && store.globalSlotWait(sourceID) == nil,
        "source wait reason does not impersonate global slot wait")
    try check(store.queueReason(sourceID).contains("백엔드는 아직 시작하지 않았습니다"), "queued source wait is visible")
    try check(store.selectedSession?.taskContext == nil, "parked admission does not replace objective before execution")
    let reload = SessionStore(storageRoot: root, runOperation: { _, _, _, _, _ in throw RunnerError.message("must not replay") })
    try check(reload.queuedSubmissions.map(\.id) == originalQueue.map(\.id) && reload.activeRuns.isEmpty,
        "parked requests survive restart with IDs/order intact and no replay")
    store.createSession(); let siblingID = store.selectedSessionID!
    store.composer = "SIBLING project"; store.send()
    try check(store.activeRuns.count == 1 && store.activeRuns[siblingID] != nil && store.activeRuns[sourceID] == nil,
        "unrelated conversation uses the backend slot while source head stays parked")
    let deadline = Date().addingTimeInterval(8)
    while !store.activeRuns.isEmpty && Date() < deadline { try await Task.sleep(for: .milliseconds(20)) }
    try check(dispatched == ["SIBLING project"] && store.queuedSubmissions.map(\.id) == originalQueue.map(\.id),
        "sibling completion preserves blocked source queue")
    let intent = SelfUpdate.Intent(build: 298, version: "fixture", sourceRoot: root.path, sourceCommit: nil,
        stagedAppSHA256: "fixture-app", stagedCLISHA256: "fixture-cli", conversationID: nil, submissionID: nil, checks: [])
    try check(SelfUpdate.decision(intent: intent, installedBuild: 297, busy: !store.activeRuns.isEmpty) == .apply,
        "parked requests alone leave pending install's active-run gate idle")
    store.createSession(); let cancelSession = store.selectedSessionID!
    store.composer = "SOURCE cancelled"; store.send()
    let cancelled = store.queuedSubmissions.first { $0.sessionID == cancelSession }!.id
    store.removeQueued(cancelled)
    try check(!store.queuedSubmissions.contains { $0.id == cancelled } && store.activeRuns[cancelSession] == nil,
        "cancelling parked request launches no backend and removes only that queue item")
    blocked = false
    store.resumeSourceWaitingSubmissions(); store.resumeSourceWaitingSubmissions()
    try check(store.activeRuns[sourceID]?.submissionID == firstID && store.queuedSubmissions.filter { $0.sessionID == sourceID }.count == 1,
        "released source is admitted once; second request stays per-conversation FIFO")
    while (!store.activeRuns.isEmpty || !store.queuedSubmissions.isEmpty) && Date() < deadline {
        store.resumeSourceWaitingSubmissions()
        try await Task.sleep(for: .milliseconds(20))
    }
    try check(store.activeRuns.isEmpty && store.queuedSubmissions.isEmpty, "released queue reaches terminal drain")
    try check(dispatched == ["SIBLING project", "SOURCE first", "SOURCE second"], "exactly-once resume and cancellation preserve order")
    try check(contexts.count == 3 && !contexts[1].contains("SOURCE cancelled"), "cancelled input never enters resumed handoff")
    print("Source-wait scheduling: \(checks) checks; model calls 0")
}

@MainActor
private func sourceWriterFairnessSelfTest() async throws {
    var checks = 0
    func check(_ condition: Bool, _ message: String) throws {
        guard condition else { throw RunnerError.message("Source writer fairness: " + message) }
        checks += 1
    }
    let home = FileManager.default.temporaryDirectory.appendingPathComponent("os1-source-fairness-" + UUID().uuidString)
    let source = home.appendingPathComponent("source"), sibling = home.appendingPathComponent("sibling")
    defer { try? FileManager.default.removeItem(at: home) }
    for folder in [source, sibling] { try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true) }
    let lock = SourceWriteAdmission.lockURL(root: source.path, home: home)
    let intent = lock.appendingPathExtension("writer-intent")
    try FileManager.default.createDirectory(at: lock.deletingLastPathComponent(), withIntermediateDirectories: true)
    try Data().write(to: lock); try Data().write(to: intent)
    let readerFD = open(lock.path, O_RDONLY | O_CLOEXEC), writerFD = open(lock.path, O_RDONLY | O_CLOEXEC)
    let intentFD = open(intent.path, O_RDONLY | O_CLOEXEC)
    guard readerFD >= 0, writerFD >= 0, intentFD >= 0 else { throw RunnerError.message("fairness fixture lock open failed") }
    defer { close(readerFD); close(writerFD); close(intentFD) }
    try check(flock(readerFD, LOCK_SH | LOCK_NB) == 0, "initial HOME task owns actual shared lease")
    var releaseReader = false, releaseWriter = false
    var dispatched: [String] = []
    let store = SessionStore(storageRoot: home.appendingPathComponent("store"), runOperation: { submission, _, _, _, onActivity in
        dispatched.append(submission.request)
        if submission.request.hasPrefix("HOME first") {
            while !releaseReader { try await Task.sleep(for: .milliseconds(20)) }
            _ = flock(readerFD, LOCK_UN)
        } else if submission.request.hasPrefix("SOURCE repair") {
            guard flock(intentFD, LOCK_EX | LOCK_NB) == 0 else { throw RunnerError.message("fairness fixture writer intent unavailable") }
            onActivity(RuntimeActivity(.waitingForSource, publicText: "fixture source writer drains readers"))
            while flock(writerFD, LOCK_EX | LOCK_NB) != 0 { try await Task.sleep(for: .milliseconds(20)) }
            onActivity(RuntimeActivity(.executing, provider: "local"))
            while !releaseWriter { try await Task.sleep(for: .milliseconds(20)) }
            _ = flock(writerFD, LOCK_UN); _ = flock(intentFD, LOCK_UN)
        }
        return AppRunSummary(status: "complete", steps: [AppRunStep(sequence: 1, provider: "local", action: "test", model: nil,
            effort: "none", revasDisposition: "adopted", sessionID: UUID().uuidString, permissionProfile: "workspace_write",
            exitCode: 0, output: "fixture " + submission.request, stderr: "", durationMS: 20, nativeRecord: nil)])
    }, sourceAdmissionFixture: (source.path, home))
    store.updateSettings { $0.parallelRunLimit = 1 }
    let readerID = store.selectedSessionID!
    store.sessions[0].workspace = home.path
    store.composer = "HOME first 파일 수정해"; store.send()
    store.createSession(); let writerID = store.selectedSessionID!
    store.sessions[0].workspace = source.path
    store.composer = "SOURCE repair 파일 수정해"; store.send()
    let writerSubmissionID = store.queuedSubmissions.first!.id
    store.createSession(); let nextHomeID = store.selectedSessionID!
    store.sessions[0].workspace = home.path
    store.composer = "HOME next 파일 수정해"; store.send()
    try check(store.activeRuns.count == 1 && store.activeRuns[readerID] != nil && store.queuedSubmissions.count == 2,
        "cap-full repair stays queued without stopping the running reader")
    // Build 319: a HOME write is never parked behind a repair in the app. Its
    // runtime confines a Claude attempt from OS-1's source (no lease) and
    // makes a Codex attempt wait on the real shared lease.
    try check(store.sourceWaitingActivity(nextHomeID) == nil && store.globalSlotWait(nextHomeID) != nil,
        "a HOME follower behind a queued repair waits only for a run slot, never for source access")
    store.updateSettings { $0.parallelRunLimit = 2 }
    try check(store.activeRuns[writerID]?.submissionID == writerSubmissionID && store.activeRuns.count == 2,
        "exactly one repair is admitted through a reader-only hold to announce writer intent")
    try check(store.activeRuns[nextHomeID] == nil && store.queuedSubmissions.count == 1 &&
        store.sourceWaitingActivity(nextHomeID) == nil && store.globalSlotWait(nextHomeID) != nil,
        "the HOME follower then waits for a free slot, not for the repair entering runtime")
    let deadline = Date().addingTimeInterval(8)
    while store.activeRuns[writerID]?.activity.phase != .waitingForSource && Date() < deadline { try await Task.sleep(for: .milliseconds(20)) }
    try check(SourceWriteAdmission.availability(root: source.path, access: .shared, home: home) == .busy,
        "runtime fixture owns actual writer intent while readers drain")
    releaseReader = true
    while (store.activeRuns[readerID] != nil || store.activeRuns[writerID]?.activity.phase != .executing
           || !dispatched.contains("HOME next 파일 수정해") || store.activeRuns[nextHomeID] != nil) && Date() < deadline {
        try await Task.sleep(for: .milliseconds(20))
    }
    try check(store.activeRuns[writerID] != nil && store.activeRuns[nextHomeID] == nil && store.queuedSubmissions.isEmpty &&
        dispatched == ["HOME first 파일 수정해", "SOURCE repair 파일 수정해", "HOME next 파일 수정해"],
        "the freed slot runs the HOME follower beside the executing repair (its runtime confines it)")
    // A HOME write pinned to Codex cannot run confined: its runtime would only
    // wait for the repair, so it waits parked here and holds no run slot.
    store.createSession(); let codexHomeID = store.selectedSessionID!
    store.sessions[0].workspace = home.path
    store.sessions[0].provider = .codex
    store.composer = "HOME codex 파일 수정해"; store.send()
    try check(store.activeRuns[codexHomeID] == nil && store.sourceWaitingActivity(codexHomeID)?.phase == .waitingForSource
        && store.activeRuns.count == 1, "a Codex-pinned HOME write stays parked behind the repair without taking the free slot")
    store.createSession(); let siblingID = store.selectedSessionID!
    store.sessions[0].workspace = sibling.path
    store.composer = "SIBLING file 수정해"; store.send()
    try check(store.activeRuns[siblingID] != nil,
        "actual sibling project bypasses source repair, and a parked Codex HOME write does not hold its slot")
    while store.activeRuns[siblingID] != nil && Date() < deadline { try await Task.sleep(for: .milliseconds(20)) }
    releaseWriter = true
    while (!store.activeRuns.isEmpty || !store.queuedSubmissions.isEmpty) && Date() < deadline {
        store.resumeSourceWaitingSubmissions(); try await Task.sleep(for: .milliseconds(20))
    }
    try check(store.activeRuns.isEmpty && store.queuedSubmissions.isEmpty, "writer and HOME followers reach terminal drain")
    try check(dispatched == ["HOME first 파일 수정해", "SOURCE repair 파일 수정해", "HOME next 파일 수정해", "SIBLING file 수정해",
                             "HOME codex 파일 수정해"],
        "each request runs exactly once; the Codex HOME write resumes after the repair; the sibling is independent")
    releaseWriter = false
    store.createSession(); let idleWriterID = store.selectedSessionID!
    store.sessions[0].workspace = source.path
    store.composer = "SOURCE repair idle 파일 수정해"; store.send()
    store.createSession(); let followingWriterID = store.selectedSessionID!
    store.sessions[0].workspace = source.path
    store.composer = "SOURCE repair follower 파일 수정해"; store.send()
    // No await between sends: the first child has not announced intent yet.
    try check(store.activeRuns.count == 1 && store.activeRuns[idleWriterID] != nil &&
        store.activeRuns[followingWriterID] == nil && store.queuedSubmissions.count == 1,
        "source-lock-free startup gap admits only one repair, not multiple future lock waiters")
    releaseWriter = true
    while (!store.activeRuns.isEmpty || !store.queuedSubmissions.isEmpty) && Date() < deadline {
        store.resumeSourceWaitingSubmissions(); try await Task.sleep(for: .milliseconds(20))
    }
    try check(store.activeRuns.isEmpty && store.queuedSubmissions.isEmpty &&
        Array(dispatched.suffix(2)) == ["SOURCE repair idle 파일 수정해", "SOURCE repair follower 파일 수정해"],
        "queued idle-source repair resumes once after the admitted repair terminates")
    // I8 stays: a staged build ready to install still parks a HOME write, so
    // a stream of HOME work cannot keep that install from its idle moment.
    let staged = SelfUpdate.Intent(build: 999, version: "fixture", sourceRoot: source.path, sourceCommit: nil,
        stagedAppSHA256: "fixture-app", stagedCLISHA256: "fixture-cli", conversationID: nil, submissionID: nil, checks: [])
    try SelfUpdate.save(staged, root: source.path)
    store.createSession(); let gatedID = store.selectedSessionID!
    store.sessions[0].workspace = home.path
    store.composer = "HOME gated 파일 수정해"; store.send()
    try check(store.activeRuns[gatedID] == nil && store.sourceWaitingActivity(gatedID)?.phase == .waitingForSource,
        "a ready update still parks a HOME write before its install gate")
    try FileManager.default.removeItem(at: SelfUpdate.intentURL(root: source.path))
    let gateDeadline = Date().addingTimeInterval(8)
    while (!store.activeRuns.isEmpty || !store.queuedSubmissions.isEmpty) && Date() < gateDeadline {
        store.resumeSourceWaitingSubmissions(); try await Task.sleep(for: .milliseconds(20))
    }
    try check(store.queuedSubmissions.isEmpty && dispatched.last == "HOME gated 파일 수정해",
        "the parked HOME write resumes once the update is gone")
    print("Source-writer fairness: \(checks) checks; real isolated flock probes; model calls 0")
}

@MainActor
private func reasoningVisibilitySelfTest() throws {
    var checks = 0
    func check(_ value: Bool, _ label: String) throws {
        guard value else { throw RunnerError.message("Reasoning visibility: " + label) }
        checks += 1
    }
    let previousLanguage = ProcessInfo.processInfo.environment["OS1_INTERFACE_LANGUAGE"]
    defer {
        if let previousLanguage { setenv("OS1_INTERFACE_LANGUAGE", previousLanguage, 1) }
        else { unsetenv("OS1_INTERFACE_LANGUAGE") }
        OS1Localization.invalidate()
    }
    let efforts = ["low", "medium", "high", "xhigh", "max", "ultra", "none"]
    // The production sidebar is 256pt with 10pt padding on both sides.
    let rowWidth = Theme.sidebarWidth - 20
    func pixels(effort: String, selected: Bool) throws -> [UInt8] {
        let content = SessionRow(session: ConversationSession(title: "Reasoning fixture", workspace: "/tmp"),
            selected: selected, activity: RuntimeActivity(.executing, provider: "codex", model: "gpt-6.1-sol", effort: effort),
            previewTime: Date(timeIntervalSinceReferenceDate: 1_004), action: {})
            .frame(width: rowWidth, height: 132, alignment: .top)
            .background(Theme.background).environment(\.colorScheme, .dark)
        let view = NSHostingView(rootView: content)
        view.frame = NSRect(x: 0, y: 0, width: rowWidth, height: 132)
        view.layoutSubtreeIfNeeded()
        guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { throw SourceContextError.invalid }
        view.cacheDisplay(in: view.bounds, to: bitmap)
        guard let data = bitmap.bitmapData else { throw SourceContextError.invalid }
        return Array(UnsafeBufferPointer(start: data, count: bitmap.bytesPerRow * bitmap.pixelsHigh))
    }
    for language in ["ko", "en"] {
        setenv("OS1_INTERFACE_LANGUAGE", language, 1); OS1Localization.invalidate()
        for surface in [ProviderSurface.codex, .gptChat, .claude, .claudeChat] {
            for effort in efforts {
                let activity = RuntimeActivity(.executing, provider: surface.backend!.rawValue,
                    surface: surface.rawValue, model: "fixture-model", effort: effort)
                let decoded = try JSONDecoder().decode(RuntimeActivity.self, from: JSONEncoder().encode(activity))
                let route = ExecutionRoutePresentation(activity: decoded)
                let expected = os1Tr("추론: \(effort)", "Reasoning: \(effort)")
                try check(route.reasoningLine == expected, "\(language)/\(surface.rawValue)/\(effort) survives activity decoding")
                try check(route.governanceLine.components(separatedBy: expected).count == 2,
                    "the shared route summary includes reasoning exactly once")
                let textWidth = (expected as NSString).size(withAttributes: [.font: NSFont.systemFont(ofSize: 10, weight: .medium)]).width
                try check(textWidth <= rowWidth - 26, "\(expected) fits the real sidebar content width")
            }
        }
        try check(ExecutionRoutePresentation(activity: nil).reasoningLine == nil, "idle rows have no invented reasoning mode")
        try check(ExecutionRoutePresentation(activity: RuntimeActivity(.routing)).reasoningLine
            == os1Tr("추론: 아직 선택 전", "Reasoning: not selected yet"), "pending selection is explicit")
        for effort in [nil, "", " \n"] as [String?] {
            try check(ExecutionRoutePresentation(activity: RuntimeActivity(.executing, provider: "codex", effort: effort)).reasoningLine
                == os1Tr("추론: 기록 없음", "Reasoning: not recorded"), "missing or blank legacy effort is not a selected mode")
        }
        try check(ExecutionRoutePresentation(activity: RuntimeActivity(.executing, provider: "claude", effort: " max \n")).reasoningLine
            == os1Tr("추론: max", "Reasoning: max"), "recorded effort is whitespace-normalized")
        try check(ExecutionRoutePresentation(activity: RuntimeActivity(.executing, provider: "local", effort: "none")).reasoningLine
            == os1Tr("추론: none", "Reasoning: none"), "an explicit none remains distinct from missing")
        // Changing only effort must alter real SessionRow pixels in selected
        // AND background rows. A formatter-only fix cannot pass this check.
        for selected in [false, true] {
            let baseline = try pixels(effort: "low", selected: selected)
            let repeated = try pixels(effort: "low", selected: selected)
            try check(baseline == repeated, "identical row fixtures have stable pixels")
            for effort in efforts.dropFirst() {
                let rendered = try pixels(effort: effort, selected: selected)
                let changed = zip(baseline, rendered).filter { $0 != $1 }.count
                try check(baseline.count == rendered.count && changed > 10,
                    "\(language)/selected=\(selected)/\(effort) must change the displayed reasoning pixels")
            }
        }
    }
    print("Reasoning visibility: \(checks) checks passed; production SessionRow pixels at \(Int(rowWidth))pt; model calls 0; live state writes 0")
}

@MainActor
private func renderShellPreview(to output: URL) throws {
    try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true, attributes: [.posixPermissions: 0o700])
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-shell-preview-" + UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: root) }
