    for request in ["그다음 수정안을 확인해 줘.", "확인한 결과와 변경 파일을 정리해 줘."] {
        store.composer = request; store.send()
    }
    store.composer = ""
    let queueBefore = store.queuedSubmissions
    guard queueBefore.count == 2 else { throw SourceContextError.invalid }
    for (name, width, height, empty) in [("shell-compact.png", 1_100.0, 780.0, false),
                                       ("shell-wide.png", 1_440.0, 920.0, false),
                                       ("shell-empty.png", 1_100.0, 780.0, true)] {
        if empty {
            for item in store.queuedSubmissions { store.removeQueued(item.id) }
            store.sessions[0].messages = []; store.activeRuns = [:]
        }
        // Same components as RootView without its native-sidebar polling task.
        let content = HStack(spacing: 0) {
            ProviderRail(store: store)
            Rectangle().fill(Theme.border).frame(width: 1)
            SessionSidebar(store: store)
            Rectangle().fill(Theme.border).frame(width: 1)
            ConversationView(store: store)
        }.frame(width: width, height: height).background(Theme.background).environment(\.colorScheme, .dark)
        let view = NSHostingView(rootView: content)
        view.frame = NSRect(x: 0, y: 0, width: width, height: height)
        RunLoop.main.run(until: Date().addingTimeInterval(0.15))
        view.layoutSubtreeIfNeeded(); view.displayIfNeeded()
        guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { throw SourceContextError.invalid }
        view.cacheDisplay(in: view.bounds, to: bitmap)
        guard let data = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
        try data.write(to: output.appendingPathComponent(name), options: .atomic)
        if !empty, store.queuedSubmissions != queueBefore { throw SourceContextError.invalid }
    }
    print("Shell previews: compact/wide/empty; production views; isolated fixture; model calls 0")
}

@main
private struct OS1DesktopApp: App {
    private static var liveStoreLease: OS1LiveStoreLease?
    @StateObject private var store: SessionStore

    init() {
        // Every self-test suite asserts the Korean wording; pin the language
        // for all of them so the user's interface-language setting (English
        // by default) cannot flip the expectations. Build133's install failed
        // exactly here: only --self-test pinned it, --self-test-parallel ran
        // in English and its "미완료" status assertion threw. First, so the
        // suites dispatched just below are pinned too.
        if CommandLine.arguments.contains(where: { $0.hasPrefix("--self-test") }) {
            setenv("OS1_INTERFACE_LANGUAGE", "ko", 1)
            OS1Localization.invalidate()
            // A suite started inside a live run (staging, the release script,
            // the installer) is a fixture, not part of that run: its children
            // (the activity fixture) must not append to the owner's run journal.
            LiveRunEnvironment.detachCurrentProcess()
        }
        if CommandLine.arguments.contains("--self-test-fixture-store-probe") {
            // Child of fixtureStoreIsolationSelfTest, after the detach above.
            do {
                let seen = try fixtureStoreProbe()
                print(String(decoding: try JSONSerialization.data(withJSONObject: seen, options: [.sortedKeys]), as: UTF8.self))
                exit(EXIT_SUCCESS)
            } catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
        }
        if CommandLine.arguments.contains("--self-test-bound-native") {
            do { try boundNativeLookupSelfTest(); exit(EXIT_SUCCESS) }
            catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
        }
        if CommandLine.arguments.contains("--self-test-native-progress") {
            do { try nativeProgressPresentationSelfTest(); exit(EXIT_SUCCESS) }
            catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
        }
        if let flag = CommandLine.arguments.firstIndex(of: "--benchmark-bound-native") {
            do {
                guard CommandLine.arguments.count == flag + 2,
                      UUID(uuidString: CommandLine.arguments[flag + 1]) != nil else { throw SourceContextError.invalid }
                let id = CommandLine.arguments[flag + 1].lowercased()
                let start = Date()
                let original = try NativeSessionReader.sessions(for: .claude, including: id).first { $0.id.lowercased() == id }
                let browseMS = Int(Date().timeIntervalSince(start) * 1_000)
                let exactStart = Date()
                let selected = try NativeSessionReader.boundSession(for: .claude, including: id)
                let lookupMS = Int(Date().timeIntervalSince(exactStart) * 1_000)
                let transcript = try selected.map { try NativeSessionReader.transcript(for: $0, forIngestion: true) } ?? []
                let receipt: [String: Any] = ["browse_ms": browseMS, "exact_lookup_ms": lookupMS,
                    "same_source_path": original?.sourcePath == selected?.sourcePath,
                    "native_record_count": transcript.count, "model_calls": 0, "writes": false]
                print(String(decoding: try JSONSerialization.data(withJSONObject: receipt, options: [.sortedKeys]), as: UTF8.self))
                exit(EXIT_SUCCESS)
            } catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
        }
        if CommandLine.arguments.contains("--self-test-profile") {
            Task { @MainActor in
                do { try await profileMenuSelfTest(); exit(EXIT_SUCCESS) }
                catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
            }
            NSApplication.shared.run()
            exit(EXIT_FAILURE)
        }
        if let flag = CommandLine.arguments.firstIndex(of: "--render-profile-preview") {
            do {
                guard CommandLine.arguments.count == flag + 2 else { throw SourceContextError.invalid }
