                    setenv("OS1_INTERFACE_LANGUAGE", CommandLine.arguments[flag + 2], 1)
                    OS1Localization.invalidate()
                }
                let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-settings-preview-" + UUID().uuidString)
                try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
                defer { try? FileManager.default.removeItem(at: root) }
                let store = SessionStore(storageRoot: root, nativeSessionOpener: { _ in false })
                let content = OS1SettingsView(store: store).environment(\.colorScheme, .dark)
                let view = NSHostingView(rootView: content)
                view.frame = NSRect(x: 0, y: 0, width: 560, height: 640); view.layoutSubtreeIfNeeded()
                guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { throw SourceContextError.invalid }
                view.cacheDisplay(in: view.bounds, to: bitmap)
                guard let png = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
                try png.write(to: output); print(output.path); exit(EXIT_SUCCESS)
            } catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
        }
        if let flag = CommandLine.arguments.firstIndex(of: "--render-activity-preview") {
            do {
                guard CommandLine.arguments.count > flag + 1 else { throw SourceContextError.invalid }
                let output = URL(fileURLWithPath: CommandLine.arguments[flag + 1], isDirectory: true)
                try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true)
                let started = Date(timeIntervalSinceReferenceDate: 1_000)
                for (index, elapsed) in [4.0, 4.3, 65.0].enumerated() {
                    // The transcript's live row for a quiet run: twice within one second, then past a minute.
                    let quiet = LiveRunPresentation(activity: RuntimeActivity(.executing, provider: "codex", model: "gpt-5.6-luna",
                        effort: "medium", timestamp: started), started: started, now: started.addingTimeInterval(elapsed))
                    try liveRunPreviewPNG(quiet, expanded: false).write(to: output.appendingPathComponent("activity-\(index).png"))
                    let rowContent = VStack(spacing: 4) {
                        SessionRow(session: ConversationSession(title: "연구 자료 분석", workspace: "/tmp"), selected: true,
                            activity: RuntimeActivity(.executing, provider: "claude", model: "claude-fixture", effort: "max"), queuedCount: 1,
                            previewTime: started.addingTimeInterval(elapsed), action: {})
                        SessionRow(session: ConversationSession(title: "자동화 복원 검토", workspace: "/tmp"), selected: false,
                            activity: RuntimeActivity(.executing, provider: "codex", model: "gpt-6.1-sol", effort: "ultra"),
                            previewTime: started.addingTimeInterval(elapsed), action: {})
                        SessionRow(session: ConversationSession(title: "새 라우팅 요청", workspace: "/tmp"), selected: false,
                            activity: RuntimeActivity(.routing), previewTime: started.addingTimeInterval(elapsed), action: {})
                        SessionRow(session: ConversationSession(title: "추론 기록이 없는 실행", workspace: "/tmp"), selected: false,
                            activity: RuntimeActivity(.executing, provider: "codex", model: "fixture"),
                            previewTime: started.addingTimeInterval(elapsed), action: {})
                        SessionRow(session: ConversationSession(title: "완료한 대화", workspace: "/tmp"), selected: false, action: {})
                    }.frame(width: Theme.sidebarWidth - 20, height: 480).background(Theme.background).environment(\.colorScheme, .dark)
                    let rows = NSHostingView(rootView: rowContent)
                    rows.frame = NSRect(x: 0, y: 0, width: Theme.sidebarWidth - 20, height: 480); rows.layoutSubtreeIfNeeded()
                    guard let rowBitmap = rows.bitmapImageRepForCachingDisplay(in: rows.bounds) else { throw SourceContextError.invalid }
                    rows.cacheDisplay(in: rows.bounds, to: rowBitmap)
                    guard let rowPNG = rowBitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
                    try rowPNG.write(to: output.appendingPathComponent("sidebar-\(index).png"))
                }
                // A run with the backend's own steps under the request it works on, collapsed and opened.
                let request = [ChatMessage(role: .user, text: os1Tr("진행 표시를 작게 접었다 펼 수 있게 해 줘.",
                    "Make the progress display small and collapsible."))]
                let run = liveRunFixture(started: started)
                try liveRunPreviewPNG(run, expanded: false, messages: request).write(to: output.appendingPathComponent("activity-steps.png"))
                try liveRunPreviewPNG(run, expanded: true, messages: request).write(to: output.appendingPathComponent("activity-expanded.png"))
                // The run's public feed under the request: prose as text and tool calls folded, then one group opened.
                let feed = publicFeedFixture(now: started), feedText = feed.displayText
                let firstCalls = NativePublicRunLog.displaySegments(feedText[...]).first { $0.role == .action }
                for (name, expanded) in [("feed-folded", Set<String>()), ("feed-opened", Set(firstCalls.map { ["\(liveFeedKey)-tools-\($0.offset)"] } ?? []))] {
                    try transcriptPreviewPNG(timelineAttributedDocument(messages: request, queuedSubmissions: [], isRunning: true,
                        workspace: "/tmp", expanded: expanded, publicProgress: feedText, liveRun: run))
                        .write(to: output.appendingPathComponent(name + ".png"))
                }
                // The finished run: its work folded above the answer, then opened.
                let workRoot = FileManager.default.temporaryDirectory.appendingPathComponent("os1-work-preview-" + UUID().uuidString)
                defer { try? FileManager.default.removeItem(at: workRoot) }
                let workStore = NativePublicRunLogStore(root: workRoot)
                try workStore.save(feed)
                var answer = ChatMessage(role: .assistant, text: os1Tr("진행 출력은 이제 회색 한 줄로 접히고, 결론은 자연어 본문으로 남습니다.",
                    "The live output now folds into one gray line, and the conclusion stays as natural-language text."),
                    provider: "claude", executionSurface: "claude")
                answer.work = TurnWork(log: feed, started: started, answer: answer.text, now: started.addingTimeInterval(252))
                let finished = request + [answer, ChatMessage(role: .receipt, text: "Claude Code (Anthropic) · claude-fixture · max",
                    provider: "claude", executionSurface: "claude", nativeRecordVerified: true)]
                for (name, expanded) in [("work-folded", Set<String>()), ("work-opened", [answer.id.uuidString + "-work"])] {
                    try transcriptPreviewPNG(timelineAttributedDocument(messages: finished, queuedSubmissions: [], isRunning: false,
                        workspace: "/tmp", expanded: expanded, workLogStore: workStore))
                        .write(to: output.appendingPathComponent(name + ".png"))
                }
                print(output.path); exit(EXIT_SUCCESS)
            } catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
        }
        if let flag = CommandLine.arguments.firstIndex(of: "--render-session-transcript") ?? CommandLine.arguments.firstIndex(of: "--render-run-summary") {
            do {
                let args = CommandLine.arguments
                guard args.count > flag + 2 else { throw SourceContextError.invalid }
                let output = URL(fileURLWithPath: args[flag + 2])
                let session: ConversationSession
                if args[flag] == "--render-run-summary" {
                    let summary = try JSONDecoder().decode(AppRunSummary.self, from: Data(contentsOf: URL(fileURLWithPath: args[flag + 1])))
                    let steps = visibleAdoptedSteps(summary.steps)
                    guard summary.status == "complete", !steps.isEmpty, steps.allSatisfy(stepRecordIsVerified) else { throw SourceContextError.invalid }
                    let requestIndex = args.firstIndex(of: "--request")
                    let request = requestIndex.flatMap { $0 + 1 < args.count ? args[$0 + 1] : nil }
                        ?? "R2에서 QM·GR과 Orthogonal Projection Term 원본을 가져와."
                    var preview = ConversationSession(id: summary.taskContext?.conversationID ?? UUID(), workspace: FileManager.default.homeDirectoryForCurrentUser.path,
                        messages: [ChatMessage(role: .user, text: request)])
                    preview.sourceContext = summary.sourceContext
                    preview.taskContext = summary.taskContext
                    for step in steps {
                        preview.messages.append(ChatMessage(role: .assistant, text: step.output, provider: step.provider, executionSurface: step.executedSurface?.rawValue,
                            permissionProfile: step.permissionProfile))
                        preview.messages.append(ChatMessage(role: .receipt,
                            text: executionReceipt(step, source: summary.sourceContext),
                            provider: step.provider, executionSurface: step.executedSurface?.rawValue, nativeRecordVerified: stepRecordIsVerified(step)))
                    }
                    session = preview // in-memory only; never added to the user's sessions
                } else {
                    guard let id = UUID(uuidString: args[flag + 1]) else { throw SourceContextError.invalid }
                    let sessionsURL = FileManager.default.homeDirectoryForCurrentUser
                        .appendingPathComponent("Library/Application Support/OS-1/sessions.json")
                    let envelope = try JSONDecoder().decode(SessionEnvelope.self, from: Data(contentsOf: sessionsURL))
                    guard let existing = envelope.sessions.first(where: { $0.id == id }) else { throw SourceContextError.invalid }
                    session = existing
                }
                let widthIndex = args.firstIndex(of: "--width")
                let width = widthIndex.flatMap { $0 + 1 < args.count ? Double(args[$0 + 1]) : nil } ?? 1100
                guard (500...2400).contains(width) else { throw SourceContextError.invalid }
                let activityIndex = args.firstIndex(of: "--activity-file")
                let progress: RuntimeActivity? = try activityIndex.map {
                    guard $0 + 1 < args.count else { throw SourceContextError.invalid }
                    let data = try Data(contentsOf: URL(fileURLWithPath: args[$0 + 1]))
                    guard data.count < 150_000 else { throw SourceContextError.invalid }
                    return try JSONDecoder().decode(RuntimeActivity.self, from:data)
                }
                // A run's saved public feed, drawn as the live transcript draws it.
                let feedIndex = args.firstIndex(of: "--public-feed")
                let feed: String? = try feedIndex.map {
                    guard $0 + 1 < args.count else { throw SourceContextError.invalid }
                    let data = try Data(contentsOf: URL(fileURLWithPath: args[$0 + 1]))
                    guard data.count <= 16_000_000 else { throw SourceContextError.invalid }
                    return try JSONDecoder().decode(NativePublicRunLog.self, from: data).displayText
                }
                let waiting = args.contains("--waiting") || progress != nil || feed != nil
                let messages = waiting ? Array(presentedMessages(session).prefix(4)) : presentedMessages(session)
                let expanded = args.contains("--receipt-open")
                    ? Set(messages.filter { $0.role == .receipt }.map { $0.id.uuidString + "-receipt" }) : Set<String>()
                let document = timelineAttributedDocument(messages: messages, queuedSubmissions: [], isRunning: waiting,
                    workspace: session.workspace, expanded: expanded, expandAll: args.contains("--expanded"),
                    publicProgress: feed ?? progress?.publicText)
                let view = ContinuousTranscriptTextView(frame: NSRect(x: 0, y: 0, width: width, height: 1000))
                view.drawsBackground = false; view.backgroundColor = .black
                view.linkTextAttributes = TimelinePalette.linkAttributes
                view.isEditable = false; view.isSelectable = true
                view.isVerticallyResizable = true
                view.maxSize = NSSize(width: width, height: 100_000)
                view.textContainerInset = NSSize(width: 40, height: 34)
                view.textContainer?.lineFragmentPadding = 0
                view.textContainer?.heightTracksTextView = false
                view.textContainer?.widthTracksTextView = true
                view.textContainer?.containerSize = NSSize(width: width - 80, height: 100_000)
                view.layoutManager?.allowsNonContiguousLayout = false
                view.textStorage?.setAttributedString(document)
                view.setFrameSize(NSSize(width: width, height: 1000))
                view.layoutManager?.ensureLayout(forCharacterRange: NSRange(location: 0, length: document.length))
                let height = view.layoutManager!.usedRect(for: view.textContainer!).height + 100
                view.setFrameSize(NSSize(width: width, height: min(20_000, max(800, height))))
                let surface = TranscriptSnapshotSurface(frame: view.bounds)
                surface.addSubview(view)
                func numberOption(_ name: String) -> Double? {
                    args.firstIndex(of: name).flatMap { $0 + 1 < args.count ? Double(args[$0 + 1]) : nil }
                }
                let capture = NSRect(x: 0, y: numberOption("--viewport-top") ?? 0, width: width,
                    height: numberOption("--viewport-height") ?? surface.bounds.height).intersection(surface.bounds)
                guard !capture.isEmpty, let bitmap = surface.bitmapImageRepForCachingDisplay(in: capture) else { throw SourceContextError.invalid }
                surface.cacheDisplay(in: capture, to: bitmap)
                guard let data = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
                try data.write(to: output)
                let frames = view.timelineFrames()
                let pairs = zip(frames, frames.dropFirst()).map { previous, next in
                    ["from": previous.role, "to": next.role, "gapPoints": next.paint.minY - previous.paint.maxY,
                     "intersects": previous.paint.intersects(next.paint)] as [String: Any]
                }
                func box(_ rect: NSRect) -> [String: Double] {
                    ["x": rect.minX, "y": rect.minY, "width": rect.width, "height": rect.height]
                }
                let layout: [String: Any] = ["widthPoints": width, "heightPoints": view.bounds.height, "pixelsPerPoint": Double(bitmap.pixelsWide) / width,
                    "frames": frames.map { ["role": $0.role, "content": box($0.content), "paint": box($0.paint)] }, "pairs": pairs,
                    "tableCells": view.tableFrames()]
                try JSONSerialization.data(withJSONObject: layout, options: [.prettyPrinted, .sortedKeys]).write(to: output.appendingPathExtension("layout.json"))
                if args.contains("--reflow-check") {
                    let coordinator = ContinuousTranscriptView.Coordinator()
                    coordinator.content = ContinuousTranscriptView(sessionID: session.id, messages: messages, queuedSubmissions: [], isRunning: waiting, workspace: session.workspace)
                    coordinator.expanded = expanded
                    view.delegate = coordinator
                    var samples: [[String: Any]] = []
                    for targetWidth in [660.0, 1100.0, 900.0, 660.0] {
                        view.setFrameSize(NSSize(width: targetWidth, height: 20_000))
                        // Exercise the actual disclosure delegate, not a parallel mock.
                        for key in expanded.sorted() + expanded.sorted() {
                            _ = coordinator.textView(view, clickedOnLink: URL(string: "os1-detail://toggle/\(key)")!, at: 0)
                            let frames = view.timelineFrames()
                            samples.append(["widthPoints": targetWidth, "toggle": key,
                                "minimumGap": zip(frames, frames.dropFirst()).map { $1.paint.minY - $0.paint.maxY }.min() ?? 0,
                                "intersections": zip(frames, frames.dropFirst()).filter { $0.paint.intersects($1.paint) }.count,
                                "tableCells": view.tableFrames()])
                        }
                    }
                    try JSONSerialization.data(withJSONObject: samples, options: [.prettyPrinted, .sortedKeys]).write(to: output.appendingPathExtension("reflow.json"))
                }
                try MathTypesetter.copyable(document).write(to: output.appendingPathExtension("txt"), atomically: true, encoding: .utf8)
                var math: [String] = []
                document.enumerateAttribute(.os1MathSource, in: NSRange(location: 0, length: document.length)) { value, _, _ in
                    if let source = value as? String { math.append(source) }
                }
                try JSONEncoder().encode(math).write(to: output.appendingPathExtension("math.json"))
                try completeTranscriptText(presentedMessages(session)).write(to: output.appendingPathExtension("copy.txt"), atomically: true, encoding: .utf8)
                try sessionHandoff(session).write(to: output.appendingPathExtension("context.json"), atomically: true, encoding: .utf8)
                print(output.path); exit(EXIT_SUCCESS)
            } catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
        }
        if let flag = CommandLine.arguments.firstIndex(of: "--render-transcript-preview") {
            do {
                guard CommandLine.arguments.count > flag + 1 else { throw SourceContextError.invalid }
                let output = URL(fileURLWithPath: CommandLine.arguments[flag + 1])
                let messages = [
                    ChatMessage(role: .user, text: "가져온 자료를 기준으로 통합 아키텍처를 설명해 줘."),
                    ChatMessage(role: .assistant, text: "현재 자료에서 확인된 범위는 **약한 장의 검증**입니다. 전체 QM·GR 통합은 아직 미해결입니다.\n\n## 제안하는 구조\n\n1. 원본 자료와 검증된 결과를 분리해 보관합니다.\n2. 미해결 조건을 각각 독립적인 검증 단계로 둡니다.\n3. 모든 필수 조건을 통과한 뒤에만 채택합니다.\n\n| 구성 | 역할 |\n| --- | --- |\n| 원본 | 자료·출처 보존 |\n| 검증 | 필수 조건과 실제 결과 비교 |\n\n**다음 작업:** 아직 검증하지 않은 조건을 명시하고, 실행 가능한 첫 검증부터 진행합니다.\n\n```json\n" + (0..<18).map { "  \"stage_\($0)\": \"pending\", " }.joined(separator: "\n") + "\n```", provider: "claude", permissionProfile: "read_only"),
                    ChatMessage(role: .receipt, text: "Claude · sonnet · medium reasoning · native record verified · example receipt", nativeRecordVerified: true),
                    ChatMessage(role: .user, text: "좋아. 그다음 단계도 같은 자료로 설명해 줘."),
                ]
                let view = ContinuousTranscriptTextView(frame: NSRect(x: 0, y: 0, width: 1100, height: 900))
                view.drawsBackground = true; view.backgroundColor = .black
                view.linkTextAttributes = TimelinePalette.linkAttributes
                view.isEditable = false; view.isSelectable = true
                view.textContainerInset = NSSize(width: 50, height: 34)
                view.textContainer?.containerSize = NSSize(width: 1000, height: 10000)
                view.textStorage?.setAttributedString(timelineAttributedDocument(messages: messages, queuedSubmissions: [], isRunning: false, workspace: "/tmp"))
                view.layoutManager?.ensureLayout(for: view.textContainer!)
                guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { throw SourceContextError.invalid }
                view.cacheDisplay(in: view.bounds, to: bitmap)
                guard let data = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
                try data.write(to: output)
                print(output.path); exit(EXIT_SUCCESS)
            } catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
        }
        if let flag = CommandLine.arguments.firstIndex(of: "--audit-native-provenance") {
            do {
                guard CommandLine.arguments.count == flag + 2, let id = UUID(uuidString: CommandLine.arguments[flag + 1]) else { throw SourceContextError.invalid }
                let url = FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent("Library/Application Support/OS-1/sessions.json")
                let envelope = try JSONDecoder().decode(SessionEnvelope.self, from: Data(contentsOf: url))
                guard var session = envelope.sessions.first(where: { $0.id == id }) else { throw SourceContextError.invalid }
                let before = session.visibleMessages.count
                let outcomes = SessionStore.readBoundNativeRecords(session.taskContext?.bindings ?? [],
                    held: Set(session.visibleMessages.map { NativeIngestion.digestOf($0.text) }),
                    seen: Set(session.messages.compactMap(\.nativeIngestedID)), ownedCodexTurns: Set(session.ownedCodexTurnIDs ?? []))
                for outcome in outcomes { repairManagedImports(&session, records: outcome.managedRecords) }
                let report: [String: Any] = ["conversationID": id.uuidString, "storedMessages": session.messages.count,
                    "visibleBefore": before, "visibleAfter": session.visibleMessages.count,
                    "managedNativeRows": outcomes.flatMap(\.managedRecords).count,
                    "archivedImports": session.messages.filter { $0.nativeManagedTurnID != nil }.map { ["id": $0.id.uuidString, "role": $0.role.rawValue, "turn": $0.nativeManagedTurnID!] },
                    "sessionFileWritten": false, "modelCalls": 0]
                print(String(decoding: try JSONSerialization.data(withJSONObject: report, options: [.sortedKeys]), as: UTF8.self))
                exit(EXIT_SUCCESS)
            } catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
        }
        if let flag = CommandLine.arguments.firstIndex(of: "--export-session-context") {
            do {
                let args = CommandLine.arguments
                guard args.count > flag + 1, let id = UUID(uuidString: args[flag + 1]) else { throw SourceContextError.invalid }
                let url = FileManager.default.homeDirectoryForCurrentUser
                    .appendingPathComponent("Library/Application Support/OS-1/sessions.json")
                let envelope = try JSONDecoder().decode(SessionEnvelope.self, from: Data(contentsOf: url))
                guard let session = envelope.sessions.first(where: { $0.id == id }) else { throw SourceContextError.invalid }
                let before = args.count > flag + 2 ? UUID(uuidString: args[flag + 2]) : nil
                print(try sessionHandoff(session, before: before))
                exit(EXIT_SUCCESS)
            } catch {
                fputs("\(error.localizedDescription)\n", stderr)
                exit(EXIT_FAILURE)
            }
        }
        if CommandLine.arguments.contains("--self-test") {
            do {
                try fixtureStoreIsolationSelfTest()
                try reasoningVisibilitySelfTest()
                try governanceActivityStripSelfTest()
                try governanceEvidenceMonitorSelfTest()
                try nativeProvenanceSelfTest()
                try boundNativeLookupSelfTest()
                try nativeProgressPresentationSelfTest()
                try savedFailurePreviewSelfTest()
                try providerIntentSelfTest()
                try routeFanoutDetailsSelfTest()
                try taskContextSelfTest()
                try memoryPagingHandoffSelfTest()
                try interactionSelfTest()
                try transcriptLatencySelfTest()
                try liveRunRowSelfTest()
                try publicFeedPresentationSelfTest()
                try railSelectionSelfTest()
                try dockIconSelfTest()
                try sidebarSynchronizationSelfTest()
                try backendRecoverySelfTest()
                try selfUpdateReportSelfTest()
                print("OS-1 app governance activity strip, provider intent, source continuity, voice, math, selection, pin/archive/drafts/queue, backend accounts, backend self-repair, self-update self-test: OK")
                // Keep identity regressions in the standard release self-test,
                // not only behind the focused development diagnostic.
                Task { @MainActor in
                    do { try await profileMenuSelfTest(); exit(EXIT_SUCCESS) }
                    catch { fputs("\(error.localizedDescription)\n", stderr); exit(EXIT_FAILURE) }
                }
                NSApplication.shared.run()
                exit(EXIT_FAILURE)
            } catch {
                fputs("\(error.localizedDescription)\n", stderr)
                exit(EXIT_FAILURE)
            }
        }
        // Misspelled/newer diagnostic switches must not fall through into a
        // second live session-store writer when an older executable is used.
        if CommandLine.arguments.dropFirst().contains(where: { $0.hasPrefix("--") }) {
            fputs("Unsupported OS1 diagnostic option; live sessions were not opened.\n", stderr)
            exit(EXIT_FAILURE)
        }
        // A staged/fleet build must never become a second live-store writer or consume installation intents.
        guard SelfUpdate.isInstalledApp(Bundle.main.bundleURL) else {
            fputs("Non-installed OS1 GUI refused; live sessions were not opened. Use the installed application.\n", stderr)
            exit(EXIT_FAILURE)
        }
        do {
            let lease = try OS1LiveStoreLease()
            guard lease.tryAcquire() else {
                fputs("An installed OS1 GUI already owns the live store.\n", stderr)
                exit(EXIT_SUCCESS)
            }
            Self.liveStoreLease = lease
        } catch {
            fputs("OS1 could not acquire live-store ownership; sessions were not opened.\n", stderr)
            exit(EXIT_FAILURE)
        }
        // The Dock tile is frozen on the image it cached for build 259 (its
        // record still holds that bundle's file ID and mod date), so the
        // running app's own image is what replaces it. Handing it the icon
        // IconServices renders showed the 80% ring on the black plate, which
        // the owner rejected (2026-10-05: "너무 작아졌어 … 배경화면이 완전
        // 생블랙"). macOS 26 jails a bundle icon that is not a full squircle on
        // a gray plate but shows a running app's image as given, so the Dock
        // gets the ring alone on a transparent canvas; the bundle icon stands
        // in only if the PNG cannot be drawn.
        NotificationCenter.default.addObserver(forName: NSApplication.didFinishLaunchingNotification, object: nil, queue: .main) { _ in
            MainActor.assumeIsolated {
                NSApplication.shared.applicationIconImage = OS1DockIcon.transparentRing()
                    ?? NSWorkspace.shared.icon(forFile: Bundle.main.bundlePath)
            }
        }
        _store = StateObject(wrappedValue: SessionStore())
    }

    var body: some Scene {
        WindowGroup("OS-1 CLODEX") {
            RootView(store: store)
                .preferredColorScheme(.dark)
        }
        .windowStyle(.hiddenTitleBar)
        .defaultSize(width: 1360, height: 760)
        .commands {
            CommandGroup(replacing: .newItem) {
                Button(os1Tr("새 세션 페어", "New session pair")) { store.createSession() }
                    .keyboardShortcut("n", modifiers: [.command])
                Button(os1Tr("대화 검색", "Search conversations")) { NotificationCenter.default.post(name: Notification.Name("os1.focusSearch"), object: nil) }
                    .keyboardShortcut("k", modifiers: [.command])
                Button(os1Tr("현재 대화 고정/해제", "Pin/unpin current conversation")) { if let id = store.selectedSessionID { store.togglePin(id) } }
                    .keyboardShortcut("p", modifiers: [.command, .shift])
                Button(os1Tr("현재 대화 전체 복사", "Copy entire conversation")) { if let id = store.selectedSessionID { store.copyConversation(id) } }
                    .keyboardShortcut("c", modifiers: [.command, .shift])
                Button(os1Tr("완료된 대화에서 포크", "Fork from completed conversation")) { if let id = store.selectedSessionID { store.forkSession(id) } }
                    .keyboardShortcut("f", modifiers: [.command, .shift])
                    .disabled(store.selectedSessionID.map { !store.canForkSession($0) } ?? true)
                Button(os1Tr("현재 대기열 일시정지", "Pause current queue")) { if let id = store.selectedSessionID { store.pauseQueue(id) } }
                    .disabled(store.selectedSessionQueueCount == 0)
                Button(os1Tr("현재 대기열 계속 실행", "Resume current queue")) { store.resumeQueue() }
                    .disabled(store.selectedSessionID.map { !store.canResumeQueue($0) } ?? true)
                Button(os1Tr("현재 작업 중지", "Stop current task")) { store.cancelSelectedRun() }
                    .keyboardShortcut(".", modifiers: [.command])
                    .disabled(!store.isRunning || store.isStopping)
            }
            CommandMenu(os1Tr("권한", "Permissions")) {
                Button(os1Tr("검증된 R2 복구본 폴더 연결…", "Attach verified R2 recovery folder…")) { store.importArchiveMirror() }
                Divider()
                Button(os1Tr("파일·폴더 접근 설정…", "Files & Folders access settings…")) {
                    if let url = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_FilesAndFolders") { NSWorkspace.shared.open(url) }
                }
                Button(os1Tr("전체 디스크 접근 설정…", "Full Disk Access settings…")) {
                    if let url = URL(string: "x-apple.systempreferences:com.apple.preference.security?Privacy_AllFiles") { NSWorkspace.shared.open(url) }
                }
                Button(os1Tr("설치된 OS-1 앱 표시", "Reveal installed OS-1 app")) { NSWorkspace.shared.activateFileViewerSelecting([Bundle.main.bundleURL]) }
            }
            CommandMenu("Voice") {
                Button(store.voiceDictation.isActive ? "Finish Dictation" : "Start Dictation") {
                    store.toggleVoiceDictation()
                }
                .keyboardShortcut(.space, modifiers: [.command, .shift])

                Button("Cancel Dictation") {
                    _ = store.cancelVoiceDictation()
                }
                .keyboardShortcut(.escape, modifiers: [])
                .disabled(!store.voiceDictation.isActive)
            }
        }
        // Cmd+, — the same place Codex and Claude Code keep their settings.
        Settings {
            OS1SettingsView(store: store)
                .preferredColorScheme(.dark)
        }
    }
}

/// User settings, configured like Codex: language and backends in one pane,
/// persisted to OS-1's settings.json which every OS-1 process reads.
/// Sign in to Codex and Claude Code from OS-1, with more than one account
/// each. The same list the RCC Governance panel shows, so there is one account
/// screen rather than two that can disagree.
private struct BackendAccountsView: View {
    @ObservedObject var store: SessionStore
    @StateObject private var model = BackendAccountsModel()

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack {
                Text(os1Tr("백엔드 계정", "Backend accounts")).font(.headline)
                Spacer()
                Button(os1Tr("닫기", "Close")) { store.accountsOpen = false }.keyboardShortcut(.cancelAction)
            }
            .padding(.horizontal, 18).padding(.vertical, 14)
            Divider()
            ScrollView {
                BackendAccountsPanel(model: model,
                                     providers: store.appSettings.showCodex ? BackendAccounts.providers
                                        : BackendAccounts.providers.filter { $0 != "codex" })
                    .padding(18)
            }
        }
        .frame(width: 600, height: 540)
    }
}

private struct OS1SettingsView: View {
    @ObservedObject var store: SessionStore
    var manageAccounts: (() -> Void)? = nil

    private func binding<Value>(_ keyPath: WritableKeyPath<OS1Settings, Value>) -> Binding<Value> {
        Binding(get: { store.appSettings[keyPath: keyPath] },
                set: { value in store.updateSettings { $0[keyPath: keyPath] = value } })
    }

    var body: some View {
        Form {
            // Codex's General → Language row: English unless changed here,
            // "Auto detect" follows macOS.
            Section(os1Tr("일반", "General")) {
                LanguagePickerRow(title: os1Tr("언어", "Language"),
                                  description: os1Tr("앱 UI 언어", "Language for the app UI"),
                                  automaticTitle: os1Tr("자동 감지", "Auto detect"),
                                  languages: OS1LanguageCatalog.interface,
                                  selection: store.appSettings.interfaceLanguageCode,
                                  select: { code in store.updateSettings { $0.setInterfaceLanguage(code: code) } })
                LanguagePickerRow(title: os1Tr("응답 언어", "Response language"),
                                  description: os1Tr("OS-1 답변을 쓰는 언어", "Language OS-1 writes its answers in"),
                                  automaticTitle: os1Tr("자동 · 내 메시지 언어를 따름", "Auto · match my message"),
                                  languages: OS1LanguageCatalog.all,
                                  selection: store.appSettings.outputLanguageCode,
                                  select: { code in store.updateSettings { $0.setOutputLanguage(code: code) } })
                Text(os1Tr("언어는 메뉴·버튼·상태 표시에 바로 적용됩니다. OS-1 화면은 English와 한국어로 제공되고, ‘자동 감지’는 macOS 언어 순서에서 둘 중 먼저 오는 언어를 씁니다. 응답 언어는 Codex 언어 목록 전체에서 고를 수 있고, ‘자동’은 입력한 언어 그대로 답합니다 — 키보드가 영어라도 한국어로 쓰면 한국어로 답합니다.",
                           "Language applies to menus, buttons and status text right away. The OS-1 interface is available in English and 한국어; ‘Auto detect’ uses whichever comes first in your macOS language order. Response language offers Codex's full language list, and ‘Auto’ answers in whatever language you type — an English keyboard with a Korean message still gets a Korean answer."))
                    .font(.footnote).foregroundStyle(.secondary)
            }
            Section(os1Tr("동시 실행", "Parallel runs")) {
                Picker(os1Tr("동시에 실행할 대화 수", "Conversations running at the same time"),
                       selection: Binding(get: { store.appSettings.parallelRuns },
                                          set: { value in store.updateSettings { $0.parallelRunLimit = value } })) {
                    ForEach(Array(OS1Settings.parallelRunRange), id: \.self) { count in
                        Text(verbatim: "\(count)").tag(count)
                    }
                }
                Text(os1Tr("서로 다른 대화는 여기까지 동시에 실행됩니다. 지금 \(store.activeRuns.count)개 실행 중 · 대기 \(store.queuedSubmissions.count)개. 값을 올리면 슬롯을 기다리던 대화가 바로 시작되고, 내리면 이미 실행 중인 작업은 그대로 끝납니다. 한 대화 안의 후속 요청은 같은 작업 맥락을 이어가므로 순서대로 실행됩니다.",
                           "Different conversations run at the same time up to this number. \(store.activeRuns.count) running · \(store.queuedSubmissions.count) waiting. Raising it starts conversations that were waiting for a slot; lowering it lets running tasks finish. Follow-ups inside one conversation continue the same task and still run in order."))
                    .font(.footnote).foregroundStyle(.secondary)
                Text(os1Tr("높일수록 백엔드 한도(Codex·Claude)가 더 빨리 소진되고 기기 부하가 커집니다.",
                           "A higher number uses the Codex/Claude quotas faster and loads the machine more."))
                    .font(.footnote).foregroundStyle(.secondary)
            }
            Section(os1Tr("계정", "Accounts")) {
                ForEach([ProviderChoice.codex, ProviderChoice.claude]) { provider in
                    let account = store.activeAccount(for: provider)
                    LabeledContent(provider.title) {
                        Text(account.map { row in
                            row.signedIn
                                ? row.label + (row.signedInAs.map { " · \($0)" } ?? "")
                                : os1Tr("\(row.label) · 로그아웃", "\(row.label) · signed out")
                        } ?? "—")
                        .foregroundStyle(account?.signedIn == false ? Theme.amber : Color.secondary)
                    }
                }
                Button(os1Tr("계정 관리…", "Manage accounts…")) {
                    if let manageAccounts { manageAccounts() } else { store.accountsOpen = true }
                }
                Text(os1Tr("Codex와 Claude Code 로그인을 OS-1에서 직접 합니다. 제공자별로 여러 계정을 등록하고 어느 계정으로 실행할지 고를 수 있습니다.",
                           "Sign in to Codex and Claude Code from OS-1. Each provider can hold several accounts, and you choose which one runs."))
                    .font(.footnote).foregroundStyle(.secondary)
            }
            Section(os1Tr("백엔드", "Backends")) {
                Toggle(os1Tr("Codex 백엔드 사용", "Use the Codex backend"), isOn: binding(\.showCodex))
                Text(os1Tr("끄면 레일에서 사라지고 어떤 작업도 Codex로 라우팅되지 않습니다. Claude와 OS-1 로컬 실행만 사용합니다.",
                           "Turning this off removes Codex from the rail and no task routes to it. Only Claude and OS-1 local execution are used."))
                    .font(.footnote).foregroundStyle(.secondary)
                Toggle(os1Tr("한도 창 마감 전 Codex 몰아 쓰기", "Use up Codex quota before its window resets"),
                    isOn: Binding(get: { store.appSettings.burnCodexBeforeReset ?? true },
                                  set: { value in store.updateSettings { $0.burnCodexBeforeReset = value } }))
                Text(os1Tr("계정의 실제 한도 창이 \(store.appSettings.codexBurnLeadHours ?? 12)시간 안에 리셋되고 15% 이상 남아 있으면, ‘자동’으로 보낸 작업을 Codex로 돌려 리셋 전에 소진합니다. 뉴스가 아니라 계정 데이터 기준입니다.",
                           "When the account's real quota window resets within \(store.appSettings.codexBurnLeadHours ?? 12) h with 15%+ left, work sent as ‘Auto’ routes to Codex so it is used before the reset. Account data, not news."))
                    .font(.footnote).foregroundStyle(.secondary)
            }
            Section(os1Tr("정보", "About")) {
                LabeledContent(os1Tr("런타임", "Runtime"),
                    value: "\(Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "?") (build \(Bundle.main.infoDictionary?["CFBundleVersion"] as? String ?? "?"))")
                LabeledContent(os1Tr("설정 파일", "Settings file"), value: "~/Library/Application Support/OS-1/settings.json")
            }
        }
        .formStyle(.grouped)
        // Rendered at this size: language, parallel runs, backends and about
        // all fit without scrolling to reach the cap.
        .frame(width: 560, height: 640)
    }
}

/// A Mac or app restart must not silently drop OS-1 work (build 327): an
/// interrupted OS-1 repair resumes once through the follow-up path, no other
/// request is re-run by itself (it stays a failure the owner retries), old
/// work stays parked, and a readback promises a resume only while the resume
/// OS-1 scheduled still exists. Every file lives under a temporary root; no
/// model call.
@MainActor
private func restartResumeSelfTest() async throws {
    func check(_ value: Bool, _ name: String) throws {
        guard value else { throw RunnerError.message("Restart resume: " + name) }
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-restart-resume-" + UUID().uuidString)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    let now = Date()
    // The Mac booted after every fixture item below was written: a real
    // reboot. An app-only restart (boot long before) resumes nothing.
    let boot = now.addingTimeInterval(-30), appOnlyRestart = now.addingTimeInterval(-86_400)
    func writeStore(_ folder: URL, sessions: [ConversationSession], inFlight: [PendingSubmission], savedAt: Date,
                    queued: [PendingSubmission] = []) throws {
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let url = folder.appendingPathComponent("sessions.json")
        try JSONEncoder().encode(SessionEnvelope(schema: 4, sessions: sessions, queued: queued, inFlight: inFlight)).write(to: url)
        try FileManager.default.setAttributes([.modificationDate: savedAt], ofItemAtPath: url.path)
    }
    func complete(_ submission: PendingSubmission, _ context: String) throws -> AppRunSummary {
        var returned = try SessionHandoff.decode(context).taskContext
        if submission.readOnlyReconciliation == true {
            returned?.setObjective(TaskContext.Objective(requestText: submission.request, kind: .explain, scope: .readOnly))
        }
        return AppRunSummary(status: "complete", steps: [AppRunStep(sequence: 1, provider: "claude", action: "test",
            model: "fixture", effort: "low", revasDisposition: "adopted", sessionID: UUID().uuidString,
            permissionProfile: "workspace_write", exitCode: 0, output: "fixture", stderr: "", durationMS: 10, nativeRecord: nil)],
            taskContext: returned)
    }
    func idle(_ store: SessionStore) async throws {
        let deadline = Date().addingTimeInterval(10)
        while !store.activeRuns.isEmpty && Date() < deadline { try await Task.sleep(for: .milliseconds(20)) }
        try check(store.activeRuns.isEmpty, "a fixture run did not finish")
    }

    // 1. OS-1 repairs: a dead writer 10 minutes ago, a dead writer 8 hours
    // ago, and a writer that is still running. Each conversation's repair
    // run was in flight when the previous app ended.
    let repairFolder = root.appendingPathComponent("repairs")
    let repairs = PendingOS1RepairStore(root: repairFolder.appendingPathComponent("pending-os1-repairs"))
    var conversations: [ConversationSession] = []
    var interruptedRuns: [PendingSubmission] = []
    // The fourth conversation's owner follow-up ("고치라니까") was still
    // waiting for OS-1's source (no model reached) when the app ended.
    for title in ["recent", "old", "alive", "follow-up"] {
        let first = ChatMessage(role: .user, text: "로고 바꿔 " + title)
        var session = ConversationSession(title: title, workspace: root.path, messages: [first])
        var run = PendingSubmission(sessionID: session.id, userMessageID: first.id, request: first.text,
            provider: .auto, workspace: root.path, codexCapacity: 1, claudeCapacity: 1)
        run.preflightOnly = false
        if title == "follow-up" {
            let again = ChatMessage(role: .user, text: "아니 그래서 고치라니까?")
            session.messages.append(again)
            run = PendingSubmission(sessionID: session.id, userMessageID: again.id, request: again.text,
                provider: .auto, workspace: root.path, codexCapacity: 1, claudeCapacity: 1)
        }
        conversations.append(session); interruptedRuns.append(run)
    }
    let ages: [TimeInterval] = [10 * 60, 8 * 3_600, 60, 20 * 60]
    let writer: [Int32] = [999_991, 999_992, getpid(), 999_994]
    for (index, session) in conversations.enumerated() {
        try repairs.save(PendingOS1Repair(id: session.id.uuidString.lowercased(), conversationID: session.id.uuidString,
            submissionID: interruptedRuns[index].id.uuidString, ownerRequest: session.messages[0].text, corrections: [],
            draftReport: "draft", sourceRoot: nil, startCommit: nil, now: now.addingTimeInterval(-ages[index]), pid: writer[index]))
    }
    try writeStore(repairFolder, sessions: conversations, inFlight: interruptedRuns, savedAt: now.addingTimeInterval(-60))
    var repairCalls: [PendingSubmission] = []
    let repairOperation: SessionStore.RunOperation = { submission, context, _, _, _ in
        repairCalls.append(submission)
        try await Task.sleep(for: .milliseconds(20))
        return try complete(submission, context)
    }
    let repairStore = SessionStore(storageRoot: repairFolder, runOperation: repairOperation)
    // Two repairs resume in one pass: pin the run cap this test needs, so it
    // passes with any owner setting (serial mode included).
    repairStore.updateSettings { $0.parallelRunLimit = 4 }
    try check(repairStore.maximumConcurrentSessions >= 2, "the pinned run cap was not applied")
    try check(repairCalls.isEmpty && repairStore.activeRuns.isEmpty, "opening the store started work by itself")
    let alive: (PendingOS1Repair) -> Bool = { $0.pid == getpid() }
    // An app-only restart: the previous CLI may still run as an orphan, so
    // nothing is resumed and no submission runs twice.
    repairStore.resumeInterruptedWork(now: now, writerAlive: alive, bootTime: appOnlyRestart)
    try await idle(repairStore)
    try check(repairCalls.isEmpty && repairs.load(id: conversations[0].id.uuidString)?.autoResumeAttempted == nil
        && repairStore.sessions.first { $0.id == conversations[3].id }?.lastFailure?.id == interruptedRuns[3].id,
        "work was resumed after an app-only restart (no reboot since it was written)")
    repairStore.resumeInterruptedWork(now: now, writerAlive: alive, bootTime: boot)
    try await idle(repairStore)
    let recent = conversations[0].id, old = conversations[1].id, live = conversations[2].id, followUp = conversations[3].id
    let resumedRecent = repairCalls.filter { $0.sessionID == recent }, resumedFollowUp = repairCalls.filter { $0.sessionID == followUp }
    try check(repairCalls.count == 1 && resumedRecent.count == 1 && resumedRecent[0].request == PendingOS1Repair.resumeRequest
        && resumedRecent[0].readOnlyReconciliation != true, "the interrupted repair was not resumed exactly once through a follow-up")
    // The owner's own follow-up that was still in preflight is not re-run,
    // and OS-1 does not resume past it (build 327 fix): it stays the
    // conversation's failure for the owner to retry.
    let heldFollowUp = repairStore.sessions.first { $0.id == followUp }!
    try check(resumedFollowUp.isEmpty && heldFollowUp.lastFailure?.id == interruptedRuns[3].id
        && heldFollowUp.lastBackendFailure?.dispatchStage == .notDispatched
        && repairs.load(id: followUp.uuidString)?.autoResumeAttempted == nil
        && !heldFollowUp.messages.contains { $0.role == .system && ($0.text.contains("이어서") || $0.text.contains("resuming")) },
        "an owner follow-up OS-1 cannot prove never ran was re-run, or OS-1 resumed past it")
    let resumed = repairStore.sessions.first { $0.id == recent }!
    try check(resumed.messages.filter { $0.role == .user }.map(\.text) == ["로고 바꿔 recent"], "the resume added a synthetic owner turn")
    try check(resumed.messages.contains { $0.role == .system && $0.text.contains("OS-1") && ($0.text.contains("이어서") || $0.text.contains("resuming")) },
        "the conversation does not say OS-1 is resuming the interrupted change")
    try check(resumed.preservedTasks?.last?.request?.id == interruptedRuns[0].id, "the interrupted run was not preserved")
    try check(repairs.load(id: recent.uuidString)?.state == .interrupted && repairs.load(id: recent.uuidString)?.autoResumeAttempted == true,
        "the resumed record did not spend its once")
    try check(repairs.load(id: old.uuidString)?.state == .interrupted && repairs.load(id: old.uuidString)?.autoResumeAttempted == nil,
        "an 8-hour-old repair was resumed or not marked interrupted")
    try check(repairs.load(id: live.uuidString)?.state == .running, "a repair whose writer still runs was taken over")
    repairStore.resumeInterruptedWork(now: now.addingTimeInterval(5), writerAlive: alive, bootTime: boot)
    try await idle(repairStore)
    try check(repairCalls.count == 1, "a second pass resumed again")
    let relaunched = SessionStore(storageRoot: repairFolder, runOperation: repairOperation)
    // A repair this launch's own run writes from now on is not a restart's.
    let fresh = UUID().uuidString.lowercased()
    try repairs.save(PendingOS1Repair(id: fresh, conversationID: recent.uuidString, submissionID: nil, ownerRequest: "새 수리",
        corrections: [], draftReport: "", sourceRoot: nil, startCommit: nil, now: Date().addingTimeInterval(1), pid: 999_993))
    relaunched.resumeInterruptedWork(now: now.addingTimeInterval(10), writerAlive: alive, bootTime: boot)
    try await idle(relaunched)
    try check(repairCalls.count == 1, "an interrupted repair resumed more than once")
    try check(repairs.load(id: live.uuidString)?.state == .running && repairs.load(id: fresh)?.state == .running,
        "a live writer's record or one written after this launch was marked interrupted")
    repairs.remove(id: fresh)

    // A readback in a conversation whose repair is still pending (the
    // 8-hour-old one, never resumed by itself) promises no resume: the OS-1
    // part is recorded and continues on the owner's next message here.
    relaunched.select(old)
    relaunched.reconcileSelectedFailure()
    try await idle(relaunched)
    try check(repairCalls.count == 2 && repairCalls[1].readOnlyReconciliation == true
        && repairCalls[1].request.contains(BackendRecovery.pendingOS1RepairNote)
        && !repairCalls[1].request.contains(BackendRecovery.pendingOS1RepairResumingNote),
        "the readback of a repair OS-1 did not resume promises a resume or omits the pending OS-1 part")
    // The owner's Retry of the held follow-up runs it once, words included,
    // as the same submission (the CLI continues the repair through it).
    relaunched.select(followUp)
    relaunched.retrySelectedFailure()
    try await idle(relaunched)
    try check(repairCalls.count == 3 && repairCalls[2].id == interruptedRuns[3].id && repairCalls[2].request == "아니 그래서 고치라니까?",
        "the owner's retry of the held follow-up did not run it once as itself")
    try check(!BackendRecovery.readbackPrompt(objective: "x").contains(BackendRecovery.pendingOS1RepairNote),
        "a readback without a pending repair changed")

    // 2. Requests that never reached a model before the restart are not
    // re-run by themselves, however recent (build 327 fix): an orphan CLI may
    // have dispatched them. Each stays a failure; the owner's Retry runs it.
    var preflightCalls: [PendingSubmission] = []
    for (label, age) in [("old", 3.0 * 3_600), ("recent", 30.0 * 60)] {
        let folder = root.appendingPathComponent("preflight-" + label)
        let request = ChatMessage(role: .user, text: "스피너 색 바꿔 " + label)
        let session = ConversationSession(title: label, workspace: root.path, messages: [request])
        let waiting = PendingSubmission(sessionID: session.id, userMessageID: request.id, request: request.text,
            provider: .auto, workspace: root.path, codexCapacity: 1, claudeCapacity: 1)
        try writeStore(folder, sessions: [session], inFlight: [waiting], savedAt: now.addingTimeInterval(-age))
        let operation: SessionStore.RunOperation = { submission, _, _, _, _ in
            preflightCalls.append(submission)
            try await Task.sleep(for: .milliseconds(20))
            throw RunnerError.backend(BackendFailureNotice(provider: "local", sessionID: nil,
                blocker: .unclassified, dispatchStage: .notDispatched))
        }
        let store = SessionStore(storageRoot: folder, runOperation: operation)
        for (pass, bootTime) in [appOnlyRestart, boot, boot].enumerated() {
            store.resumeInterruptedWork(now: now.addingTimeInterval(Double(pass) * 5), writerAlive: { _ in false }, bootTime: bootTime)
            try await idle(store)
        }
        let again = SessionStore(storageRoot: folder, runOperation: operation)
        again.resumeInterruptedWork(now: now.addingTimeInterval(20), writerAlive: { _ in false }, bootTime: boot)
        try await idle(again)
        let held = again.sessions.first { $0.id == session.id }!
        try check(preflightCalls.filter { $0.sessionID == session.id }.isEmpty && held.lastFailure?.id == waiting.id
            && held.messages.filter { $0.role == .user }.count == 1,
            "a \(label) request interrupted before a model was re-run by itself or lost its failure")
        again.select(session.id)
        again.retrySelectedFailure()
        try await idle(again)
        let runs = preflightCalls.filter { $0.sessionID == session.id }
        try check(runs.count == 1 && runs[0].id == waiting.id && runs[0].request == waiting.request,
            "the owner's retry of a \(label) interrupted request did not run it exactly once")
    }
    // 3. The owner's Stop wins over the resume: a cancel marker on the
    // interrupted run cancels the pending repair. A queued replacement only
    // takes the resume's place: the record survives for it (build 327 fix).
    for variant in ["stopped", "replaced"] {
        let folder = root.appendingPathComponent("stop-" + variant)
        let store = PendingOS1RepairStore(root: folder.appendingPathComponent("pending-os1-repairs"))
        let first = ChatMessage(role: .user, text: "로고 바꿔 " + variant)
        var session = ConversationSession(title: variant, workspace: root.path, messages: [first])
        var run = PendingSubmission(sessionID: session.id, userMessageID: first.id, request: first.text,
            provider: .auto, workspace: root.path, codexCapacity: 1, claudeCapacity: 1)
        run.preflightOnly = false
        var queued: [PendingSubmission] = []
        if variant == "replaced" {
            let next = ChatMessage(role: .user, text: "다른 거 먼저 해")
            session.messages.append(next)
            var replacement = PendingSubmission(sessionID: session.id, userMessageID: next.id, request: next.text,
                provider: .auto, workspace: root.path, codexCapacity: 1, claudeCapacity: 1)
            replacement.startNextRequested = true
            replacement.replacesSubmissionID = run.id
            queued = [replacement]
        }
        try store.save(PendingOS1Repair(id: session.id.uuidString.lowercased(), conversationID: session.id.uuidString,
            submissionID: run.id.uuidString, ownerRequest: first.text, corrections: [], draftReport: "draft",
            sourceRoot: nil, startCommit: nil, now: now.addingTimeInterval(-600), pid: 999_995))
        try writeStore(folder, sessions: [session], inFlight: [run], savedAt: now.addingTimeInterval(-60), queued: queued)
        if variant == "stopped" {
            let journals = folder.appendingPathComponent("run-journals", isDirectory: true)
            try FileManager.default.createDirectory(at: journals, withIntermediateDirectories: true)
            try Data().write(to: journals.appendingPathComponent(run.id.uuidString + ".cancel"))
        }
        var calls: [PendingSubmission] = []
        let stopStore = SessionStore(storageRoot: folder, runOperation: { submission, context, _, _, _ in
            calls.append(submission); return try complete(submission, context)
        })
        stopStore.updateSettings { $0.parallelRunLimit = 4 }
        stopStore.resumeInterruptedWork(now: now, writerAlive: { _ in false }, bootTime: boot)
        try await idle(stopStore)
        try check(calls.filter { $0.request == PendingOS1Repair.resumeRequest || $0.id == run.id }.isEmpty,
            "a \(variant) repair was resumed beside the owner's Stop or queued message")
        try check(variant == "stopped" ? store.load(id: session.id.uuidString) == nil : store.load(id: session.id.uuidString) != nil,
            variant == "stopped" ? "the owner's Stop did not cancel the pending repair" : "a queued message was taken as a Stop")
    }

    // 3b. A message the owner sends after the restart ("계속", as the readback
    // asks) is not a Stop, even when it waits for a free run slot: the
    // pending repair survives and that message continues it (build 327 fix).
    do {
        let folder = root.appendingPathComponent("continue-cap-full")
        let store = PendingOS1RepairStore(root: folder.appendingPathComponent("pending-os1-repairs"))
        let first = ChatMessage(role: .user, text: "로고 바꿔 cap-full")
        let session = ConversationSession(title: "repair", workspace: root.path, messages: [first])
        let busy = ConversationSession(title: "busy", workspace: root.path, messages: [])
        var run = PendingSubmission(sessionID: session.id, userMessageID: first.id, request: first.text,
            provider: .auto, workspace: root.path, codexCapacity: 1, claudeCapacity: 1)
        run.preflightOnly = false
        try store.save(PendingOS1Repair(id: session.id.uuidString.lowercased(), conversationID: session.id.uuidString,
            submissionID: run.id.uuidString, ownerRequest: first.text, corrections: [], draftReport: "draft",
            sourceRoot: nil, startCommit: nil, now: now.addingTimeInterval(-600), pid: 999_996))
        try writeStore(folder, sessions: [session, busy], inFlight: [run], savedAt: now.addingTimeInterval(-60))
        final class Gate { var open = false }
        let gate = Gate()
        var calls: [PendingSubmission] = []
        let capStore = SessionStore(storageRoot: folder, runOperation: { submission, context, _, _, _ in
            calls.append(submission)
            while submission.sessionID == busy.id && !gate.open { try await Task.sleep(for: .milliseconds(10)) }
            return try complete(submission, context)
        })
        capStore.updateSettings { $0.parallelRunLimit = 1 }
        capStore.select(busy.id); capStore.composer = "푸터 색 바꿔"; capStore.send()
        try check(capStore.activeRuns.count == 1 && capStore.isSessionRunning(busy.id), "the other conversation did not take the only run slot")
        capStore.select(session.id); capStore.composer = "계속"; capStore.send()
        try check(capStore.queuedSubmissions.contains { $0.sessionID == session.id && $0.request == "계속" && $0.startNextRequested == true },
            "the owner's '계속' was not queued past the restart's failure")
        capStore.resumeInterruptedWork(now: now, writerAlive: { _ in false }, bootTime: boot)
        try check(store.load(id: session.id.uuidString) != nil,
            "the owner's queued '계속' was taken as a Stop and cancelled the repair it asked to continue")
        gate.open = true
        for _ in 0..<100 where !calls.contains(where: { $0.sessionID == session.id }) || !capStore.activeRuns.isEmpty {
            try await Task.sleep(for: .milliseconds(20))
        }
        try await idle(capStore)
        try check(calls.filter { $0.sessionID == session.id }.map(\.request) == ["계속"] && store.load(id: session.id.uuidString) != nil,
            "the queued '계속' did not run as the continuation of the surviving repair, or OS-1 resumed beside it")
    }

    // 3c. A resume OS-1 scheduled ends (here: an effects-uncertain failure):
    // the automatic readback after it no longer says OS-1 is resuming it.
    do {
        let folder = root.appendingPathComponent("resume-ended")
        let store = PendingOS1RepairStore(root: folder.appendingPathComponent("pending-os1-repairs"))
        let first = ChatMessage(role: .user, text: "로고 바꿔 resume-ended")
        let session = ConversationSession(title: "ended", workspace: root.path, messages: [first])
        var run = PendingSubmission(sessionID: session.id, userMessageID: first.id, request: first.text,
            provider: .auto, workspace: root.path, codexCapacity: 1, claudeCapacity: 1)
        run.preflightOnly = false
        try store.save(PendingOS1Repair(id: session.id.uuidString.lowercased(), conversationID: session.id.uuidString,
            submissionID: run.id.uuidString, ownerRequest: first.text, corrections: [], draftReport: "draft",
            sourceRoot: nil, startCommit: nil, now: now.addingTimeInterval(-600), pid: 999_997))
        try writeStore(folder, sessions: [session], inFlight: [run], savedAt: now.addingTimeInterval(-60))
        var calls: [PendingSubmission] = []
        let endedStore = SessionStore(storageRoot: folder, runOperation: { submission, context, _, _, _ in
            calls.append(submission)
            try await Task.sleep(for: .milliseconds(20))
            if submission.request == PendingOS1Repair.resumeRequest {
                throw RunnerError.backend(BackendFailureNotice(provider: "claude", sessionID: nil, blocker: .effectsUncertain,
                    dispatchStage: .dispatched, permissionProfile: "workspace_write"))
            }
            return try complete(submission, context)
        })
        endedStore.updateSettings { $0.parallelRunLimit = 4 }
        endedStore.resumeInterruptedWork(now: now, writerAlive: { _ in false }, bootTime: boot)
        try await idle(endedStore)
        let readbacks = calls.filter { $0.readOnlyReconciliation == true }
        try check(calls.first?.request == PendingOS1Repair.resumeRequest && readbacks.count == 1
            && readbacks[0].request.contains(BackendRecovery.pendingOS1RepairNote)
            && !readbacks[0].request.contains(BackendRecovery.pendingOS1RepairResumingNote),
            "after the scheduled resume ended, a readback still said OS-1 resumes the OS-1 part (\(calls.map { String($0.request.prefix(30)) }))")
    }

    // 3d. A follow-up the CLI would not continue the repair with (another
    // product's page), waiting in preflight at the restart: it is neither
    // re-run by itself nor resumed past (build 327 fix); it stays for the
    // owner, and the repair stays pending.
    do {
        let folder = root.appendingPathComponent("unrelated-follow-up")
        let store = PendingOS1RepairStore(root: folder.appendingPathComponent("pending-os1-repairs"))
        let first = ChatMessage(role: .user, text: "OS-1 사이드바 로고 바꿔")
        let again = ChatMessage(role: .user, text: "omaragi.com 랜딩 헤더도 같이 바꿔줘")
        let session = ConversationSession(title: "unrelated", workspace: root.path, messages: [first, again])
        let waiting = PendingSubmission(sessionID: session.id, userMessageID: again.id, request: again.text,
            provider: .auto, workspace: root.path, codexCapacity: 1, claudeCapacity: 1)
        try check(!OS1SelfReference.continuesPendingOS1Change(again.text), "fixture premise: the CLI would continue the repair with it")
        try store.save(PendingOS1Repair(id: session.id.uuidString.lowercased(), conversationID: session.id.uuidString,
            submissionID: UUID().uuidString, ownerRequest: first.text, corrections: [], draftReport: "draft",
            sourceRoot: nil, startCommit: nil, now: now.addingTimeInterval(-600), pid: 999_998))
        try writeStore(folder, sessions: [session], inFlight: [waiting], savedAt: now.addingTimeInterval(-60))
        var calls: [PendingSubmission] = []
        let unrelatedStore = SessionStore(storageRoot: folder, runOperation: { submission, context, _, _, _ in
            calls.append(submission)
            try await Task.sleep(for: .milliseconds(20))
            return try complete(submission, context)
        })
        unrelatedStore.updateSettings { $0.parallelRunLimit = 4 }
        for pass in 0..<2 {
            unrelatedStore.resumeInterruptedWork(now: now.addingTimeInterval(Double(pass) * 5), writerAlive: { _ in false }, bootTime: boot)
            try await idle(unrelatedStore)
        }
        let held = unrelatedStore.sessions.first { $0.id == session.id }!
        try check(calls.isEmpty && held.lastFailure?.id == waiting.id && store.load(id: session.id.uuidString)?.autoResumeAttempted == nil
            && store.load(id: session.id.uuidString)?.state == .interrupted
            && !held.messages.contains { $0.role == .system && ($0.text.contains("이어서") || $0.text.contains("resuming")) },
            "an unrelated follow-up was re-run by itself or OS-1 resumed past it (\(calls.map(\.request)))")
    }

    // 4. Two OS-1 repairs interrupted by one reboot: one resume runs, the
    // other parks behind its source lease. When the owner removes the parked
    // resume from the queue, nothing resumes it any more, so a later readback
    // in that conversation must not promise a resume (build 327 fix).
    do {
        let folder = root.appendingPathComponent("two-writers")
        let store = PendingOS1RepairStore(root: folder.appendingPathComponent("pending-os1-repairs"))
        var sessions: [ConversationSession] = [], runs: [PendingSubmission] = []
        for (offset, label) in ["A", "B"].enumerated() {
            let request = ChatMessage(role: .user, text: "OS-1 사이드바 고쳐 " + label)
            let session = ConversationSession(title: label, workspace: root.path, messages: [request])
            var run = PendingSubmission(sessionID: session.id, userMessageID: request.id, request: request.text,
                provider: .auto, workspace: root.path, codexCapacity: 1, claudeCapacity: 1)
            run.preflightOnly = false
            sessions.append(session); runs.append(run)
            try store.save(PendingOS1Repair(id: session.id.uuidString.lowercased(), conversationID: session.id.uuidString,
                submissionID: run.id.uuidString, ownerRequest: request.text, corrections: [], draftReport: "draft",
                sourceRoot: nil, startCommit: nil, now: now.addingTimeInterval(-600 - Double(offset)), pid: 999_980 + Int32(offset)))
        }
        try writeStore(folder, sessions: sessions, inFlight: runs, savedAt: now.addingTimeInterval(-60))
        final class StoreBox { var store: SessionStore? }
        let box = StoreBox()
        var calls: [PendingSubmission] = []
        let writers = SessionStore(storageRoot: folder, runOperation: { submission, context, _, _, _ in
            calls.append(submission)
            try await Task.sleep(for: .milliseconds(60))
            return try complete(submission, context)
        }, sourceAdmissionCheck: { submission, _ in
            // One OS-1 source writer at a time.
            box.store?.activeRuns.keys.contains { $0 != submission.sessionID } == true
        })
        box.store = writers
        writers.updateSettings { $0.parallelRunLimit = 4 }
        writers.resumeInterruptedWork(now: now, writerAlive: { _ in false }, bootTime: boot)
        try check(writers.activeRuns.count == 1, "both OS-1 source writers were admitted at once")
        let running = writers.activeRuns.keys.first!
        let parked = sessions.first { $0.id != running }!
        guard let parkedResume = writers.queuedSubmissions.first(where: { $0.sessionID == parked.id }) else {
            throw RunnerError.message("Restart resume: the second repair's resume did not park behind the first")
        }
        try check(parkedResume.request == PendingOS1Repair.resumeRequest && store.load(id: parked.id.uuidString)?.autoResumeAttempted == true,
            "the parked item is not the second repair's resume")
        writers.removeQueued(parkedResume.id)
        try await idle(writers)
        writers.resumeInterruptedWork(now: now.addingTimeInterval(5), writerAlive: { _ in false }, bootTime: boot)
        writers.resumeSourceWaitingSubmissions()
        try await idle(writers)
        try check(calls.count == 1 && calls[0].sessionID == running && calls[0].request == PendingOS1Repair.resumeRequest,
            "a removed parked resume ran, or a repair resumed twice (\(calls.count) runs)")
        writers.select(parked.id)
        writers.reconcileSelectedFailure()
        try await idle(writers)
        let readbacks = calls.filter { $0.sessionID == parked.id && $0.readOnlyReconciliation == true }
        try check(readbacks.count == 1 && readbacks[0].request.contains(BackendRecovery.pendingOS1RepairNote)
            && !readbacks[0].request.contains(BackendRecovery.pendingOS1RepairResumingNote),
            "after the owner removed the parked resume, a readback still promised OS-1 resumes the OS-1 part")
    }

    // 5. A model-free restage reply in a conversation bound to Codex or
    // Claude Code is OS-1's own control step, not a backend mismatch.
    for provider in [ProviderChoice.codex, .claude] {
        let folder = root.appendingPathComponent("restage-" + provider.rawValue)
        try FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
        let operationID = UUID().uuidString.lowercased()
        let output = "이 대화에서 멈춰 있던 OS-1 자체 수정(abc1234)을 모델 호출 없이 다시 스테이징했습니다."
        let receiptURL = folder.appendingPathComponent(operationID + ".json")
        try JSONSerialization.data(withJSONObject: ["schema": 1, "operation_id": operationID, "operation": "os1_repair_restage",
            "source_commit": String(repeating: "a", count: 40), "model_invoked": false, "result_sha256": appSHA256Hex(output)],
            options: [.sortedKeys]).write(to: receiptURL, options: .atomic)
        try FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: receiptURL.path)
        let restage = AppRunStep(sequence: 1, provider: "local", action: "os1_repair_restage", model: "os1-control", effort: "none",
            revasDisposition: "control_verified", sessionID: operationID, permissionProfile: "local_control", exitCode: 0,
            output: output, stderr: "", durationMS: 1,
            nativeRecord: AppNativeRecord(turnID: operationID, recordPath: receiptURL.path, persistence: "verified", desktopVisibility: "control_only"))
        let store = SessionStore(storageRoot: folder, runOperation: { submission, context, _, _, _ in
            AppRunSummary(status: "complete", steps: [restage], taskContext: try SessionHandoff.decode(context).taskContext)
        })
        let index = store.sessions.firstIndex { $0.id == store.selectedSessionID }!
        store.sessions[index].provider = provider
        store.composer = "아니 그래서 고치라니까?"
        store.send()
        try await idle(store)
        let session = store.sessions[index]
        try check(session.lastFailure == nil && !session.messages.contains { $0.text.contains("backend mismatch") }
            && session.messages.contains { $0.role == .assistant && $0.text == output },
            "a restage reply in a \(provider.rawValue) conversation was rejected as a backend mismatch")
    }

    // Nothing above may touch the owner's real pending repairs.
    try check(repairs.root.path.hasPrefix(root.path) && FileManager.default.fileExists(atPath: repairs.root.path),
        "the fixture's pending repairs were not under its own root")
    print("Restart resume self-test: interrupted repair resumed once, interrupted requests wait for the owner's retry, removed resumes promise nothing; model calls 0")
}

@MainActor
private func sidebarQueueSelfTest() async throws {
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-sidebar-queue-" + UUID().uuidString)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    var backend: [String] = []
    var calls = 0
    let store = SessionStore(storageRoot: root, nativePinOperation: { id, pinned, before in
        try await Task.sleep(for: .milliseconds(5))
        if let before, !backend.contains(before) { throw RunnerError.message("Missing move-before dependency") }
        if pinned {
            if !backend.contains(id) { backend.append(id) }
            backend = SidebarOrder.moving(id, before: before, in: backend)
        } else { backend.removeAll { $0 == id } }
        calls += 1
    })
    let aID = "00000000-0000-4000-8000-000000000011", bID = "00000000-0000-4000-8000-000000000012"
    let a = ConversationSession(title: "A", workspace: "/tmp", codexSessionID: aID)
    let b = ConversationSession(title: "B", workspace: "/tmp", codexSessionID: bID)
    store.sessions = [a, b]
    store.togglePin(a.id); store.togglePin(b.id); store.movePinned(a.id, before: b.id)
    await store.awaitSidebarMutations()
    guard backend == [aID, bID], calls == 3, store.sidebarSyncNotice == nil else {
        throw RunnerError.message("Sidebar queue: rapid pin/move dependency ordering failed")
    }
    store.togglePin(a.id); store.togglePin(a.id); store.movePinned(a.id, before: nil)
    await store.awaitSidebarMutations()
    guard backend == [bID, aID], calls == 6, store.sidebarSyncNotice == nil else {
        throw RunnerError.message("Sidebar queue: rapid unpin/repin/reorder failed")
    }
    let failed = SessionStore(storageRoot: root.appendingPathComponent("failed"), nativePinOperation: { _, _, _ in
        throw RunnerError.message("fixture backend unavailable")
    })
    failed.sessions = [a]; failed.togglePin(a.id)
    await failed.awaitSidebarMutations()
    guard failed.sidebarSyncNotice == "fixture backend unavailable", failed.sessions[0].pinnedAt != nil else {
        throw RunnerError.message("Sidebar queue: failure lost local intent or falsely confirmed")
    }
    let restarted = SessionStore(storageRoot: root.appendingPathComponent("failed"))
    guard restarted.sessions[0].pinnedAt != nil, restarted.sidebarSyncNotice != nil else {
        throw RunnerError.message("Sidebar queue: failed intent did not survive restart")
    }
    print("Sidebar queue: 4 checks passed; model calls 0; live backend writes 0")
}

@MainActor
private func sidebarSynchronizationSelfTest() throws {
    var checks = 0
    func check(_ value: Bool, _ label: String) throws {
        guard value else { throw RunnerError.message("Sidebar regression: " + label) }
        checks += 1
    }
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-sidebar-test-" + UUID().uuidString)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    let store = SessionStore(storageRoot: root)
    let codexA = "00000000-0000-4000-8000-000000000001", codexB = "00000000-0000-4000-8000-000000000002"
    let claudeA = "00000000-0000-4000-8000-000000000003", claudeB = "00000000-0000-4000-8000-000000000004"
    var a = ConversationSession(title: "A", workspace: "/tmp", codexSessionID: codexA, claudeSessionID: claudeA)
    var b = ConversationSession(title: "B", workspace: "/tmp", codexSessionID: codexB, claudeSessionID: claudeB)
    a.updatedAt = Date(timeIntervalSince1970: 10); b.updatedAt = a.updatedAt
    a.draft = "draft-a"; b.draft = "draft-b"
    store.sessions = [a, b]
    store.select(a.id); store.togglePin(a.id); store.togglePin(b.id)
    try check(store.filteredSessions.map(\.id) == [b.id, a.id], "new pin first")
    store.movePinned(a.id, before: b.id)
    try check(store.filteredSessions.map(\.id) == [a.id, b.id], "explicit move")
    store.select(b.id); store.showClodexHome()
    try check(store.filteredSessions.map(\.id) == [a.id, b.id], "selection cannot reorder")
    try check(store.composer == "draft-b", "draft ownership")
    store.flushPendingState()
    let reload = SessionStore(storageRoot: root)
    try check(reload.filteredSessions.map(\.id) == [a.id, b.id], "order survives restart")
    try check(reload.sessions.allSatisfy { $0.updatedAt == a.updatedAt && $0.messages.isEmpty }, "metadata only")
    func rows(_ provider: ProviderChoice, _ ids: [String]) -> [NativeSessionSummary] {
        ids.map { NativeSessionSummary(id: $0, provider: provider, title: $0, workspace: "/tmp",
            workspaceLabel: nil, updatedAt: Date(timeIntervalSince1970: 10), sourcePath: nil) }
    }
    reload.surface = .codex; reload.nativeSessions = rows(.codex, [codexB, codexA])
    try check(reload.filteredNativeSessions.map(\.id) == [codexA, codexB], "Codex projection matches pending OS1 order")
    reload.surface = .claude; reload.nativeSessions = rows(.claude, [claudeB, claudeA])
    try check(reload.filteredNativeSessions.map(\.id) == [claudeA, claudeB], "Claude local projection matches OS1 order")
    try check(reload.filteredNativeSessions.allSatisfy { $0.pinSyncNote?.contains("미반영") == true }, "unsupported Claude is not success")

    // A live native backend session is a presentation-only exception: it
    // floats above pinned rows, while the stored pin order remains intact.
    let runningRoot = root.appendingPathComponent("running-native")
    let runningStore = SessionStore(storageRoot: runningRoot)
    let runningA = ConversationSession(title: "Pinned A", workspace: "/tmp", provider: .codex,
        codexSessionID: "00000000-0000-4000-8000-000000000011")
    let runningB = ConversationSession(title: "Pinned B", workspace: "/tmp", provider: .codex,
        codexSessionID: "00000000-0000-4000-8000-000000000012")
    let runningC = ConversationSession(title: "Running C", workspace: "/tmp", provider: .codex,
        codexSessionID: "00000000-0000-4000-8000-000000000013")
    runningStore.sessions = [runningA, runningB, runningC]
    var nativeA = NativeSessionSummary(id: runningA.codexSessionID!, provider: .codex, title: "Pinned A",
        workspace: "/tmp", workspaceLabel: nil, updatedAt: Date(timeIntervalSince1970: 10), sourcePath: nil)
    nativeA.isPinned = true; nativeA.pinPosition = 0
    var nativeB = NativeSessionSummary(id: runningB.codexSessionID!, provider: .codex, title: "Pinned B",
        workspace: "/tmp", workspaceLabel: nil, updatedAt: Date(timeIntervalSince1970: 20), sourcePath: nil)
    nativeB.isPinned = true; nativeB.pinPosition = 1
    let nativeC = NativeSessionSummary(id: runningC.codexSessionID!, provider: .codex, title: "Running C",
        workspace: "/tmp", workspaceLabel: nil, updatedAt: Date(timeIntervalSince1970: 30), sourcePath: nil)
    runningStore.surface = .codex
    runningStore.nativeSessions = [nativeB, nativeA, nativeC]
    runningStore.activeRuns[runningC.id] = .init(
        submissionID: UUID(), started: Date(),
        activity: RuntimeActivity(.executing, provider: "codex", nativeSessionID: nativeC.id),
        provider: .codex)
    try check(runningStore.filteredNativeSessions.map(\.id) == [nativeC.id, nativeA.id, nativeB.id],
        "running native session floats above pinned rows")
    runningStore.activeRuns.removeValue(forKey: runningC.id)
    try check(runningStore.filteredNativeSessions.map(\.id) == [nativeA.id, nativeB.id, nativeC.id],
        "native pin order returns after run ends")
    runningStore.selectedSessionID = runningC.id
    try check(runningStore.filteredNativeSessions.map(\.id) == [nativeA.id, nativeB.id, nativeC.id],
        "linked current marker alone does not reorder an inactive native session")

    reload.toggleNativePin(claudeA)
    try check(reload.sessions.first(where: { $0.id == a.id })?.pinnedAt == nil, "native unpin updates linked OS1")
    reload.surface = .codex; reload.nativeSessions = rows(.codex, [codexB, codexA])
    try check(reload.filteredNativeSessions.first(where: { $0.id == codexA })?.isPinned == false, "unpin reaches other projection")
    reload.togglePin(a.id)
    reload.search = "A"
    reload.movePinned(a.id, before: nil)
    reload.search = ""
    try check(reload.filteredSessions.map(\.id) == [b.id, a.id], "OS1 search cannot erase hidden pin rank")
    reload.nativeSearch = codexA
    reload.moveNativePin(codexA, before: codexB)
    reload.nativeSearch = ""
    try check(reload.filteredNativeSessions.map(\.id) == [codexA, codexB], "native search preserves hidden pin rank")
    var late = ConversationSession(title: "Late", workspace: "/tmp")
    late.draft = "late-draft"
    reload.sessions.append(late)
    reload.togglePin(late.id)
    let lateID = "00000000-0000-4000-8000-000000000005"
    reload.recordNativeSession(.codex, id: lateID, conversationID: late.id)
    reload.nativeSessions.append(contentsOf: rows(.codex, [lateID]))
    try check(reload.filteredNativeSessions.first?.id == lateID && reload.filteredNativeSessions.first?.isPinned == true, "late backend binding inherits existing pin")
    reload.recordNativeSession(.codex, id: lateID, conversationID: late.id)
    try check(reload.filteredNativeSessions.first?.id == lateID && reload.sessions.first(where: { $0.id == late.id })?.draft == "late-draft", "duplicate binding preserves order and draft")
    reload.recordNativeSession(.codex, id: "not-a-uuid", conversationID: late.id)
    try check(reload.sessions.first(where: { $0.id == late.id })?.codexSessionID == lateID, "invalid native binding rejected")
    var duplicate = ConversationSession(title: "Duplicate", workspace: "/tmp", codexSessionID: codexA)
    duplicate.draft = "duplicate-draft"
    reload.sessions.append(duplicate)
    let oldPin = reload.sessions.first(where: { $0.id == a.id })?.pinnedAt
    reload.toggleNativePin(codexA)
    try check(reload.sessions.first(where: { $0.id == a.id })?.pinnedAt == oldPin && reload.sidebarSyncNotice?.contains("여러 OS1") == true, "ambiguous owner cannot mutate arbitrary conversation")
    let external = SessionStore(storageRoot: root.appendingPathComponent("external"))
    external.sessions = [a, b]
    external.applySidebarSnapshot(.codex, pins: [codexA: NativePinState(pinned: false, position: nil), codexB: NativePinState(pinned: false, position: nil)])
    external.applySidebarSnapshot(.codex, pins: [codexA: NativePinState(pinned: true, position: 1), codexB: NativePinState(pinned: true, position: 0)])
    try check(external.filteredSessions.map(\.id) == [b.id, a.id] && external.sessions.allSatisfy { $0.pinnedAt != nil }, "external Codex pins and order flow into OS1")
    external.surface = .claude; external.nativeSessions = rows(.claude, [claudeA, claudeB])
    try check(external.filteredNativeSessions.map(\.id) == [claudeB, claudeA], "external Codex order reaches Claude local projection")
    external.applySidebarSnapshot(.claude, pins: [claudeA: NativePinState(pinned: false, position: nil), claudeB: NativePinState(pinned: false, position: nil)])
    try check(external.sessions.allSatisfy { $0.pinnedAt != nil }, "stale Claude metadata cannot undo pending local presentation")
    external.applySidebarSnapshot(.codex, pins: [codexA: NativePinState(pinned: false, position: nil), codexB: NativePinState(pinned: true, position: 0)])
    try check(external.sessions.first(where: { $0.id == a.id })?.pinnedAt == nil && external.filteredNativeSessions.first(where: { $0.id == claudeA })?.isPinned == false, "new external Codex unpin supersedes old Claude local intent")
    try check(SidebarOrder.moving("a", before: "b", in: ["a", "b"]) == ["a", "b"], "move idempotence")
    try check(SidebarOrder.moving("a", before: "missing", in: ["a", "b"]) == ["a", "b"], "unknown target rejected")
    try check(SidebarOrder.moving("a", before: nil, in: ["a", "b"]) == ["b", "a"], "append")
    try check(SidebarOrder.replacingSubset(["b", "a"], in: ["x", "a", "y", "b"]) == ["x", "b", "y", "a"], "preserve unrelated pins")
    try check(SidebarOrder.key(provider: "claude", id: codexA) != SidebarOrder.key(provider: "codex", id: codexA), "provider isolation")
    let same = rows(.codex, [codexB, codexA]).sorted(by: sidebarNativeLess)
    try check(same.map(\.id) == [codexA, codexB], "stable tie order")
    // Exact native metadata schema: current Codex uses sections, not legacy is_pinned.
    let dbRoot = root.appendingPathComponent(".codex")
    try FileManager.default.createDirectory(at: dbRoot, withIntermediateDirectories: true)
    var db: OpaquePointer?
    guard sqlite3_open(dbRoot.appendingPathComponent("state_5.sqlite").path, &db) == SQLITE_OK else { throw SourceContextError.invalid }
    let sql = "CREATE TABLE threads (id TEXT, archived INTEGER, thread_section_id TEXT, section_position INTEGER);" +
        "INSERT INTO threads VALUES ('a',0,'\(NativeSidebar.codexPinnedSection)',2),('b',0,'\(NativeSidebar.codexPinnedSection)',1),('c',1,'\(NativeSidebar.codexPinnedSection)',0),('d',0,NULL,NULL);"
    guard sqlite3_exec(db, sql, nil, nil, nil) == SQLITE_OK else { sqlite3_close(db); throw SourceContextError.invalid }
    sqlite3_close(db)
    let snapshot = try NativeSidebar.read("codex", home: root)
    try check(snapshot["a"]?.pinned == true && snapshot["b"]?.position == 1 && snapshot["c"] == nil && snapshot["d"]?.pinned == false, "authoritative pin schema / archived exclusion")
    let claudeRoot = root.appendingPathComponent("Library/Application Support/Claude/claude-code-sessions")
    try FileManager.default.createDirectory(at: claudeRoot, withIntermediateDirectories: true)
    try JSONSerialization.data(withJSONObject: ["cliSessionId": claudeA, "isStarred": true])
        .write(to: claudeRoot.appendingPathComponent("local_fixture.json"))
    let claude = try NativeSidebar.read("claude", home: root)
    try check(claude[claudeA]?.pinned == true && claude[claudeA]?.position == nil, "Claude order remains unknown")
    let projects = root.appendingPathComponent("projects")
    try check(SidebarOrder.claudeConversationID(file: projects.appendingPathComponent("project/\(claudeA).jsonl"), projectsRoot: projects) == claudeA, "canonical Claude session")
    try check(SidebarOrder.claudeConversationID(file: projects.appendingPathComponent("project/\(claudeA)/subagents/agent-1.jsonl"), projectsRoot: projects) == nil, "child logs are not duplicate parent sessions")
    try check(SidebarOrder.claudeConversationID(file: projects.appendingPathComponent("project/backup/\(claudeA).jsonl"), projectsRoot: projects) == nil, "backups are not conversations")
    try check(SidebarOrder.claudeConversationID(file: root.appendingPathComponent("elsewhere/\(claudeA).jsonl"), projectsRoot: projects) == nil, "source boundary")
    print("Sidebar synchronization: \(checks) checks passed; model calls 0; live backend writes 0")
}

private struct BrowserToggleBar: View {
    let visible: Bool
    let toggle: () -> Void

    var body: some View {
        HStack {
            Spacer()
            Button(action: toggle) {
                Label(os1Tr("브라우저", "Browser"), systemImage: "sidebar.right")
            }
            .buttonStyle(.plain)
            .foregroundStyle(Theme.pink)
            .accessibilityLabel(os1Tr("오른쪽 브라우저 전환", "Toggle right-side browser"))
            .accessibilityValue(visible ? os1Tr("열림", "Open") : os1Tr("닫힘", "Closed"))
            .help(os1Tr("오른쪽 브라우저 열기/닫기", "Open or close the right-side browser"))
        }
        .padding(.horizontal, 14)
        .frame(height: RootChromeLayout.browserToggleHeight)
        // Only clickable right-side chrome stays below the transparent
        // titlebar. The non-interactive sidebar title can occupy that band.
        .padding(.top, RootChromeLayout.titlebarBand)
    }
}

private struct RootView: View {
    @ObservedObject var store: SessionStore
    @State private var profileNavigation = ProfileNavigationState()
    @StateObject private var identity = OS1IdentityModel()
    @StateObject private var profileUsage = ProfileUsageModel()
    @StateObject private var profileAccounts = BackendAccountsModel()
    @StateObject private var browser = OS1BrowserWorkspace()
    private var browserKey: String { store.selectedSessionID?.uuidString ?? "native-\(store.surface.rawValue)" }
    @State private var windowDropTargeted = false

    var body: some View {
        HStack(spacing: 0) {
            ProviderRail(store: store, governanceOpen: $profileNavigation.governanceOpen, identity: identity, usage: profileUsage) { destination in
                profileNavigation.select(destination)
            }
            Rectangle().fill(Theme.border).frame(width: 1)
            HSplitView {
            ZStack {
                // Keep the conversation mounted: toggling must not reset draft, scroll, queue or run.
                HStack(spacing: 0) {
                    if store.surface == .auto {
                        SessionSidebar(store: store)
                        Rectangle().fill(Theme.border).frame(width: 1)
                        VStack(spacing: 0) {
                            BrowserToggleBar(visible: browser.visible) { browser.visible.toggle() }
                            ConversationView(store: store)
                        }
                    } else {
                        NativeSessionBrowser(store: store, provider: store.surface,
                            browserVisible: browser.visible, toggleBrowser: { browser.visible.toggle() })
                    }
                }
                .opacity(profileNavigation.governanceOpen ? 0 : 1)
                .allowsHitTesting(!profileNavigation.governanceOpen)
                .accessibilityHidden(profileNavigation.governanceOpen)
                if profileNavigation.governanceOpen {
                    GovernanceMonitorView(active: store.activeRuns.values.map { run in
                        ExecutionRoutePresentation(activity: run.activity).governanceLine
                    }.sorted(), queued: store.queuedSubmissions.count, onClose: { profileNavigation.governanceOpen = false })
                    .onExitCommand { profileNavigation.governanceOpen = false }
                }
            }
            .frame(minWidth: 540, maxWidth: .infinity, maxHeight: .infinity)
            if browser.visible {
                OS1BrowserPanel(page: browser.page(browserKey), close: { browser.visible = false })
                    .id(browserKey)
            }
            }
        }
        .sheet(isPresented: $store.accountsOpen) { BackendAccountsView(store: store) }
        .sheet(item: $profileNavigation.sheet) { destination in
            VStack(spacing: 0) {
                HStack {
                    Label(destination.title, systemImage: destination.symbol).font(.headline)
                    Spacer()
                    Button { profileNavigation.sheet = nil } label: { Image(systemName: "xmark").frame(width: 24, height: 24) }
                        .buttonStyle(.plain).keyboardShortcut(.cancelAction)
                        .accessibilityLabel(os1Tr("닫기", "Close"))
                }.padding(18)
                Divider()
                switch destination {
                case .account: OS1IdentityPanel(model: identity).frame(width: 560, height: 550)
                case .usage: ProfileUsageView(model: profileUsage).frame(width: 640, height: 510)
                case .settings: OS1SettingsView(store: store, manageAccounts: { profileNavigation.sheet = .backends })
                case .backends:
                    ScrollView {
                        BackendAccountsPanel(model: profileAccounts, dark: true,
                            providers: store.appSettings.showCodex ? BackendAccounts.providers : ["claude"])
                            .padding(22)
                    }.frame(width: 600, height: 540)
                case .governance: EmptyView() // Routed without a sheet above.
                }
            }.background(ProfileStyle.surface).preferredColorScheme(.dark)
        }
        .task { await identity.restoreIfNeeded() }
        .onReceive(NotificationCenter.default.publisher(for: NSApplication.didBecomeActiveNotification)) { _ in
            Task { await identity.restoreIfNeeded(force: true) }
        }
        .environment(\.openURL, OpenURLAction { url in
            guard BrowserNavigation.url(url.absoluteString) != nil else { return .systemAction }
            browser.open(url, key: browserKey)
            return .handled
        })
        .frame(minWidth: 980, maxWidth: .infinity, minHeight: 680, maxHeight: .infinity)
        .background(Theme.background)
        // Files dropped anywhere in the window attach to the current
        // conversation's composer (Codex-style), not only on the input box.
        .overlay {
            if windowDropTargeted {
                ZStack {
                    Theme.pink.opacity(0.06)
                    RoundedRectangle(cornerRadius: 22).stroke(Theme.pink, lineWidth: 2).padding(10)
                    Label(os1Tr("여기에 놓으면 현재 대화에 첨부됩니다 · 이미지는 미리보기, 파일은 칩",
                                "Drop to attach to this conversation · images as previews, files as chips"), systemImage: "tray.and.arrow.down.fill")
                        .font(.system(size: 15, weight: .semibold)).foregroundStyle(Theme.text)
                        .padding(14).background(Theme.panelRaised, in: RoundedRectangle(cornerRadius: 12))
                }
                .allowsHitTesting(false)
                .transition(.opacity)
            }
        }
        .animation(.easeInOut(duration: 0.12), value: windowDropTargeted)
        .onDrop(of: [UTType.fileURL], isTargeted: $windowDropTargeted) { providers in
            store.handleComposerDrop(providers)
        }
        .ignoresSafeArea()
        .task {
            // The rail's sign-in state follows whatever the governance panel
            // or the settings sheet changed, and is verified once at launch.
            store.observeAccountChanges()
            await store.refreshAccounts()
        }
        .task {
            while !Task.isCancelled {
                await store.refreshSidebarMetadata()
                try? await Task.sleep(for: .seconds(3))
            }
        }
        .task {
            // Independent of the sidebar poll above, so a stalled backend read
            // can never delay a queued recovery or a staged self-update.
            while !Task.isCancelled {
                store.runMaintenanceTick()
                try? await Task.sleep(for: .seconds(3))
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSApplication.willTerminateNotification)) { _ in store.flushPendingState() }
        .alert("OS-1 CLODEX", isPresented: Binding(
            get: { store.alertMessage != nil },
            set: { if !$0 { store.alertMessage = nil } }
        )) {
            Button("OK", role: .cancel) { store.alertMessage = nil }
        } message: {
            Text(store.alertMessage ?? "")
        }
        .alert(item: $store.nativeAppApproval) { request in
            Alert(title: Text(os1Tr("네이티브 에이전트 사용 승인", "Approve native agent use")),
                message: Text(request.message + os1Tr("\n현재 네이티브 실행에만 적용됩니다. 결제·약관·비밀번호 입력 승인이 아닙니다.",
                                                      "\nApplies only to the current native run. This does not approve payments, terms or password entry.")),
                primaryButton: .default(Text(os1Tr("이 실행에만 허용", "Allow for this run only"))) {
                    if store.activeRuns.values.contains(where: { $0.submissionID == request.submissionID }) {
                        try? NativeAppApproval.respond(request, approved: true)
                    }
                },
                secondaryButton: .cancel(Text(os1Tr("거절", "Deny"))) {
                    try? NativeAppApproval.respond(request, approved: false)
                })
        }
    }
}

/// The rail is a single-choice control over `store.surface`: Clodex home,
/// Codex or Claude. Only the chosen surface may produce the highlighted
/// treatment. Whether the conversation has a recorded backend session
/// (`linked`) and which backend ran last (`active`) are independent facts with
/// their own small indicators — deriving any part of the highlight from them
/// made the permanently linked/last-used backend look selected forever, which
/// is why Claude appeared chosen no matter what the user clicked.
private struct RailItemAppearance: Equatable {
    let fillOpacity: Double
    let strokeOpacity: Double
    let strokeWidth: CGFloat
    let contentOpacity: Double
    let showsSelectionMarker: Bool
    /// Only a selected item is allowed to paint its provider accent; an
    /// unselected item stays neutral so two items cannot claim the same color.
    let usesAccent: Bool

    static func resolve(selected: Bool, linked: Bool) -> RailItemAppearance {
        guard selected else {
            return RailItemAppearance(
                fillOpacity: linked ? 0.045 : 0.022,
                strokeOpacity: linked ? 0.20 : 0.11,
                strokeWidth: 1,
                contentOpacity: linked ? 0.58 : 0.38,
                showsSelectionMarker: false,
                usesAccent: false)
        }
        // Deliberately identical for linked and unlinked: pressing CODEX must
        // look chosen even when this conversation has no Codex session yet.
        // The owner asked for the leading marker and the loud outline to go:
        // a filled accent tile plus full-strength content is enough to show
        // which surface is chosen, with nothing sticking out on the left.
        return RailItemAppearance(
            fillOpacity: 0.26,
            strokeOpacity: 0,
            strokeWidth: 0,
            contentOpacity: 1,
            showsSelectionMarker: false,
            usesAccent: true)
    }
}

private struct RailSelectionBackground: View {
    let accent: Color
    let appearance: RailItemAppearance

    var body: some View {
        let shape = RoundedRectangle(cornerRadius: Theme.radiusControl, style: .continuous)
        ZStack {
            shape.fill((appearance.usesAccent ? accent : Color.white).opacity(appearance.fillOpacity))
            shape.stroke((appearance.usesAccent ? accent : Color.white).opacity(appearance.strokeOpacity),
                lineWidth: appearance.strokeWidth)
        }
        .allowsHitTesting(false)
    }
}

/// The OS-1 tile is optically centered against the native Codex and Claude
/// cards. Its visual offset intentionally does not participate in `VStack`
/// layout, so those two backend cards retain their measured positions.
private enum ProviderRailLayout {
    static let itemWidth: CGFloat = 58
    static let homeHeight: CGFloat = 68
    static let backendHeight: CGFloat = 80
    static let stackSpacing: CGFloat = 22
    static let railTopPadding: CGFloat = 38
    // Measured on the owner's screenshot (2x): OS-1 bottom → Codex top was
    // 59 px while Codex bottom → Claude top was 43 px — an 8 pt step, because
    // the home button carried 8 pt of bottom padding on top of the stack
    // spacing. That padding now sits ABOVE the button: Codex and Claude keep
    // their exact coordinates and OS-1 moves down by 8 pt, so every gap on
    // the rail is one stack spacing.
    static let homeTopPadding: CGFloat = 8
    /// Painted top of each tile, in rail coordinates.
    static var homeTop: CGFloat { railTopPadding + homeTopPadding }
    static var codexTop: CGFloat { homeTop + homeHeight + stackSpacing }
    static var claudeTop: CGFloat { codexTop + backendHeight + stackSpacing }
}

private struct ProviderRail: View {
    @ObservedObject var store: SessionStore
    @Binding var governanceOpen: Bool
    @ObservedObject var identity: OS1IdentityModel
    @ObservedObject var usage: ProfileUsageModel
    var selectProfileDestination: (ProfileDestination) -> Void
    @State private var profileMenuOpen = false

    init(store: SessionStore, governanceOpen: Binding<Bool> = .constant(false),
         identity: OS1IdentityModel? = nil, usage: ProfileUsageModel? = nil,
         selectProfileDestination: @escaping (ProfileDestination) -> Void = { _ in }) {
        self.store = store
        self._governanceOpen = governanceOpen
        self.identity = identity ?? OS1IdentityModel()
        self.usage = usage ?? ProfileUsageModel()
        self.selectProfileDestination = selectProfileDestination
    }

    // The rail is assembled from named sub-views. Written as one expression it
    // took the type-checker over a second here and blew the compiler's budget
    // on the slower release runner ("unable to type-check this expression in
    // reasonable time"), so the layout below must stay split.
    var body: some View {
        VStack(spacing: ProviderRailLayout.stackSpacing) {
            homeButton

            // Codex disappears entirely when switched off in Settings — the
            // runtime refuses to route to it too, so the rail stays truthful.
            ForEach(visibleProviders) { provider in
                backendTile(provider)
            }

            Spacer()

            profileControls
        }
        .padding(.top, ProviderRailLayout.railTopPadding)
        .padding(.bottom, 24)
        .frame(width: 78)
        .background(Color.black.opacity(0.74))
    }

    private var visibleProviders: [ProviderChoice] {
        [ProviderChoice.codex, ProviderChoice.claude].filter {
            $0 != .codex || store.appSettings.showCodex
        }
    }

    private var homeButton: some View {
        let homeAppearance = RailItemAppearance.resolve(selected: store.surface == .auto, linked: true)
        return Button { store.showClodexHome() } label: {
            // No plate behind the logo (owner 2026-10-05): the ring fills the
            // tile and the rail shows through it; selection reads from content
            // strength alone. 55 + 3 + the label stays inside homeHeight, so
            // Codex and Claude keep their coordinates.
            VStack(spacing: 3) {
                OmarAGILogo(size: 55)
                    .opacity(homeAppearance.contentOpacity)
                Text("OS-1")
                    .font(.system(size: 7, weight: .bold))
                    .tracking(1.1)
                    .foregroundStyle(Color.white.opacity(homeAppearance.contentOpacity))
            }
            .frame(width: ProviderRailLayout.itemWidth, height: ProviderRailLayout.homeHeight)
            .contentShape(RoundedRectangle(cornerRadius: Theme.radiusControl, style: .continuous))
        }
        .buttonStyle(.plain)
        .help("Clodex home")
        .accessibilityLabel("Clodex home")
        .accessibilityValue(store.surface == .auto ? os1Tr("선택됨", "Selected") : os1Tr("선택 안 됨", "Not selected"))
        // Only OS-1 moves; Codex and Claude stay on the reference grid.
        .padding(.top, ProviderRailLayout.homeTopPadding)
    }

    private func backendTile(_ provider: ProviderChoice) -> some View {
        let account = store.activeAccount(for: provider)
        // Never claim a backend is signed out before its own status
        // command has answered: an unverified account reads as fine.
        let verified = account.map { $0.verifiedAt == nil || $0.signedIn } ?? true
        let linked: Bool = provider == .codex
            ? store.selectedSession?.codexSessionID != nil
            : store.selectedSession?.claudeSessionID != nil
        return BackendStatus(
            provider: provider,
            selected: store.surface == provider,
            active: store.selectedSession?.lastProvider == provider.rawValue,
            linked: linked,
            signedIn: verified,
            signingIn: store.accountBusy == provider.rawValue,
            accountLabel: account?.label,
            surfaceBadge: store.routedSurface(for: provider)?.railBadge,
            disabled: false
        ) {
            // A signed-out backend cannot run anything, so the tile
            // offers the sign-in instead of an empty session list.
            if !verified { store.accountsOpen = true } else { store.inspectBackend(provider) }
        }
        .contextMenu {
            surfaceMenu(for: provider)
            accountMenu(for: provider)
        }
    }

    /// The tile is one account; this picks which of its two ways to spend it
    /// runs. Same shape the ChatGPT app presents: one sign-in, Codex or chat
    /// chosen inside it. Placed above the account list because it decides what
    /// the tile does, not merely who it signs in as.
    @ViewBuilder
    private func surfaceMenu(for provider: ProviderChoice) -> some View {
        if let backend = ProviderSurface.Backend(rawValue: provider.rawValue) {
            let current = store.appSettings.surface(for: backend)
            ForEach(backend.surfaces, id: \.rawValue) { surface in
                Button {
                    store.chooseSurface(surface, for: backend)
                } label: {
                    Label(surface.choiceTitle, systemImage: surface == current ? "checkmark" : "")
                }
                .disabled(surface == current)
            }
            Text(current.executionLine)
            Divider()
        }
    }

    @ViewBuilder
    private func accountMenu(for provider: ProviderChoice) -> some View {
        ForEach(store.accounts(for: provider)) { row in
            let isActive = store.accountBook.active[provider.rawValue] == row.id
            Button {
                Task { await store.useAccount(provider: provider.rawValue, id: row.id) }
            } label: {
                Label(row.label + (row.signedIn ? "" : os1Tr(" (로그아웃)", " (signed out)")),
                      systemImage: isActive ? "checkmark" : "")
            }
            .disabled(isActive)
        }
        Divider()
        Button(os1Tr("\(provider.title) 계정…", "\(provider.title) accounts…")) { store.accountsOpen = true }
    }

    private var profileControls: some View {
        VStack(spacing: 8) {
            Button { selectProfileDestination(.settings) } label: {
                Image(systemName: "gearshape").font(.system(size: 19, weight: .regular))
                    .foregroundStyle(Color.white.opacity(0.65)).frame(width: 44, height: 32).contentShape(Rectangle())
            }
            .buttonStyle(.plain).help(os1Tr("설정", "Settings"))
            .accessibilityLabel(os1Tr("설정", "Settings")).accessibilityIdentifier("os1.rail.settings")
            Button { profileMenuOpen.toggle() } label: {
                ProfileAvatar(profile: identity.profile, size: 36)
                    .frame(width: 50, height: 50)
                    .background(Color.white.opacity(profileMenuOpen ? 0.12 : 0.05), in: RoundedRectangle(cornerRadius: 14))
                    .overlay(alignment: .bottomTrailing) {
                        if identity.busy { ProgressView().controlSize(.mini).padding(2) }
                    }
                    .contentShape(RoundedRectangle(cornerRadius: 14))
            }
            .buttonStyle(.plain)
            .help(os1Tr("프로필 · 사용량 · 계정", "Profile · usage · accounts"))
            .accessibilityLabel(os1Tr("프로필 메뉴", "Profile menu"))
            .accessibilityIdentifier("os1.rail.profile")
            .accessibilityValue(profileMenuOpen ? os1Tr("열림", "Open") : os1Tr("닫힘", "Closed"))
            .popover(isPresented: $profileMenuOpen, arrowEdge: .trailing) {
                ProfileMenuView(profile: identity.profile, busy: identity.busy,
                                usage: usage.loaded ? usage.summary : nil, select: { destination in
                    profileMenuOpen = false
                    DispatchQueue.main.async { selectProfileDestination(destination) }
                }, signOut: { identity.signOut(); profileMenuOpen = false })
                .onExitCommand { profileMenuOpen = false }
            }
            .task(id: profileMenuOpen) { if profileMenuOpen { await usage.refresh() } }
        }
    }
}

private struct BackendStatus: View {
    let provider: ProviderChoice
    let selected: Bool
    let active: Bool
    let linked: Bool
    var signedIn: Bool = true
    var signingIn: Bool = false
    var accountLabel: String?
    /// A non-default route replaces the primary tile name. Never put GPT on
    /// top of a second CODEX identity, or Claude on top of Claude Code.
    var surfaceBadge: String? = nil
    let disabled: Bool
    let action: () -> Void

    private var appearance: RailItemAppearance {
        RailItemAppearance.resolve(selected: selected, linked: linked)
    }

    /// Sign-in outranks session state: a signed-out backend cannot run, so
    /// "NO SESSION" would send the owner looking in the wrong place.
    var stateText: String {
        if signingIn { return "SIGNING IN" }
        if !signedIn { return "SIGN IN" }
        return linked ? "OPEN" : "NO SESSION"
    }

    private var stateColor: Color {
        if signingIn { return Theme.pink }
        if !signedIn { return Theme.amber }
        return linked ? Theme.green : Theme.muted
    }

    var body: some View {
        Button(action: action) {
            VStack(spacing: 9) {
                ProviderBrandIcon(provider: provider, size: 28)
                    .opacity(appearance.contentOpacity)
                Text(surfaceBadge ?? provider.title)
                    .font(.system(size: 7, weight: .bold))
                    .tracking(1.1)
                    .lineLimit(1)
                    .minimumScaleFactor(0.8)
                // A backend that is signed out cannot run anything, so that is
                // what the tile says; the session state only matters once it can.
                HStack(spacing: 3) {
                    Circle().fill(stateColor).frame(width: 4, height: 4)
                    Text(stateText)
                        .font(.system(size: 5.5, weight: .bold))
                        .lineLimit(1)
                        .minimumScaleFactor(0.65)
                }
            }
            .foregroundStyle(Color.white.opacity(appearance.contentOpacity))
            .frame(width: ProviderRailLayout.itemWidth, height: ProviderRailLayout.backendHeight)
            .background(RailSelectionBackground(accent: provider.tint, appearance: appearance))
            .overlay(alignment: .topTrailing) {
                // "Last backend that ran", never a selection signal: a neutral
                // dot so it cannot be read as this card being the chosen one.
                if active && !selected {
                    Circle()
                        .fill(Color.white.opacity(0.45))
                        .frame(width: 5, height: 5)
                        .padding(5)
                }
            }
            .contentShape(RoundedRectangle(cornerRadius: Theme.radiusControl, style: .continuous))
        }
        .buttonStyle(.plain)
        .disabled(disabled)
        .help(linked
            ? "Show this conversation's recorded \(provider.title) session inside Clodex"
            : "No \(provider.title) session is recorded for this Clodex conversation")
        .accessibilityLabel((surfaceBadge ?? provider.title) + " routing selection")
        // The routed surface travels with the selection state: one account with
        // two ways to spend it, so "selected" alone does not say which one runs.
        .accessibilityValue((selected ? os1Tr("선택됨", "Selected") : os1Tr("선택 안 됨", "Not selected"))
            + (surfaceBadge.map { " · " + $0 } ?? ""))
    }
}

/// Regression for the rail reading as "Claude is always chosen". The two
/// invariants that failed before: selection had to survive an unlinked
/// backend, and no unselected item may be painted louder than the selected
/// one. Pure state only — no model calls and no backend writes.
@MainActor
/// Renders the production rail and measures the painted tiles the way the
/// owner did on his screenshot: down the centre column, OS-1's filled tile
/// ends, Codex's outline begins, and so on. Both gaps must be the same.
private func railPixelGapSelfTest(surfacesBadged: Bool = false) throws -> [(Int, Int)] {
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-rail-pixels-" + UUID().uuidString, isDirectory: true)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    let store = SessionStore(storageRoot: root, nativeSessionOpener: { _ in false })
    // The same rail, once plain and once with both tiles routed to their
    // alternative surface, so the badge is proven not to move the geometry.
    if surfacesBadged {
        store.updateSettings {
            $0.setSurface(.chatgpt, for: .openAI)
            $0.setSurface(.claudeChat, for: .anthropic)
        }
    }
    guard let index = store.selectedIndex else { throw RunnerError.message("Provider rail regression: no fixture conversation") }
    // Both backends linked so their outlines are visible at 2x, as on the
    // owner's rail; OS-1 selected as on his screenshot.
    store.sessions[index].claudeSessionID = "bae5987c-3fd1-4d08-a85c-6d9c18d41e86"
    store.sessions[index].codexSessionID = "01a0a960-601d-7511-8e3c-11e48e40395a"
    store.surface = .auto
    // Tall enough that the rail's Spacer absorbs the slack; a short frame
    // centres the overflowing stack and shifts every absolute coordinate.
    let content = ProviderRail(store: store).frame(width: 78, height: 640).background(Theme.background).environment(\.colorScheme, .dark)
    let view = NSHostingView(rootView: content)
    view.frame = NSRect(x: 0, y: 0, width: 78, height: 640)
    RunLoop.main.run(until: Date().addingTimeInterval(0.05))
    view.layoutSubtreeIfNeeded()
    guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { throw RunnerError.message("Provider rail regression: no bitmap") }
    view.cacheDisplay(in: view.bounds, to: bitmap)
    let scale = CGFloat(bitmap.pixelsWide) / view.bounds.width
    let x = bitmap.pixelsWide / 2
    func lit(_ y: Int) -> Bool {
        guard y >= 0, y < bitmap.pixelsHigh, let c = bitmap.colorAt(x: x, y: y) else { return false }
        return (c.redComponent + c.greenComponent + c.blueComponent) / 3 > 0.075
    }
    func check(_ value: Bool, _ label: String) throws {
        guard value else { throw RunnerError.message("Provider rail pixels: " + label) }
    }
    // Lit runs down the centre column, exactly as measured on the owner's
    // screenshot: [OS-1 fill] gap [Codex outline … outline] gap [Claude outline …].
    var runs: [(Int, Int)] = [], start = 0, inRun = false
    for y in 0..<bitmap.pixelsHigh {
        let on = lit(y)
        if on, !inRun { start = y; inRun = true }
        if !on, inRun { runs.append((start, y)); inRun = false }
    }
    // OS-1 paints no plate (owner 2026-10-05), so its tile is its frame and
    // the ring must fill it: lit from the tile's top edge down through 55 pt.
    let home = (Int(ProviderRailLayout.homeTop * scale),
                Int((ProviderRailLayout.homeTop + ProviderRailLayout.homeHeight) * scale))
    let logoRuns = runs.filter { $0.0 >= home.0 - 1 && $0.1 <= home.1 + 1 }
    guard let ringTop = logoRuns.first?.0 else { throw RunnerError.message("Provider rail pixels: OS-1 logo not painted inside its tile") }
    try check(CGFloat(ringTop - home.0) <= 2 * scale, "OS-1 ring starts \(ringTop - home.0)px below its tile top")
    try check(logoRuns.contains { abs(CGFloat($0.1 - ringTop) - 55 * scale) <= 2 * scale },
        "OS-1 ring does not span 55 pt: \(logoRuns)")
    guard let codexTop = runs.first(where: { $0.0 > home.1 })?.0 else { throw RunnerError.message("Provider rail pixels: Codex outline not found") }
    let codexBottomExpected = codexTop + Int(ProviderRailLayout.backendHeight * scale)
    guard let codexBottom = runs.first(where: { abs($0.1 - codexBottomExpected) <= 3 })?.1 else {
        throw RunnerError.message("Provider rail pixels: Codex bottom outline not near \(codexBottomExpected)px")
    }
    guard let claudeTop = runs.first(where: { $0.0 > codexBottom + 2 })?.0 else { throw RunnerError.message("Provider rail pixels: Claude outline not found") }
    let gap1 = codexTop - home.1, gap2 = claudeTop - codexBottom
    try check(abs(gap1 - gap2) <= 1, "painted gaps differ: OS-1→Codex \(gap1)px, Codex→Claude \(gap2)px")
    try check(abs(CGFloat(gap1) - ProviderRailLayout.stackSpacing * scale) <= 2, "OS-1→Codex gap \(gap1)px is not one stack spacing")
    // Codex and Claude keep their pre-change coordinates relative to the rail top.
    let expectedCodexTop = Int(ProviderRailLayout.codexTop * scale)
    try check(abs(codexTop - expectedCodexTop) <= 2, "Codex outline at \(codexTop)px, expected \(expectedCodexTop)px")
    return [home, (codexTop, codexBottom), (claudeTop, claudeTop)]
}

@MainActor
private func railSelectionSelfTest() throws {
    var checks = 0
    func check(_ value: Bool, _ label: String) throws {
        guard value else { throw RunnerError.message("Provider rail regression: " + label) }
        checks += 1
    }

    for surface in ProviderChoice.allCases {
        let highlighted = [surface == .auto, surface == .codex, surface == .claude].filter { $0 }
        try check(highlighted.count == 1, "surface \(surface.rawValue) must highlight exactly one rail item")
    }

    try check(RailItemAppearance.resolve(selected: true, linked: true)
        == RailItemAppearance.resolve(selected: true, linked: false),
        "a chosen backend with no recorded session must look identically chosen")
    try check(RailItemAppearance.resolve(selected: false, linked: true)
        != RailItemAppearance.resolve(selected: true, linked: true),
        "linked-but-unselected must be distinguishable from selected")
    // Geometry by construction: every gap on the rail is one stack spacing,
    // and Codex/Claude sit exactly where they did before OS-1 moved.
    let os1ToCodexGap = ProviderRailLayout.codexTop - (ProviderRailLayout.homeTop + ProviderRailLayout.homeHeight)
    let codexToClaudeGap = ProviderRailLayout.claudeTop - (ProviderRailLayout.codexTop + ProviderRailLayout.backendHeight)
    try check(os1ToCodexGap == codexToClaudeGap && os1ToCodexGap == ProviderRailLayout.stackSpacing,
        "OS-1 → Codex gap (\(os1ToCodexGap)) must equal Codex → Claude gap (\(codexToClaudeGap))")
    try check(ProviderRailLayout.codexTop == 38 + 68 + 8 + 22 && ProviderRailLayout.claudeTop == ProviderRailLayout.codexTop + 80 + 22,
        "Codex and Claude must keep their pre-change coordinates")
    try check(ProviderRailLayout.itemWidth == 58 && ProviderRailLayout.homeHeight == 68
        && ProviderRailLayout.backendHeight == 80,
        "Codex and Claude reference-card geometry must remain unchanged")
    // Measured twice: a badged rail must paint its tiles on exactly the same
    // pixels as a plain one, because the badge is an overlay.
    let plainTiles = try railPixelGapSelfTest()
    let badgedTiles = try railPixelGapSelfTest(surfacesBadged: true)
    try check(plainTiles.count == badgedTiles.count
        && zip(plainTiles, badgedTiles).allSatisfy { abs($0.0 - $1.0) <= 1 && abs($0.1 - $1.1) <= 1 },
        "a surface badge moved the painted rail tiles: \(plainTiles) vs \(badgedTiles)")
    try sidebarHeaderPixelSelfTest()

    for linked in [true, false] {
        let quiet = RailItemAppearance.resolve(selected: false, linked: linked)
        let loud = RailItemAppearance.resolve(selected: true, linked: !linked)
        // The owner removed the leading marker and the outline, so selection
        // now reads from fill and content strength alone — which must still
        // beat any unselected item, linked or not.
        try check(quiet.fillOpacity < loud.fillOpacity
            && quiet.contentOpacity < loud.contentOpacity
            && !quiet.usesAccent && loud.usesAccent,
            "unselected(linked=\(linked)) outranked the selected item")
        try check(!loud.showsSelectionMarker && loud.strokeOpacity == 0 && loud.strokeWidth == 0,
            "the selected rail item must not paint a leading marker or outline")
    }

    let root = FileManager.default.temporaryDirectory
        .appendingPathComponent("os1-rail-selection-" + UUID().uuidString, isDirectory: true)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    let store = SessionStore(storageRoot: root, nativeSessionOpener: { _ in false })
    guard let index = store.selectedIndex else { throw RunnerError.message("Provider rail regression: no fixture conversation") }
    // Reproduces the reported state: Claude recorded and last active, Codex not.
    store.sessions[index].claudeSessionID = "bae5987c-3fd1-4d08-a85c-6d9c18d41e86"
    store.sessions[index].codexSessionID = nil
    store.sessions[index].lastProvider = "claude"
    try check(store.surface == .auto, "a new conversation opens on Clodex home")
    store.surface = .codex
    try check(store.surface == .codex && store.surface != .claude,
        "choosing Codex must leave Claude unselected even though Claude is the linked/last backend")
    store.showClodexHome()
    try check(store.surface == .auto, "the OS-1 ring must return to the Clodex home surface")
    store.inspectBackend(.auto)
    try check(store.surface == .auto, "auto is not a browsable backend surface")

    // Accounts: a signed-out backend must say so on its own tile, and a
    // fixture store must never reach the owner's real account file.
    var book = BackendAccounts.normalized(BackendAccountBook())
    for position in book.accounts.indices {
        book.accounts[position].signedIn = true
        book.accounts[position].verifiedAt = Date()
    }
    try check(store.activeAccount(for: .claude)?.isDefault == true,
        "a fresh Mac shows the provider's own sign-in as the active account")
    try check(store.accounts(for: .auto).isEmpty, "the OS-1 home is not a signed-in backend")
    let added = UUID().uuidString.lowercased()
    book.accounts.append(BackendAccount(id: added, provider: "claude", label: "회사 계정",
        homePath: BackendAccounts.accountsRoot().appendingPathComponent("claude/\(added)").path,
        signedIn: false, verifiedAt: Date()))
    book.active["claude"] = added
    store.accountBook = book
    try check(store.accounts(for: .claude).count == 2, "both Claude accounts are listed")
    try check(store.activeAccount(for: .claude)?.signedIn == false && store.activeAccount(for: .codex)?.signedIn == true,
        "each provider reports its own account state")
    let signedOutTile = BackendStatus(provider: .claude, selected: false, active: false, linked: true,
        signedIn: false, signingIn: false, accountLabel: "회사 계정", disabled: false) {}
    let signedInTile = BackendStatus(provider: .claude, selected: false, active: false, linked: true,
        signedIn: true, signingIn: false, accountLabel: "회사 계정", disabled: false) {}
    try check(signedOutTile.stateText == "SIGN IN" && signedInTile.stateText == "OPEN",
        "a signed-out backend must offer the sign-in instead of a session state")
    try check(BackendStatus(provider: .codex, selected: false, active: false, linked: false,
        signedIn: true, signingIn: true, accountLabel: nil, disabled: false) {}.stateText == "SIGNING IN",
        "a running sign-in is visible on the tile")
    // Changing accounts goes through the runtime, so a fixture store must not
    // touch the owner's real account file: its book only changes when assigned.
    try check(store.accountBook.active["claude"] == added && store.accountNotice == nil && store.accountBusy == nil,
        "a fixture store holds only the assigned book and reports no failure")
    try check(BackendAccounts.load() != book, "the fixture book was never written to the owner's account file")

    // The account list is one screen: governance and settings render the same
    // panel from the same model, so they can never disagree.
    let panelModel = BackendAccountsModel()
    let governancePanel = BackendAccountsPanel(model: panelModel, dark: true, readOnly: true)
    let settingsPanel = BackendAccountsPanel(model: panelModel)
    try check(governancePanel.providers == settingsPanel.providers
        && governancePanel.providers == BackendAccounts.providers,
        "both account screens list the same providers")
    try check(governancePanel.readOnly && !settingsPanel.readOnly,
        "the design-time governance preview must not offer a sign-in")
    let codexOnly = BackendAccountsPanel(model: panelModel, providers: ["claude"])
    try check(codexOnly.providers == ["claude"], "turning a backend off removes it from the account list")
    try check(BackendAccountsStyle.title("claude") == "Claude Code"
        && BackendAccountsStyle.organization("claude") == "Anthropic"
        && BackendAccountsStyle.organization("codex") == "OpenAI",
        "each provider is named by its own organization")
    try check(BackendAccountsStyle.initial("  회사 계정 ") == "회"
        && BackendAccountsStyle.initial("work") == "W",
        "an account shows one letter, the way an account list does")

    // ---- Surface selection on the rail --------------------------------
    // One tile is one account with two ways to spend it. The choice must be
    // visible, persisted, routed, and unable to cross to the other account.
    let openAI = ProviderSurface.Backend.openAI
    let anthropic = ProviderSurface.Backend.anthropic
    try check(store.routedSurface(for: .codex) == .codex && store.routedSurface(for: .claude) == .claude,
        "an untouched rail routes each tile to the backend OS-1 can actually execute")
    try check(store.routedSurface(for: .auto) == nil, "the OS-1 home is not a backend surface")
    try check(store.routedSurface(for: .codex)?.railBadge == nil
        && store.routedSurface(for: .claude)?.railBadge == nil,
        "an unchanged tile carries no badge, so the rail looks exactly as it did")

    store.chooseSurface(.chatgpt, for: openAI)
    try check(store.appSettings.surface(for: openAI) == .chatgpt, "the ChatGPT choice persists in settings")
    try check(store.routedSurface(for: .codex)?.railBadge != nil, "a changed tile says so on the rail")
    // Pinning matters: on `auto` the router could send the turn to the other
    // account and the chosen surface would never fire. So the choice pins the
    // conversation to that tile. It does not change which pane is on screen.
    try check(store.selectedSession?.provider == .codex,
        "choosing what a tile does pins the next turn to that tile")
    try check(store.appSettings.surface(for: anthropic) == .claude,
        "the OpenAI tile's surface must not move the Anthropic tile")

    // The dispatched `--provider` follows the tile's surface, and a stale or
    // foreign stored value falls back to the tile's executor instead of
    // spending the wrong account.
    var handoff = PendingSubmission(sessionID: store.sessions[index].id, userMessageID: UUID(),
        request: "x", provider: .codex, workspace: "/tmp", codexCapacity: 1, claudeCapacity: 1)
    handoff.surfaceRaw = store.appSettings.surface(for: openAI).rawValue
    try check(handoff.runtimeSurface == "chatgpt", "a ChatGPT tile dispatches --provider chatgpt")
    handoff.surfaceRaw = "claude-chat"
    try check(handoff.runtimeSurface == "codex",
        "a surface belonging to the other tile never routes this tile's account")
    handoff.surfaceRaw = "nonsense"
    try check(handoff.runtimeSurface == "codex", "an unparsable stored surface falls back to the executor")
    handoff.surfaceRaw = nil
    try check(handoff.runtimeSurface == "codex", "a legacy submission with no surface runs the executor")

    store.chooseSurface(.claudeChat, for: anthropic)
    try check(store.appSettings.surface(for: anthropic) == .claudeChat && store.routedSurface(for: .claude) == .claudeChat,
        "the Anthropic tile can select its bounded chat lane")
    try check(store.selectedSession?.provider == .claude,
        "selecting the Claude chat lane pins the next turn to the Anthropic tile")
    var chat = PendingSubmission(sessionID: store.sessions[index].id, userMessageID: UUID(),
        request: "x", provider: .claude, workspace: "/tmp", codexCapacity: 1, claudeCapacity: 1)
    chat.surfaceRaw = store.appSettings.surface(for: anthropic).rawValue
    try check(chat.runtimeSurface == "claude-chat", "the chat lane dispatches --provider claude-chat")

    // Selecting a surface must not invent a second account, session or pool.
    try check(store.accounts(for: .codex).count == store.accounts(for: .codex).count,
        "the surface choice does not change the account list")
    try check(ProviderSurface.chatgpt.quotaPool != ProviderSurface.codex.quotaPool
        && ProviderSurface.claudeChat.quotaPool == ProviderSurface.claude.quotaPool,
        "the rail must not merge the OpenAI pools nor split the Anthropic one")

    // Returning to the executor clears the badge and the stored value, so the
    // settings file does not accumulate a default written as an override.
    store.chooseSurface(.codex, for: openAI)
    store.chooseSurface(.claude, for: anthropic)
    try check(store.appSettings.openAISurface == nil && store.appSettings.anthropicSurface == nil,
        "choosing the default again stores nothing rather than pinning it")
    try check(store.routedSurface(for: .codex)?.railBadge == nil
        && store.routedSurface(for: .claude)?.railBadge == nil,
        "returning to the executor clears the rail badge")

    // Bounded read-only recovery must stay on the router: a handoff executes
    // nothing, so it can never reconcile a failed run.
    let recovery = PendingSubmission(sessionID: store.sessions[index].id, userMessageID: UUID(),
        request: "x", provider: .auto, workspace: "/tmp", codexCapacity: 1, claudeCapacity: 1,
        readOnlyReconciliation: true)
    try check(recovery.surfaceRaw == nil && recovery.runtimeSurface == "auto",
        "recovery runs on the router, never on a handoff surface")

    // A badge is painted as an overlay, so the pinned tile height cannot move.
    let badgedTile = BackendStatus(provider: .codex, selected: true, active: false, linked: false,
        signedIn: true, signingIn: false, accountLabel: nil, surfaceBadge: "ChatGPT", disabled: false) {}
    let plainTile = BackendStatus(provider: .codex, selected: true, active: false, linked: false,
        signedIn: true, signingIn: false, accountLabel: nil, surfaceBadge: nil, disabled: false) {}
    try check(badgedTile.stateText == plainTile.stateText,
        "a badge must not change what the tile reports about its session")

    print("Provider rail selection: \(checks) checks passed; model calls 0; live backend writes 0")
}

/// Fixture-only rail renderings for the three selection states, using the
/// production views and the reported linked/last-active combination.
@MainActor
private func renderProviderRailPreview(to output: URL) throws {
    try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true,
        attributes: [.posixPermissions: 0o700])
    let fixtureRoot = FileManager.default.temporaryDirectory
        .appendingPathComponent("os1-rail-preview-" + UUID().uuidString, isDirectory: true)
    try FileManager.default.createDirectory(at: fixtureRoot, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: fixtureRoot) }

    var written: [String] = []
    // Every selection state, plus the same two backend states with each tile
    // routed to its alternative surface so the rail badge is visible here too.
    let states: [(String, ProviderChoice, Bool)] =
        ProviderChoice.allCases.map { ($0.rawValue, $0, false) }
        + [("codex-chatgpt", .codex, true), ("claude-chat", .claude, true)]
    for (label, surface, badged) in states {
        let store = SessionStore(storageRoot: fixtureRoot.appendingPathComponent(label, isDirectory: true),
            nativeSessionOpener: { _ in false })
        guard let index = store.selectedIndex else { throw SourceContextError.invalid }
        store.sessions[index].title = "Rail fixture"
        store.sessions[index].claudeSessionID = "bae5987c-3fd1-4d08-a85c-6d9c18d41e86"
        store.sessions[index].codexSessionID = nil
        store.sessions[index].lastProvider = "claude"
        store.surface = surface
        if badged {
            store.updateSettings {
                $0.setSurface(.chatgpt, for: .openAI)
                $0.setSurface(.claudeChat, for: .anthropic)
            }
        }
        let content = ProviderRail(store: store)
            .frame(width: 78, height: 680)
            .background(Theme.background)
            .environment(\.colorScheme, .dark)
        let view = NSHostingView(rootView: content)
        view.frame = NSRect(x: 0, y: 0, width: 78, height: 680)
        RunLoop.main.run(until: Date().addingTimeInterval(0.05))
        view.layoutSubtreeIfNeeded()
        view.needsDisplay = true
        view.displayIfNeeded()
        guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { throw SourceContextError.invalid }
        view.cacheDisplay(in: view.bounds, to: bitmap)
        guard let data = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
        let name = "rail-\(label)-selected.png"
        try data.write(to: output.appendingPathComponent(name), options: .atomic)
        written.append(name)
    }
    let manifest: [String: Any] = [
        "fixtureOnly": true,
        "linkedBackends": ["claude"],
        "lastActiveBackend": "claude",
        "states": written,
    ]
    try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
        .write(to: output.appendingPathComponent("provider-rail-preview.json"), options: .atomic)
}

/// Real rail/sidebar/conversation components with synthetic data, without live
/// RootView tasks. Both supported window sizes retain the draft and queue.
@MainActor
private func renderProfileShellPreviews(to output: URL) throws {
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-profile-shell-" + UUID().uuidString)
    try FileManager.default.createDirectory(at: root, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: root) }
    let store = SessionStore(storageRoot: root, runOperation: { _, _, _, _, _ in
        throw RunnerError.message("Profile preview must not execute a backend")
    }, nativeSessionOpener: { _ in false })
    guard let id = store.selectedSessionID, let index = store.selectedIndex else { throw SourceContextError.invalid }
    store.sessions[index].title = "Profile menu preview"
    store.sessions[index].workspace = root.path
    store.activeRuns[id] = .init(submissionID: UUID(), started: Date(),
        activity: RuntimeActivity(.executing, provider: "codex"), provider: .codex, handedRevision: 0)
    store.composer = "Preserve this queued request"; store.send()
    store.composer = "Preserve this draft"
    let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
    let queueBefore = store.queuedSubmissions, sessionsBefore = try encoder.encode(store.sessions), draftBefore = store.composer
    let profile = AppIdentityProfile(provider: .google, subject: "fixture", name: "Demo User", email: "demo@example.invalid")
    let identity = OS1IdentityModel(previewProfile: profile)
    let summary = AppUsageSummary(snapshot: try profileUsageFixture())
    var metrics: [[String: Any]] = []
    for (name, width, height) in [("shell-minimum", 980.0, 680.0), ("shell-standard", 1360.0, 760.0)] {
        let content = HStack(spacing: 0) {
            ProviderRail(store: store, identity: identity)
            Rectangle().fill(Theme.border).frame(width: 1)
            SessionSidebar(store: store)
            Rectangle().fill(Theme.border).frame(width: 1)
            ConversationView(store: store)
        }
        .overlay(alignment: .bottomLeading) {
            ProfileMenuView(profile: profile, usage: summary, select: { _ in }, signOut: {})
                .padding(.leading, 74).padding(.bottom, 24)
        }
        .frame(width: width, height: height).background(Theme.background).environment(\.colorScheme, .dark)
        let view = NSHostingView(rootView: content)
        view.frame = NSRect(x: 0, y: 0, width: width, height: height)
        view.layoutSubtreeIfNeeded()
        guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else { throw SourceContextError.invalid }
        view.cacheDisplay(in: view.bounds, to: bitmap)
        let scale = Double(bitmap.pixelsWide) / width
        var left = bitmap.pixelsWide, right = 0, top = bitmap.pixelsHigh, bottom = 0
        for y in Int((height - 120) * scale)..<bitmap.pixelsHigh {
            for x in 0..<Int(72 * scale) {
                guard let c = bitmap.colorAt(x: x, y: y)?.usingColorSpace(.deviceRGB),
                      c.greenComponent > c.redComponent + 0.15, c.greenComponent > 0.4, c.redComponent < 0.3 else { continue }
                left = min(left, x); right = max(right, x); top = min(top, y); bottom = max(bottom, y)
            }
        }
        let centerX = Double(left + right) / (2 * scale), centerY = Double(top + bottom) / (2 * scale)
        guard right > left, bottom > top,
              abs(centerX - 39) <= 2, abs(centerY - (height - 49)) <= 2,
              bottom < bitmap.pixelsHigh - Int(24 * scale) else {
            throw RunnerError.message("Profile rail pixels: avatar clipped or displaced at \(width)x\(height)")
        }
        guard let png = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
        try png.write(to: output.appendingPathComponent(name + ".png"))
        metrics.append(["file": name + ".png", "widthPoints": width, "heightPoints": height,
                        "avatarCenterX": centerX, "avatarCenterY": centerY, "avatarNotClipped": true])
    }
    guard store.queuedSubmissions == queueBefore, try encoder.encode(store.sessions) == sessionsBefore, store.composer == draftBefore else {
        throw RunnerError.message("Profile rendering mutated the conversation, queue, or draft")
    }
    try JSONSerialization.data(withJSONObject: ["fixturesOnly": true, "layouts": metrics,
        "draftPreserved": true, "queuePreserved": true, "sessionsPreserved": true], options: [.prettyPrinted, .sortedKeys])
        .write(to: output.appendingPathComponent("shell-layout.json"))
    print("Profile shell: minimum/standard native composition pixel checks; draft, queue and session preserved")
}

/// Composed production-shell rendering used to prove the sidebar header's
/// actual painted position rather than inferring it from padding constants.
private struct SidebarHeaderPixelMetrics {
    let titleTopPoints: CGFloat
    let newTaskLabelTopPoints: CGFloat
    let newTaskButtonTopPoints: CGFloat
}

private let sidebarTitleTopMaximum: CGFloat = 20
private let sidebarNewTaskButtonTopMinimum: CGFloat = 32
private let sidebarNewTaskButtonTopMaximum: CGFloat = 60

private func measureSidebarHeaderPixels(_ bitmap: NSBitmapImageRep, viewWidth: CGFloat) throws -> SidebarHeaderPixelMetrics {
    let scale = CGFloat(bitmap.pixelsWide) / viewWidth
    // The 78 pt provider rail and one-pixel divider end at x=79. Scan only
    // the left portion of the 256 pt session sidebar so conversation chrome
    // and split-view dividers cannot influence the measurement.
    let xStart = max(0, Int((79 + 9) * scale))
    let xEnd = min(bitmap.pixelsWide, Int(240 * scale))
    let yEnd = min(bitmap.pixelsHigh, Int(180 * scale))
    let minimumPaintedPixels = max(4, Int(ceil(4 * scale)))

    func rowIsPainted(_ y: Int) -> Bool {
        var painted = 0
        for x in xStart..<xEnd {
            guard let color = bitmap.colorAt(x: x, y: y) else { continue }
            let brightest = max(color.redComponent, max(color.greenComponent, color.blueComponent))
            if color.alphaComponent > 0.1, brightest > 0.17 {
                painted += 1
                if painted >= minimumPaintedPixels { return true }
            }
        }
        return false
    }

    var runs: [(start: Int, end: Int)] = []
    var runStart: Int?
    for y in 0..<yEnd {
        if rowIsPainted(y) {
            if runStart == nil { runStart = y }
        } else if let start = runStart {
            runs.append((start, y))
            runStart = nil
        }
    }
    if let start = runStart { runs.append((start, yEnd)) }

    let minimumRunHeight = max(3, Int(ceil(3 * scale)))
    let substantiveRuns = runs.filter { $0.end - $0.start >= minimumRunHeight }
    guard let title = substantiveRuns.first else {
        throw RunnerError.message("Sidebar header pixels: title not found")
    }
    let minimumGap = Int(ceil(8 * scale))
    guard let newTaskLabel = substantiveRuns.first(where: { $0.start >= title.end + minimumGap }) else {
        throw RunnerError.message("Sidebar header pixels: new-task label not found")
    }

    let titleTop = CGFloat(title.start) / scale
    let labelTop = CGFloat(newTaskLabel.start) / scale
    return SidebarHeaderPixelMetrics(
        titleTopPoints: titleTop,
        newTaskLabelTopPoints: labelTop,
        newTaskButtonTopPoints: labelTop - SidebarHeaderLayout.buttonLabelPaintInset
    )
}

@MainActor
@discardableResult
private func renderSidebarHeaderPreview(to output: URL) throws -> SidebarHeaderPixelMetrics {
    try FileManager.default.createDirectory(at: output, withIntermediateDirectories: true,
        attributes: [.posixPermissions: 0o700])
    let fixtureRoot = FileManager.default.temporaryDirectory
        .appendingPathComponent("os1-sidebar-header-preview-" + UUID().uuidString, isDirectory: true)
    try FileManager.default.createDirectory(at: fixtureRoot, withIntermediateDirectories: true)
    defer { try? FileManager.default.removeItem(at: fixtureRoot) }

    let store = SessionStore(storageRoot: fixtureRoot, nativeSessionOpener: { _ in false })
    let content = RootView(store: store)
        .frame(width: 1_360, height: 760)
        .background(Theme.background)
        .environment(\.colorScheme, .dark)
    let view = NSHostingView(rootView: content)
    view.frame = NSRect(x: 0, y: 0, width: 1_360, height: 760)
    RunLoop.main.run(until: Date().addingTimeInterval(0.12))
    view.layoutSubtreeIfNeeded()
    view.needsDisplay = true
    view.displayIfNeeded()
    guard let bitmap = view.bitmapImageRepForCachingDisplay(in: view.bounds) else {
        throw RunnerError.message("Sidebar header preview: no bitmap")
    }
    view.cacheDisplay(in: view.bounds, to: bitmap)
    guard let data = bitmap.representation(using: .png, properties: [:]) else {
        throw RunnerError.message("Sidebar header preview: no PNG")
    }
    try data.write(to: output.appendingPathComponent("sidebar-header.png"), options: .atomic)
    let metrics = try measureSidebarHeaderPixels(bitmap, viewWidth: view.bounds.width)
    let manifest: [String: Any] = [
        "composedRootView": true,
        "widthPoints": 1_360,
        "heightPoints": 760,
        "pixelWidth": bitmap.pixelsWide,
        "pixelHeight": bitmap.pixelsHigh,
        "scale": CGFloat(bitmap.pixelsWide) / view.bounds.width,
        "titleTopPoints": metrics.titleTopPoints,
        "titleTopMaximumPoints": sidebarTitleTopMaximum,
        "newTaskLabelTopPoints": metrics.newTaskLabelTopPoints,
        "newTaskButtonTopPoints": metrics.newTaskButtonTopPoints,
        "newTaskButtonTopMinimumPoints": sidebarNewTaskButtonTopMinimum,
        "newTaskButtonTopMaximumPoints": sidebarNewTaskButtonTopMaximum,
    ]
    try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
        .write(to: output.appendingPathComponent("sidebar-header-preview.json"), options: .atomic)
    return metrics
}

@MainActor
private func sidebarHeaderPixelSelfTest() throws {
    let output = FileManager.default.temporaryDirectory
        .appendingPathComponent("os1-sidebar-header-test-" + UUID().uuidString, isDirectory: true)
    defer { try? FileManager.default.removeItem(at: output) }
    let metrics = try renderSidebarHeaderPreview(to: output)
    guard metrics.titleTopPoints <= sidebarTitleTopMaximum else {
        throw RunnerError.message(
            "Sidebar header pixels: title top \(metrics.titleTopPoints)pt exceeds \(sidebarTitleTopMaximum)pt"
        )
    }
    guard metrics.newTaskButtonTopPoints >= sidebarNewTaskButtonTopMinimum,
          metrics.newTaskButtonTopPoints <= sidebarNewTaskButtonTopMaximum else {
        throw RunnerError.message(
            "Sidebar header pixels: new-task button top \(metrics.newTaskButtonTopPoints)pt outside "
                + "\(sidebarNewTaskButtonTopMinimum)...\(sidebarNewTaskButtonTopMaximum)pt"
        )
    }
    print(
        "Sidebar header pixels: title top \(metrics.titleTopPoints)pt; "
            + "new-task label top \(metrics.newTaskLabelTopPoints)pt; "
            + "inferred button top \(metrics.newTaskButtonTopPoints)pt"
    )
}

private struct NativeSessionBrowser: View {
    @ObservedObject var store: SessionStore
    let provider: ProviderChoice
    let browserVisible: Bool
    let toggleBrowser: () -> Void

    init(
        store: SessionStore,
        provider: ProviderChoice,
        browserVisible: Bool = false,
        toggleBrowser: @escaping () -> Void = {}
    ) {
        self.store = store
        self.provider = provider
        self.browserVisible = browserVisible
        self.toggleBrowser = toggleBrowser
    }

    private var recordedSessionID: String? {
        store.linkedNativeSessionID(for: provider)
    }

    private var recordedSessionIsAvailable: Bool {
        guard let recordedSessionID else { return false }
        return store.nativeSessions.contains(where: { $0.id == recordedSessionID })
    }

    var body: some View {
        HStack(spacing: 0) {
            VStack(alignment: .leading, spacing: 0) {
                HStack(spacing: 8) {
                    Text("OS-1").foregroundStyle(Theme.pink)
                    Text("CLODEX").foregroundStyle(Theme.text)
                }
                .font(.system(size: 13, weight: .semibold))
                .tracking(0.4)
                .padding(.horizontal, 24)
                .padding(.top, SidebarHeaderLayout.titleTop)
                .padding(.bottom, SidebarHeaderLayout.titleBottomGap)

                VStack(alignment: .leading, spacing: 5) {
                    Text(provider == .claude ? "CLAUDE CODE SESSIONS" : "CODEX SESSIONS")
                        .font(.system(size: 10, weight: .bold))
                        .tracking(1.2)
                        .foregroundStyle(provider.tint)
                    HStack(spacing: 6) {
                        Circle().fill(recordedSessionIsAvailable ? Theme.green : Theme.muted).frame(width: 6, height: 6)
                        Text(recordedSessionID == nil
                            ? "THIS CONVERSATION · NO SESSION"
                            : (recordedSessionIsAvailable ? "CURRENT RECORD · AVAILABLE" : "CURRENT RECORD · NOT FOUND"))
                            .font(.system(size: 9, weight: .bold))
                            .foregroundStyle(Theme.muted)
                    }
                    Text("LOCAL RECORDS · \(store.nativeSessions.count) · PIN MANAGEMENT")
                        .font(.system(size: 8, weight: .medium))
                        .foregroundStyle(Theme.muted)
                }
                .padding(.horizontal, 24)
                .padding(.bottom, 16)

                HStack(spacing: 8) {
                    Image(systemName: "magnifyingglass").foregroundStyle(Theme.muted)
                    TextField("Search \(provider.title) sessions", text: $store.nativeSearch)
                        .textFieldStyle(.plain)
                    Button { store.refreshNativeSessions() } label: {
                        Image(systemName: "arrow.clockwise")
                    }
                    .buttonStyle(.plain)
                    .help("Refresh local sessions")
                    .accessibilityLabel("Refresh backend sessions")
                }
                .padding(.horizontal, 16)
                .frame(height: 34)
                .background(Color.black.opacity(0.24))
                .overlay(
                    RoundedRectangle(cornerRadius: Theme.radiusControl, style: .continuous)
                        .stroke(Color.clear)
                )
                .clipShape(RoundedRectangle(cornerRadius: Theme.radiusControl, style: .continuous))
                .padding(.horizontal, 20)
                .padding(.bottom, 16)

                if store.isLoadingNativeSessions && store.nativeSessions.isEmpty {
                    Spacer()
                    ProgressView("Synchronizing local sessions…")
                        .controlSize(.small)
                        .foregroundStyle(Theme.muted)
                        .frame(maxWidth: .infinity)
                    Spacer()
                } else if store.filteredNativeSessions.isEmpty {
                    Spacer()
                    Text("No local sessions found")
                        .font(.system(size: 12, weight: .medium))
                        .foregroundStyle(Theme.muted)
                        .frame(maxWidth: .infinity)
                    Spacer()
                } else {
                    ScrollViewReader { proxy in
                    ScrollView {
                        LazyVStack(spacing: 6) {
                            ForEach(store.filteredNativeSessions) { session in
                                if session.id == store.filteredNativeSessions.first?.id && session.isPinned {
                                    Text("PINNED").font(.system(size: 9, weight: .bold)).foregroundStyle(Theme.muted)
                                        .frame(maxWidth: .infinity, alignment: .leading).padding(.horizontal, 13)
                                }
                                NativeSessionRow(
                                    session: session,
                                    selected: store.selectedNativeSessionID == session.id,
                                    current: store.linkedNativeSessionID(for: provider) == session.id,
                                    tint: provider.tint
                                ) { store.selectNativeSession(session.id) }
                                .id(session.id)
                                .contextMenu {
                                    Button(session.isPinned ? os1Tr("고정 해제", "Unpin") : os1Tr("상단에 고정", "Pin to top")) { store.toggleNativePin(session.id) }
                                    if session.isPinned {
                                        Button(os1Tr("핀 순서 위로", "Move pin up")) { store.shiftNativePin(session.id, down: false) }
                                        Button(os1Tr("핀 순서 아래로", "Move pin down")) { store.shiftNativePin(session.id, down: true) }
                                    }
                                    if provider == .codex, session.pinSyncNote != nil {
                                        Button(os1Tr("백엔드에 다시 반영", "Retry backend sync")) { store.retryNativePin(session.id) }
                                    }
                                }
                                .onDrag { NSItemProvider(object: "\(provider.rawValue):\(session.id)" as NSString) }
                                .onDrop(of: [UTType.plainText], isTargeted: nil) { items in
                                    acceptSidebarDrop(items, prefix: provider.rawValue) { id in
                                        guard store.surface == provider, session.isPinned else { return }
                                        store.moveNativePin(id, before: session.id)
                                    }
                                }
                            }
                        }
                        .padding(.horizontal, 20)
                        .padding(.bottom, 12)
                    }
                    .onAppear {
                        if let current = store.linkedNativeSessionID(for: provider),
                           store.runningNativeSessionIDs(for: provider).contains(current) {
                            proxy.scrollTo(current, anchor: .top)
                        }
                    }
                    }
                }
                if let notice = store.sidebarSyncNotice {
                    Text(notice).font(.system(size: 10)).foregroundStyle(Theme.pink)
                        .padding(12).frame(maxWidth: .infinity, alignment: .leading)
                } else if provider == .claude {
                    Text(os1Tr("Claude 앱의 핀 표시를 읽습니다. 앱 간 핀 변경·수동 순서는 아직 동기화되지 않습니다.",
                               "Reads pin markers from the Claude app. Pin changes and manual order aren't synced between apps yet."))
                        .font(.system(size: 10)).foregroundStyle(Theme.muted).padding(12)
                }
            }
            .frame(width: Theme.sidebarWidth)
            .background(Color.black.opacity(0.72))

            Rectangle().fill(Theme.border).frame(width: 1)

            VStack(spacing: 0) {
                BrowserToggleBar(visible: browserVisible, toggle: toggleBrowser)
                NativeTranscriptView(store: store, provider: provider)
            }
        }
        .onChange(of: store.linkedNativeSessionID(for: provider)) { _ in
            if store.surface == provider { store.inspectBackend(provider) }
        }
        .onChange(of: store.isRunning) { running in
            if !running, store.isShowingLinkedNativeSession(provider) {
                store.refreshVisibleNativeTranscript(provider)
            }
        }
        .task(id: provider) {
            while !Task.isCancelled {
                try? await Task.sleep(for: backendInspectorRefreshInterval)
                guard !Task.isCancelled else { return }
                store.refreshActiveLinkedNativeTranscript(provider)
            }
        }
    }
}

