}

private extension NSAttributedString.Key {
    static let os1TimelineRole = NSAttributedString.Key("com.omaragi.os1.timeline-role")
}

/// Inline attachment cards for the owner's files. Images get bounded
/// thumbnails; every other file gets its native document icon and name.
/// The quoted transport path stays in stored message text but never becomes
/// the visible transcript payload.
private func timelineAttachmentPreviews(
    paths: [String],
    maxEdge: CGFloat = Theme.attachmentPreviewMaxEdge
) -> NSAttributedString? {
    let result = NSMutableAttributedString()
    // Every attachment the composer accepted (it caps at 24) gets a card; a
    // silent cut at six lost files 7+ without a trace.
    for (index, path) in paths.enumerated() {
        let url = URL(fileURLWithPath: path)
        let attachment = NSTextAttachment()
        var isImagePreview = false
        if PromptAttachments.isImagePath(path),
           let source = CGImageSourceCreateWithURL(url as CFURL, nil),
           let cgImage = CGImageSourceCreateThumbnailAtIndex(source, 0, [
                kCGImageSourceCreateThumbnailFromImageAlways: true,
                kCGImageSourceCreateThumbnailWithTransform: true,
                kCGImageSourceThumbnailMaxPixelSize: Int(maxEdge * 2),
           ] as CFDictionary) {
            attachment.image = NSImage(cgImage: cgImage, size: .zero)
            let scale = min(1, maxEdge / max(CGFloat(cgImage.width), CGFloat(cgImage.height)))
            attachment.bounds = CGRect(
                x: 0,
                y: 0,
                width: CGFloat(cgImage.width) * scale,
                height: CGFloat(cgImage.height) * scale
            )
            isImagePreview = true
        } else {
            attachment.image = NSWorkspace.shared.icon(forFile: path)
            attachment.bounds = CGRect(x: 0, y: -3, width: 24, height: 24)
        }
        if index > 0 { result.append(NSAttributedString(string: "\n")) }
        result.append(NSAttributedString(attachment: attachment))
        // The image is the card. Repeating its filename beside the preview
        // adds clutter; document attachments still need a visible label.
        if !isImagePreview {
            let kind = url.pathExtension.isEmpty ? os1Tr("파일", "File") : url.pathExtension.uppercased()
            result.append(NSAttributedString(
                string: "  \(kind) · \(url.lastPathComponent)",
                attributes: [
                    .font: NSFont.systemFont(ofSize: 11, weight: .medium),
                    .foregroundColor: TimelinePalette.muted,
                ]
            ))
        }
    }
    return result.length == 0 ? nil : result
}

private enum TimelinePalette {
    static let text = NSColor.white.withAlphaComponent(0.95)
    static let muted = NSColor.white.withAlphaComponent(0.47)
    /// Secondary lines that open in place (tool calls, work time, execution
    /// record): gray like Claude Code's and Codex's, still readable.
    static let detail = NSColor.white.withAlphaComponent(0.58)
    /// Links keep the color they were drawn with, so a gray disclosure stays
    /// gray; the text view adds only the pointing hand.
    @MainActor static var linkAttributes: [NSAttributedString.Key: Any] { [.cursor: NSCursor.pointingHand] }
    static let borderStrong = NSColor.white.withAlphaComponent(0.22)
    static let panelRaised = NSColor(
        calibratedRed: 0.035,
        green: 0.029,
        blue: 0.034,
        alpha: 0.72
    )
    static let pink = NSColor(calibratedRed: 0.93, green: 0.70, blue: 0.80, alpha: 1)
    static let green = NSColor(calibratedRed: 0.28, green: 0.93, blue: 0.55, alpha: 1)
    static let codex = NSColor(calibratedRed: 0.95, green: 0.64, blue: 0.80, alpha: 1)
    static let claude = NSColor(calibratedRed: 0.98, green: 0.53, blue: 0.68, alpha: 1)
    // User bubbles share the app's pink family while staying readable against the dark transcript.
    static let userBubble = NSColor(calibratedRed: 0.62, green: 0.24, blue: 0.43, alpha: 1)
}

/// The one line under a steered input that separates "OS-1 accepted and is
/// still handing this over" from "the run actually received it". Ordinary
/// messages carry no state and render exactly as before.
/// `queueReason` is the owning conversation's actual queue blocker, passed
/// only for a request still waiting in an idle conversation's queue, so the
/// bubble names why it has not reached a backend (e.g. the global slot cap).
private func steeringDeliveryCaption(_ state: SteeringDeliveryState?, queueReason: String? = nil) -> [(String, NSFont, NSColor)] {
    guard let state else { return [] }
    let (text, color): (String, NSColor)
    switch state {
    case .waiting: (text, color) = (queueReason.map { os1Tr("백엔드 전달 전 · ", "Not yet sent to the backend · ") + $0 } ?? os1Tr("전달 대기 · 아직 백엔드에 전달되지 않았습니다", "Waiting to deliver · not yet sent to the backend"), TimelinePalette.muted)
    case .pending: (text, color) = (os1Tr("전달 대기 · 현재 작업에 전달했고 수신 확인 중입니다", "Waiting for delivery · sent to the current task, confirming receipt"), TimelinePalette.muted)
    case .delivered: (text, color) = (os1Tr("전달 완료 · 현재 작업이 입력을 받았습니다", "Delivered · the current task received the input"), TimelinePalette.green)
    case .rejected: (text, color) = (os1Tr("전달 거절됨 · 입력은 보존했습니다", "Delivery rejected · input preserved"), TimelinePalette.pink)
    case .undelivered: (text, color) = (os1Tr("전달되지 않음 · 입력은 보존했습니다", "Not delivered · input preserved"), TimelinePalette.muted)
    }
    return [("\u{2028}" + text, NSFont.systemFont(ofSize: 10, weight: .medium), color)]
}

private func timelineNormalizedText(_ value: String) -> String {
    value
        .replacingOccurrences(of: "\r\n", with: "\n")
        .replacingOccurrences(of: "\r", with: "\n")
        // A line separator keeps one visual message in one TextKit paragraph.
        // ContinuousTranscriptTextView.copy converts it back to a regular LF.
        .replacingOccurrences(of: "\n", with: "\u{2028}")
}

private func retrievalPresentation(messages: [ChatMessage], index: Int, sourceStore: SourceContextStore) -> RetrievedAnswer? {
    let message = messages[index]
    guard message.role == .assistant, message.provider == "local",
          (message.text.hasPrefix("R2에서") || message.text.hasPrefix("등록 원본에서")),
          index + 1 < messages.count else { return nil }
    let receipt = messages[index + 1]
    guard receipt.role == .receipt, receipt.provider == "local", receipt.nativeRecordVerified == true,
          let match = receipt.text.range(of: #"[a-fA-F0-9]{8}(?:-[a-fA-F0-9]{4}){3}-[a-fA-F0-9]{12}\.json\b"#, options: .regularExpression),
          let id = UUID(uuidString: String(receipt.text[match].dropLast(5))),
          let reference = sourceStore.legacyReference(id: id, output: message.text),
          let data = try? sourceStore.read(reference),
          let value = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
          let sources = value["sources"] as? [[String: Any]] else { return nil }
    return RetrievedAnswer.fromEvidence(output: message.text, sourcePaths: sources.compactMap { $0["source_path"] as? String })
}

private func assistantDisplayText(messages: [ChatMessage], index: Int, expanded: Set<String>, expandAll: Bool,
                                  sourceStore: SourceContextStore) -> NSAttributedString {
    let message = messages[index], key = message.id.uuidString
    guard let answer = retrievalPresentation(messages: messages, index: index, sourceStore: sourceStore) else {
        return TranscriptMarkdown.render(message.text, key: key, expanded: expanded, expandAll: expandAll)
    }
    let content = NSMutableAttributedString(attributedString: TranscriptMarkdown.render(answer.overview, key: key))
    let request = messages[..<index].last(where: { $0.role == .user })?.text.lowercased() ?? ""
    let originalRequested = ["원문 그대로", "원문 전체", "전체 원문", "verbatim"].contains(where: request.contains)
    for (suffix, label, text, initiallyOpen) in [
        ("source", os1Tr("자료 원문", "Source text"), answer.original, originalRequested),
        ("evidence", os1Tr("출처·검증 정보", "Sources and verification"), answer.technical, false),
    ] {
        let detailKey = "\(key)-\(suffix)"
        let open = expandAll || (initiallyOpen != expanded.contains(detailKey))
        content.append(NSAttributedString(string: "\u{2028}\u{2028}"))
        content.append(TranscriptMarkdown.detailLink("\(label) · \(open ? os1Tr("접기", "Collapse") : os1Tr("펼쳐보기", "Expand"))", key: detailKey))
        if open {
            content.append(NSAttributedString(string: "\u{2028}\u{2028}"))
            content.append(TranscriptMarkdown.render(text, key: detailKey, expanded: expanded, expandAll: expandAll))
        }
    }
    return content
}

/// The part of the live output `progress` produced after `anchor`, the live
/// output that was on screen when the owner steered. The stream only appends,
/// except that it keeps its last 24k characters, so a trimmed head is found
/// again by the anchor's tail. A stream that no longer contains the anchor (a
/// fresh attempt) was produced entirely after it.
private func liveProgress(after anchor: String?, in progress: String) -> Substring {
    guard let anchor, !anchor.isEmpty else { return progress[...] }
    if progress.hasPrefix(anchor) { return progress.dropFirst(anchor.count).drop(while: \.isWhitespace) }
    let tail = String(anchor.suffix(64))
    if tail.count >= 16, let found = progress.range(of: tail) {
        return progress[found.upperBound...].drop(while: \.isWhitespace)
    }
    return progress[...]
}

/// The anchor of the last steered input in `messages`: the live output
/// shown above it. Output after it belongs below that bubble.
private func latestSteeringAnchor(_ messages: [ChatMessage], _ anchors: [UUID: String]) -> String? {
    guard !anchors.isEmpty else { return nil }
    return messages.last(where: { anchors[$0.id] != nil }).flatMap { anchors[$0.id] }
}

private func timelineAttributedDocument(
    messages: [ChatMessage],
    queuedSubmissions: [PendingSubmission],
    isRunning: Bool,
    workspace: String,
    expanded: Set<String> = [],
    expandAll: Bool = false,
    sourceStore: SourceContextStore = SourceContextStore(),
    publicProgress: String? = nil,
    waitingReason: String? = nil,
    progressAnchors: [UUID: String] = [:],
    progressFollows: String? = nil,
    liveRun: LiveRunPresentation? = nil,
    liveRunExpanded: Bool = false,
    workLogStore: NativePublicRunLogStore = NativePublicRunLogStore()
) -> NSAttributedString {
    let document = NSMutableAttributedString()
    let queuedMessageIDs = Set(queuedSubmissions.map(\.userMessageID))

    func appendBlock(
        role: String,
        alignment: NSTextAlignment = .left,
        minimumHeadIndent: CGFloat = 0,
        components: [(String, NSFont, NSColor)],
        richContent: NSAttributedString? = nil,
        trailingSpacing: CGFloat = 40
    ) {
        let paragraph = NSMutableParagraphStyle()
        paragraph.alignment = alignment
        paragraph.headIndent = minimumHeadIndent
        paragraph.firstLineHeadIndent = minimumHeadIndent
        paragraph.lineSpacing = 3
        // Borders extend 12–13 points past glyphs on BOTH neighboring messages.
        // Reserve that paint in text layout, not only in draw(_:).
        paragraph.paragraphSpacing = 0
        let start = document.length
        for component in components {
            document.append(NSAttributedString(
                string: component.0,
                attributes: [
                    .font: component.1,
                    .foregroundColor: component.2,
                ]
            ))
        }
        if let richContent { document.append(richContent) }
        let contentRange = NSRange(location: start, length: document.length - start)
        // Do not erase Markdown paragraph styles or native table cell blocks.
        document.enumerateAttribute(.paragraphStyle, in: contentRange) { style, range, _ in
            if style == nil { document.addAttribute(.paragraphStyle, value: paragraph, range: range) }
        }
        document.addAttribute(.os1TimelineRole, value: role as NSString, range: contentRange)
        let endingStyle = document.string.hasSuffix("\n") ? paragraph
            : ((document.attribute(.paragraphStyle, at: max(start, document.length - 1), effectiveRange: nil) as? NSParagraphStyle)?.mutableCopy() as? NSMutableParagraphStyle ?? paragraph)
        document.append(NSAttributedString(string: "\n", attributes: [
            .font: NSFont.systemFont(ofSize: 4),
            .paragraphStyle: endingStyle,
        ]))
        let lastParagraph = (document.string as NSString).paragraphRange(for: NSRange(location: document.length - 1, length: 1))
        let finalStyle = endingStyle.mutableCopy() as! NSMutableParagraphStyle
        finalStyle.paragraphSpacing = trailingSpacing
        document.addAttribute(.paragraphStyle, value: finalStyle, range: lastParagraph)
    }

    // The backend's prose reads as text; its tool calls fold into gray
    // lines that open in place, as Claude Code and Codex show a working turn.
    func appendLiveProgress(_ text: Substring, key: String) {
        let segments = NativePublicRunLog.displaySegments(text)
        guard !segments.isEmpty else { return }
        appendBlock(role: "assistant", components: [], richContent: publicFeedContent(segments, key: key, toolsKey: liveFeedKey,
            caption: os1Tr("진행 중 · 아직 검증되지 않은 출력", "In progress · output not yet verified"),
            expanded: expanded, expandAll: expandAll))
    }

    // While the run is live, a steered input sits after the output that was
    // on screen when the owner sent it; only later output follows it.
    var steeredAfter = progressFollows
    for (index, message) in messages.enumerated() {
        if isRunning, let anchor = progressAnchors[message.id] {
            appendLiveProgress(liveProgress(after: steeredAfter, in: anchor), key: "live-progress-" + message.id.uuidString)
            steeredAfter = anchor
        }
        switch message.role {
        case .user:
            // Codex-style convergence: text owns the user bubble while image
            // cards stay outside it. The transport path remains stored/copyable
            // but never becomes visible transcript text.
            let paths = PromptAttachments.paths(in: message.text)
            let previews = timelineAttachmentPreviews(paths: paths)
            let shown = paths.isEmpty ? message.text : PromptAttachments.textWithoutReferences(message.text)
            appendBlock(
                role: MessageRole.user.rawValue,
                alignment: .right,
                minimumHeadIndent: 100,
                components: [(
                    timelineNormalizedText(shown),
                    NSFont.systemFont(ofSize: 14, weight: .medium),
                    TimelinePalette.text
                )] + steeringDeliveryCaption(message.steeringDelivery,
                    queueReason: queuedMessageIDs.contains(message.id) ? waitingReason : nil),
                trailingSpacing: previews == nil ? 40 : 20
            )
            if let previews {
                appendBlock(
                    role: "userAttachment",
                    alignment: .right,
                    minimumHeadIndent: 100,
                    components: [],
                    richContent: previews
                )
            }
        case .assistant:
            if let work = message.work {
                // The turn's own answers, so opened work never repeats them.
                let answer = messages[index...].prefix { $0.role != .user }.filter { $0.role == .assistant }
                    .map(\.text).joined(separator: "\n\n")
                let key = "\(message.id.uuidString)-work"
                appendBlock(role: "work", components: [], richContent: turnWorkContent(work, key: key, answer: answer,
                    expanded: expanded, expandAll: expandAll, store: workLogStore),
                    trailingSpacing: expandAll || expanded.contains(key) ? 24 : 14)
            }
            let provider = providerDisplayName(message.provider, surface: message.executionSurface)
            let providerColor = message.provider == "local"
                ? TimelinePalette.green
                : (message.provider == "claude" ? TimelinePalette.claude : TimelinePalette.codex)
            appendBlock(
                role: MessageRole.assistant.rawValue,
                components: [
                    ("\(provider)", NSFont.systemFont(ofSize: 10, weight: .medium), providerColor),
                    ("\n\n", NSFont.systemFont(ofSize: 6), TimelinePalette.muted),
                ],
                richContent: assistantDisplayText(messages: messages, index: index, expanded: expanded, expandAll: expandAll, sourceStore: sourceStore)
            )
        case .receipt:
            let key = "\(message.id.uuidString)-receipt"
            let show = expandAll || expanded.contains(key)
            // Pasted back, these lines are recognised as OS-1 output in both
            // languages (OS1SelfOutput.lineMarkers, OS1ReceiptText.fingerprints).
            let status = message.nativeRecordVerified == true
                ? os1Tr("실행 기록 확인됨", "Execution record verified") : os1Tr("실행 기록 미확인", "Execution record unverified")
            let details = NSMutableAttributedString(attributedString: TranscriptMarkdown.detailLink(
                "\(status) · \(show ? os1Tr("세부 정보 접기", "Hide details") : os1Tr("세부 정보 보기", "Show details"))", key: key,
                color: TimelinePalette.detail))
            if show {
                details.append(NSAttributedString(string: os1Tr("\u{2028}백엔드 실행 기록의 확인 여부입니다. 답변의 정확성이나 과제 완수를 보증하지 않습니다.\u{2028}",
                                                                "\u{2028}Whether the backend's execution record was verified. It does not vouch for the answer's accuracy or the task's completion.\u{2028}"),
                                                  attributes: [.font: NSFont.systemFont(ofSize: 11), .foregroundColor: TimelinePalette.muted]))
                details.append(NSAttributedString(string: timelineNormalizedText(historicalRouteFanoutDetails(messages: messages, index: index, sourceStore: sourceStore) ?? message.text), attributes: [.font: NSFont.monospacedSystemFont(ofSize: 11, weight: .regular), .foregroundColor: TimelinePalette.muted]))
            }
            appendBlock(
                role: MessageRole.receipt.rawValue,
                components: [], richContent: details
            )
        case .system:
            appendBlock(
                role: MessageRole.system.rawValue,
                components: [
                    ("◇  ", NSFont.systemFont(ofSize: 12, weight: .bold), TimelinePalette.pink),
                    (
                        timelineNormalizedText(message.text),
                        NSFont.systemFont(ofSize: 12, weight: .medium),
                        TimelinePalette.muted
                    ),
                ]
            )
        }
    }

    // Pending requests belong to ConversationQueueView, not the sent transcript.

    if isRunning {
        if let publicProgress {
            appendLiveProgress(liveProgress(after: steeredAfter, in: publicProgress), key: "live-progress")
        }
        // Activity, elapsed time and steps have one owner: this last row,
        // one line until the owner opens it, as Codex shows a working turn.
        if let liveRun {
            appendBlock(role: "liveRun", components: [], richContent: liveRunRow(liveRun, expanded: liveRunExpanded),
                trailingSpacing: 8)
        }
    }

    return document.copy() as! NSAttributedString
}

private func transcriptLatencySelfTest() throws {
    func check(_ ok: Bool, _ why: String) throws { if !ok { throw RunnerError.message("Transcript latency: " + why) } }
    let messages = (0..<100).map { i in ChatMessage(role: .assistant,
        text: "## History \(i)\n" + String(repeating: "Unchanged **native** text.\n", count: 40)) }
    let session = UUID(), cache = TranscriptRenderCache()
    var input = TranscriptRenderInput(sessionID: session, messages: messages, queued: [], isRunning: true, workspace: "/tmp")
    var maxMS = 0.0
    var originalPrefix: NSAttributedString?
    for i in 0..<40 {
        input.publicProgress = "## Native stream\n" + String(repeating: "unchanged public delta \(i)\n", count: i + 1)
        let start = Date(), parts = cache.parts(input, expanded: [])
        if i == 0 { originalPrefix = parts.prefix }
        else {
            try check(!parts.rebuilt && parts.prefix === originalPrefix, "history reparsed on live delta")
            maxMS = max(maxMS, Date().timeIntervalSince(start) * 1000)
        }
        let joined = NSMutableAttributedString(attributedString: parts.prefix); joined.append(parts.tail)
        let reference = timelineAttributedDocument(messages: messages, queuedSubmissions: [], isRunning: true,
            workspace: "/tmp", publicProgress: input.publicProgress)
        try check(joined.string == reference.string, "cached suffix changed transcript content")
        try check(joined.attribute(.os1TimelineRole, at: joined.length - 2, effectiveRange: nil) as? String == "assistant", "suffix lost role")
        try check(joined.string.contains("아직 검증되지 않은 출력"), "preview mislabeled as adopted")
    }
    try check(cache.prefixBuildCount == 1, "100-message history not cached")
    _ = cache.parts(input, expanded: ["changed-code-disclosure"])
    try check(cache.prefixBuildCount == 2, "expanded state not in cache identity")
    // A steered input sits after the output on screen when it was sent. The
    // output above it joins the cached history; only what streams after it
    // stays the live suffix, so deltas still never reparse the history.
    let shown = "## Native stream\nOUTPUT_BEFORE_STEER " + String(repeating: "앞선 출력 ", count: 30)
    var steer = ChatMessage(role: .user, text: "STEER_INPUT_SENTINEL"); steer.steeringDelivery = .pending
    var steered = TranscriptRenderInput(sessionID: session, messages: Array(messages.prefix(3)) + [steer], queued: [],
        isRunning: true, workspace: "/tmp", progressAnchors: [steer.id: shown])
    let steeredCache = TranscriptRenderCache()
    var steeredPrefix: NSAttributedString?
    for i in 0..<12 {
        steered.publicProgress = shown + "\n\n" + String(repeating: "OUTPUT_AFTER_STEER \(i)\n", count: i)
        let parts = steeredCache.parts(steered, expanded: [])
        if i == 0 { steeredPrefix = parts.prefix }
        else { try check(!parts.rebuilt && parts.prefix === steeredPrefix, "history reparsed on a delta after steering") }
        let joined = NSMutableAttributedString(attributedString: parts.prefix); joined.append(parts.tail)
        let reference = timelineAttributedDocument(messages: steered.messages, queuedSubmissions: [], isRunning: true,
            workspace: "/tmp", publicProgress: steered.publicProgress, progressAnchors: steered.progressAnchors)
        try check(joined.string == reference.string, "cached suffix changed the steered transcript")
        let text = joined.string as NSString
        let earlier = text.range(of: "OUTPUT_BEFORE_STEER").location, bubble = text.range(of: "STEER_INPUT_SENTINEL").location
        try check(earlier != NSNotFound && bubble != NSNotFound && earlier < bubble, "steered input drew above the output it followed")
        try check(joined.string.components(separatedBy: "OUTPUT_BEFORE_STEER").count == 2, "output before the steer drawn twice")
        let later = text.range(of: "OUTPUT_AFTER_STEER").location
        try check(i == 0 ? parts.tail.length == 0 : later != NSNotFound && later > bubble,
            "output after the steer drew above the steered input")
    }
    input = TranscriptRenderInput(sessionID: session, messages: messages, queued: [], isRunning: false, workspace: "/tmp")
    let finished = cache.parts(input, expanded: [])
    try check(finished.rebuilt && finished.tail.length == 0, "pending suffix survived completion")
    print("OS-1 transcript relay: 100-message history rendered once / 40 deltas; max warm suffix \(String(format: "%.2f", maxMS)) ms; content/role/pending/expansion/final boundaries OK")
}

private func completeTranscriptText(_ messages: [ChatMessage]) -> String {
    messages.map { message in
        let title = message.role == .user ? "USER" : message.role == .receipt ? os1Tr("실행 기록 (정확성 보증 아님)", "Execution record (no accuracy guarantee)") : providerDisplayName(message.provider, surface: message.executionSurface)
        return "\(title)\n\(message.text)"
    }.joined(separator: "\n\n")
}

private final class TranscriptSnapshotSurface: NSView {
    override var isFlipped: Bool { true }
    override var isOpaque: Bool { true }
    override func draw(_ dirtyRect: NSRect) { NSColor.black.setFill(); dirtyRect.fill() }
}

private final class ContinuousTranscriptTextView: NSTextView {
    /// Never accept a dragged file: the window-wide handler attaches it to the
    /// conversation instead. Returning an empty operation lets the drag fall
    /// through to the SwiftUI container behind this view.
    override func draggingEntered(_ sender: any NSDraggingInfo) -> NSDragOperation { [] }
    override func draggingUpdated(_ sender: any NSDraggingInfo) -> NSDragOperation { [] }
    override func performDragOperation(_ sender: any NSDraggingInfo) -> Bool { false }

    var completeTranscript = ""
    var progressSession: UUID?
    var progressText: String?

    override func menu(for event: NSEvent) -> NSMenu? {
        let menu = super.menu(for: event) ?? NSMenu()
        menu.addItem(.separator())
        let item = NSMenuItem(title: os1Tr("대화 전체 복사 (코드·실행 기록 포함)",
                                           "Copy entire conversation (including code and execution records)"), action: #selector(copyCompleteTranscript), keyEquivalent: "")
        item.target = self
        menu.addItem(item)
        return menu
    }

    @objc func copyCompleteTranscript(_ sender: Any?) {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(completeTranscript, forType: .string)
    }
    override func setFrameSize(_ newSize: NSSize) {
        super.setFrameSize(newSize)
        let centeredInset = max(32, (newSize.width - Theme.conversationWidth) / 2)
        if abs(textContainerInset.width - centeredInset) > 0.5 {
            textContainerInset = NSSize(width: centeredInset, height: 34)
        }
    }

    override func draw(_ dirtyRect: NSRect) {
        drawMessageBackgrounds(in: dirtyRect)
        super.draw(dirtyRect)
        if let progressSession { ActivityDisplayTiming.didDraw(session: progressSession, text: progressText) }
    }

    override func copy(_ sender: Any?) {
        guard let selected = normalizedSelectedText() else {
            super.copy(sender)
            return
        }
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(selected, forType: .string)
    }

    func normalizedSelectedText() -> String? {
        let range = selectedRange()
        guard range.location != NSNotFound,
              range.length > 0,
              NSMaxRange(range) <= (string as NSString).length else { return nil }
        return MathTypesetter.copyable(attributedString().attributedSubstring(from: range))
    }

    func timelineFrames() -> [(role: String, content: NSRect, paint: NSRect)] {
        guard let textStorage,
              let layoutManager,
              let textContainer,
              textStorage.length > 0 else { return [] }
        var frames: [(role: String, content: NSRect, paint: NSRect)] = []
        layoutManager.ensureLayout(for: textContainer)
        let origin = textContainerOrigin
        let fullRange = NSRange(location: 0, length: textStorage.length)
        textStorage.enumerateAttribute(.os1TimelineRole, in: fullRange) { value, range, _ in
            guard let role = value as? String else { return }
            let glyphRange = layoutManager.glyphRange(
                forCharacterRange: range,
                actualCharacterRange: nil
            )
            // `boundingRect(forGlyphRange:)` can include the whole aligned line
            // fragment for a right-aligned paragraph. That made a short user
            // message paint as a full-width bubble. Use each line's used rect
            // instead: it is the actual glyph envelope, so the bubble follows
            // the text like Codex while retaining the transcript's wrap width.
            var rect = NSRect.null
            layoutManager.enumerateLineFragments(forGlyphRange: glyphRange) { _, usedRect, _, _, _ in
                var glyphRect = usedRect
                glyphRect.origin.x += origin.x
                glyphRect.origin.y += origin.y
                rect = rect.union(glyphRect)
            }
            if rect.isNull {
                rect = layoutManager.boundingRect(forGlyphRange: glyphRange, in: textContainer)
                rect.origin.x += origin.x
                rect.origin.y += origin.y
            }
            let contentRect = rect
            switch role {
            case MessageRole.user.rawValue:
                rect = rect.insetBy(dx: -18, dy: -13)
            case MessageRole.receipt.rawValue:
                rect.origin.x = origin.x
                rect.size.width = max(0, textContainer.size.width)
                rect = rect.insetBy(dx: -16, dy: -12)
            case "queued":
                rect = rect.insetBy(dx: -16, dy: -12)
            default:
                break
            }
            frames.append((role, contentRect, rect))
        }
        return frames
    }

    func tableFrames() -> [[String: Any]] {
        guard let textStorage, let layoutManager, let textContainer else { return [] }
        layoutManager.ensureLayout(for: textContainer)
        var cells: [[String: Any]] = []
        textStorage.enumerateAttribute(.paragraphStyle, in: NSRange(location: 0, length: textStorage.length)) { value, range, _ in
            guard let cell = (value as? NSParagraphStyle)?.textBlocks.first as? NSTextTableBlock else { return }
            let glyphs = layoutManager.glyphRange(forCharacterRange: range, actualCharacterRange: nil)
            let rect = layoutManager.boundsRect(for: cell, glyphRange: glyphs).offsetBy(dx: self.textContainerOrigin.x, dy: self.textContainerOrigin.y)
            cells.append(["row": cell.startingRow, "column": cell.startingColumn,
                "text": textStorage.attributedSubstring(from: range).string,
                "x": rect.minX, "y": rect.minY, "width": rect.width, "height": rect.height])
        }
        return cells
    }

    private func drawMessageBackgrounds(in dirtyRect: NSRect) {
        for frame in timelineFrames() {
            switch frame.role {
            case MessageRole.user.rawValue:
                drawRoundedBackground(frame.paint, fill: TimelinePalette.userBubble, stroke: NSColor.clear, dirtyRect: dirtyRect)
            case MessageRole.receipt.rawValue:
                drawRoundedBackground(frame.paint, fill: NSColor.clear, stroke: NSColor.clear, dirtyRect: dirtyRect)
            case "queued":
                drawRoundedBackground(frame.paint, fill: TimelinePalette.panelRaised, stroke: TimelinePalette.pink.withAlphaComponent(0.24), dirtyRect: dirtyRect)
            default: break
            }
        }
    }

    private func drawRoundedBackground(
        _ rect: NSRect,
        fill: NSColor,
        stroke: NSColor,
        dirtyRect: NSRect
    ) {
        guard rect.intersects(dirtyRect), rect.width > 0, rect.height > 0 else { return }
        let path = NSBezierPath(roundedRect: rect, xRadius: 16, yRadius: 16)
        fill.setFill()
        path.fill()
        stroke.setStroke()
        path.lineWidth = 1
        path.stroke()
    }
}

private struct TranscriptRenderInput: Equatable {
    let sessionID: UUID
    let messages: [ChatMessage]
    let queued: [PendingSubmission]
    let isRunning: Bool
    let workspace: String
    var publicProgress: String? = nil
    /// Part of the render identity: a queued bubble's caption changes when
    /// the reason it waits changes (slot freed, hold released) without any
    /// message edit.
    var waitingReason: String? = nil
    /// Live output on screen when each steered input appeared. Fixed once
    /// set, so it belongs to the cached history, not the live suffix.
    var progressAnchors: [UUID: String] = [:]
    /// The live run's last row and its disclosure; the live suffix only.
    var liveRun: LiveRunPresentation? = nil
    var liveRunExpanded = false
}

/// Immutable history is keyed by all render-relevant input, not by time or
/// session name. Only the live suffix changes on native text deltas, and a
/// clock tick changes only the live run's row within it.
private final class TranscriptRenderCache {
    struct Parts {
        let prefix: NSAttributedString
        /// Reused by identity until the live output itself changes.
        let progress: NSAttributedString
        let row: NSAttributedString
        let rebuilt: Bool
        var tail: NSAttributedString {
            guard row.length > 0 else { return progress }
            let joined = NSMutableAttributedString(attributedString: progress); joined.append(row)
            return joined
        }
    }
    private struct ProgressInput: Equatable {
        let isRunning: Bool
        let workspace: String
        let text: String?
        let follows: String?
        /// The live feed's tool-call lines open in place.
        let expanded: Set<String>
    }
    private var input: TranscriptRenderInput?
    private var expanded = Set<String>()
    private var prefix = NSAttributedString(string: "")
    private var progressInput: ProgressInput?
    private var progress = NSAttributedString(string: "")
    private(set) var prefixBuildCount = 0
    private(set) var progressBuildCount = 0

    /// `workLogStore` holds finished runs' work feeds; it never changes for
    /// a view, so it is not part of the render identity.
    func parts(_ value: TranscriptRenderInput, expanded: Set<String>,
               workLogStore: NativePublicRunLogStore = NativePublicRunLogStore()) -> Parts {
        var stable = value; stable.publicProgress = nil; stable.liveRun = nil; stable.liveRunExpanded = false
        let rebuilt = input != stable || self.expanded != expanded
        if rebuilt {
            prefix = timelineAttributedDocument(messages: value.messages, queuedSubmissions: value.queued,
                isRunning: value.isRunning, workspace: value.workspace, expanded: expanded, waitingReason: value.waitingReason,
                progressAnchors: value.progressAnchors, workLogStore: workLogStore)
            input = stable; self.expanded = expanded; prefixBuildCount += 1
        }
        // Output already drawn above the latest steered input stays there;
        // the suffix holds only what streamed after it.
        let key = ProgressInput(isRunning: value.isRunning, workspace: value.workspace, text: value.publicProgress,
            follows: value.isRunning ? latestSteeringAnchor(value.messages, value.progressAnchors) : nil,
            expanded: value.isRunning ? expanded : [])
        if key != progressInput {
            progress = timelineAttributedDocument(messages: [], queuedSubmissions: [], isRunning: value.isRunning,
                workspace: value.workspace, expanded: key.expanded, publicProgress: value.publicProgress, progressFollows: key.follows)
            progressInput = key; progressBuildCount += 1
        }
        let row = value.isRunning && value.liveRun != nil
            ? timelineAttributedDocument(messages: [], queuedSubmissions: [], isRunning: true, workspace: value.workspace,
                liveRun: value.liveRun, liveRunExpanded: value.liveRunExpanded)
            : NSAttributedString(string: "")
        return Parts(prefix: prefix, progress: progress, row: row, rebuilt: rebuilt)
    }
    func invalidate() { input = nil; progressInput = nil }
}

private final class TranscriptClipView: NSClipView {
    override func scroll(to newOrigin: NSPoint) {
        super.scroll(to: newOrigin)
        // AppKit can otherwise reuse partial rows from a transparent table
        // during live scrolling. Invalidate the visible region, not the entire
        // transcript, and never alter the selection or text storage.
        documentView?.setNeedsDisplay(documentVisibleRect)
    }
}

private struct ContinuousTranscriptView: NSViewRepresentable {
    let sessionID: UUID
    let messages: [ChatMessage]
    let queuedSubmissions: [PendingSubmission]
    let isRunning: Bool
    let workspace: String
    var publicProgress: String? = nil
    var waitingReason: String? = nil
    var progressAnchors: [UUID: String] = [:]
    var liveRun: LiveRunPresentation? = nil
    /// Where finished runs' work feeds are kept (a fixture store's own).
    var workLogStore = NativePublicRunLogStore()

    final class Coordinator: NSObject, NSTextViewDelegate {
        var renderedSessionID: UUID?
        var hasRendered = false
        var hasRenderedMessages = false
        var expanded = Set<String>()
        /// A new run's feed starts with its tool-call lines closed.
        private var wasRunning = false
        /// The live row's disclosure is a view preference, not message state:
        /// it starts collapsed and holds across runs and conversations.
        var liveRunExpanded = false
        var content: ContinuousTranscriptView?
        var lastInput: TranscriptRenderInput?
        /// The live output last written after the history. While the cache
        /// returns the same object, a clock tick rewrites only the live row.
        private var appliedProgress: NSAttributedString?
        let renderCache = TranscriptRenderCache()

        func textView(_ textView: NSTextView, clickedOnLink link: Any, at charIndex: Int) -> Bool {
            guard let url = link as? URL, url.scheme == "os1-detail", let content else { return false }
            let key = url.lastPathComponent
            if key == liveRunDetailKey {
                // Only the live row changes; the history keeps its rendering.
                liveRunExpanded.toggle()
                if let scrollView = textView.enclosingScrollView { render(content, in: scrollView) }
                return true
            }
            if expanded.contains(key) { expanded.remove(key) } else { expanded.insert(key) }
            let scroll = textView.enclosingScrollView
            let origin = scroll?.contentView.bounds.origin
            let document = timelineAttributedDocument(messages: content.messages, queuedSubmissions: content.queuedSubmissions,
                isRunning: content.isRunning, workspace: content.workspace, expanded: expanded, publicProgress: content.publicProgress,
                waitingReason: content.waitingReason, progressAnchors: content.progressAnchors,
                liveRun: content.liveRun, liveRunExpanded: liveRunExpanded, workLogStore: content.workLogStore)
            textView.textStorage?.setAttributedString(document)
            renderCache.invalidate(); lastInput = nil; appliedProgress = nil
            textView.needsDisplay = true
            if let origin { scroll?.contentView.scroll(to: origin) }
            return true
        }

        @MainActor func render(_ view: ContinuousTranscriptView, in scrollView: NSScrollView) {
            guard let textView = scrollView.documentView as? ContinuousTranscriptTextView else { return }
            let changingSession = renderedSessionID != view.sessionID
            if changingSession { expanded.removeAll() }
            if view.isRunning, !wasRunning || changingSession { expanded = expanded.filter { !$0.hasPrefix(liveFeedKey + "-") } }
            wasRunning = view.isRunning
            content = view
            let input = TranscriptRenderInput(sessionID: view.sessionID, messages: view.messages,
                queued: view.queuedSubmissions, isRunning: view.isRunning, workspace: view.workspace, publicProgress: view.publicProgress,
                waitingReason: view.waitingReason, progressAnchors: view.progressAnchors,
                liveRun: view.liveRun, liveRunExpanded: liveRunExpanded)
            // Math attachments have object identity. Comparing freshly rendered
            // attributed strings would rewrite the text storage on every keystroke.
            guard lastInput != input else { return }
            lastInput = input
            let renderStarted = Date()
            let parts = renderCache.parts(input, expanded: expanded, workLogStore: view.workLogStore)
            let rebuildBaseline = parts.rebuilt
            if rebuildBaseline { textView.completeTranscript = completeTranscriptText(view.messages) }
            let prefixLength = parts.prefix.length
            let documentLength = prefixLength + parts.progress.length + parts.row.length
            let selection = textView.selectedRange()
            let distanceFromBottom = max(0, textView.bounds.height - scrollView.contentView.bounds.maxY)
            let firstMessages = !view.messages.isEmpty && (!hasRenderedMessages || changingSession)
            let shouldFollowBottom = !hasRendered || changingSession || firstMessages || distanceFromBottom < 80
            // A clock tick redraws the live row alone; it applies no new output.
            let outputApplied = rebuildBaseline || parts.progress !== appliedProgress
            if let storage = textView.textStorage {
                let rowStart = prefixLength + parts.progress.length
                if rebuildBaseline || storage.length < prefixLength {
                    let document = NSMutableAttributedString(attributedString: parts.prefix)
                    document.append(parts.tail)
                    storage.setAttributedString(document)
                } else if parts.progress === appliedProgress, storage.length >= rowStart {
                    storage.replaceCharacters(in: NSRange(location: rowStart, length: storage.length - rowStart), with: parts.row)
                } else {
                    storage.replaceCharacters(in: NSRange(location: prefixLength, length: storage.length - prefixLength), with: parts.tail)
                }
                appliedProgress = parts.progress
            }
            textView.progressSession = view.isRunning ? view.sessionID : nil
            textView.progressText = view.publicProgress
            textView.needsDisplay = true
            if !changingSession, selection.location != NSNotFound {
                let boundedLocation = min(selection.location, documentLength)
                let boundedLength = min(selection.length, documentLength - boundedLocation)
                textView.setSelectedRange(NSRange(location: boundedLocation, length: boundedLength))
            }
            if outputApplied { ActivityDisplayTiming.applied(session: view.sessionID, text: view.publicProgress, started: renderStarted) }
            renderedSessionID = view.sessionID
            hasRendered = true
            hasRenderedMessages = !view.messages.isEmpty
            if shouldFollowBottom, changingSession || selection.length == 0 {
                DispatchQueue.main.async {
                    if let container = textView.textContainer { textView.layoutManager?.ensureLayout(for: container) }
                    scrollView.layoutSubtreeIfNeeded()
                    textView.scrollToEndOfDocument(nil)
                    scrollView.reflectScrolledClipView(scrollView.contentView)
                }
            }
        }
    }

    func makeCoordinator() -> Coordinator { Coordinator() }

    func makeNSView(context: Context) -> NSScrollView { Self.makeScrollView(delegate: context.coordinator) }

    static func makeScrollView(delegate: Coordinator) -> NSScrollView {
        let scrollView = NSScrollView()
        scrollView.drawsBackground = false
        scrollView.contentView = TranscriptClipView()
        scrollView.contentView.drawsBackground = false
        scrollView.hasVerticalScroller = true
        scrollView.hasHorizontalScroller = false
        scrollView.autohidesScrollers = true
        scrollView.borderType = .noBorder

        let textView = ContinuousTranscriptTextView(frame: scrollView.contentView.bounds)
        textView.delegate = delegate
        textView.linkTextAttributes = TimelinePalette.linkAttributes
        textView.drawsBackground = false
        textView.isEditable = false
        textView.isSelectable = true
        textView.isRichText = true
        textView.importsGraphics = false
        // A file dropped on the conversation must reach the window-wide
        // attachment handler. NSTextView registers its own dragged types and
        // consumes the drop first, which is why dropping anywhere except the
        // input box did nothing.
        textView.unregisterDraggedTypes()
        textView.allowsUndo = false
        textView.usesFindPanel = true
        textView.usesFindBar = true
        textView.isIncrementalSearchingEnabled = true
        textView.usesFontPanel = false
        textView.isHorizontallyResizable = false
        textView.isVerticallyResizable = true
        textView.autoresizingMask = [.width]
        textView.minSize = NSSize(width: 0, height: scrollView.contentSize.height)
        textView.maxSize = NSSize(
            width: CGFloat.greatestFiniteMagnitude,
            height: CGFloat.greatestFiniteMagnitude
        )
        textView.textContainerInset = NSSize(width: 40, height: 34)
        textView.textContainer?.lineFragmentPadding = 0
        textView.textContainer?.widthTracksTextView = true
        textView.layoutManager?.allowsNonContiguousLayout = false
        textView.textContainer?.containerSize = NSSize(
            width: scrollView.contentSize.width,
            height: CGFloat.greatestFiniteMagnitude
        )
        textView.setAccessibilityLabel("OS-1 conversation transcript")
        scrollView.documentView = textView
        return scrollView
    }

    func updateNSView(_ scrollView: NSScrollView, context: Context) {
        context.coordinator.render(self, in: scrollView)
    }
}

/// One entry per whole second of the live run, so its row's clock neither
/// skips nor repeats a second; a single entry, so no redraw, while idle.
private struct LiveRunTicks: TimelineSchedule, Equatable {
    let started: Date?
    func entries(from startDate: Date, mode: TimelineScheduleMode) -> AnyIterator<Date> {
        guard let started else { return AnyIterator([startDate].makeIterator()) }
        // Whole seconds counted from the start, never a sum of steps that drifts.
        var second = max(0, startDate.timeIntervalSince(started).rounded(.down))
        return AnyIterator {
            defer { second += 1 }
            return started.addingTimeInterval(second)
        }
    }
}

private struct MessageTimeline: View {
    let session: ConversationSession
    let isRunning: Bool
    let queuedSubmissions: [PendingSubmission]
    var publicProgress: String? = nil
    var waitingReason: String? = nil
    var progressAnchors: [UUID: String] = [:]
    var liveRun: LiveRunPresentation? = nil
    var workLogStore = NativePublicRunLogStore()

    var body: some View {
        // Outside the timeline: a clock tick must not re-read saved results.
        let messages = presentedMessages(session)
        TimelineView(LiveRunTicks(started: isRunning ? liveRun?.started : nil)) { context in
            ContinuousTranscriptView(
                sessionID: session.id,
                messages: messages,
                queuedSubmissions: queuedSubmissions,
                isRunning: isRunning,
                workspace: session.workspace,
                publicProgress: publicProgress,
                waitingReason: waitingReason,
                progressAnchors: progressAnchors,
                liveRun: isRunning ? liveRun?.at(context.date) : nil,
                workLogStore: workLogStore
            )
        }
    }
}

/// Keeps SwiftUI's native focus, accessibility, undo, and IME behavior while
/// applying Codex's Return-to-send convention only to the focused composer.
@MainActor
private final class ComposerKeyMonitor: ObservableObject {
    var isFocused = false
    var submit: (() -> Void)?
    var cancelVoice: (() -> Bool)?
    private var eventMonitor: Any?

    func start() {
        guard eventMonitor == nil else { return }
        eventMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [weak self] event in
            guard let self, self.isFocused else { return event }
            // A queue editor is a separate sheet. Return there edits text and
            // must never submit the unrelated main composer behind the sheet.
            guard NSApp.keyWindow?.sheetParent == nil, NSApp.modalWindow == nil else { return event }
            if event.keyCode == 53, self.cancelVoice?() == true {
                return nil
            }
            let isReturn = event.keyCode == 36 || event.keyCode == 76
            guard isReturn,
                  composerReturnAction(shiftPressed: event.modifierFlags.contains(.shift)) == .send else {
                return event
            }
            if let textView = NSApp.keyWindow?.firstResponder as? NSTextView,
               textView.hasMarkedText() {
                return event
            }
            self.submit?()
            return nil
        }
    }

    func stop() {
        if let eventMonitor { NSEvent.removeMonitor(eventMonitor) }
        eventMonitor = nil
    }

}

/// A composer text view that consumes file drags before AppKit can turn them
/// into a pasted `file://` URL or bare path. The files are handed to the
/// shared attachment state instead, so dropping into the text field behaves
/// the same as dropping anywhere else in the OS-1 window.
// Internal, not private: a private NSObject subclass gets a per-file hash in
// its Objective-C class name (_TtC6OS1AppP33_<hash>…), and the release
// payload scanner rightly flags such 80-character high-entropy tokens.
final class ComposerDropTextView: NSTextView {
    var onFocusChange: ((Bool) -> Void)?

    // Key handling (Return sends) is gated on the composer being focused.
    // "Focused" means first responder — not "the user has typed", which is
    // what the delegate's textDidBeginEditing reports, so a pasted or
    // dictated draft followed by Return must still send.
    override func becomeFirstResponder() -> Bool {
        let accepted = super.becomeFirstResponder()
        if accepted { onFocusChange?(true) }
        return accepted
    }

    override func resignFirstResponder() -> Bool {
        let accepted = super.resignFirstResponder()
        if accepted { onFocusChange?(false) }
        return accepted
    }

    /// AppKit turns a dropped file into its path as text. This view is a
    /// drag destination for text only; a file drag never reaches it and
    /// falls through to the composer's own drop target, which attaches the
    /// file exactly as a drop anywhere else in the window does.
    func acceptTextDragsOnly() {
        unregisterDraggedTypes()
        registerForDraggedTypes([.string])
    }

    /// NSTextView re-registers its full drag-type set lazily — on the first
    /// draw, after editability changes — which silently undid the one-shot
    /// registration above in every real launch (caught by an adversarial
    /// verifier reproducing the sequence with ctypes). Re-apply it whenever
    /// AppKit refreshes the registration.
    override func updateDragTypeRegistration() {
        super.updateDragTypeRegistration()
        acceptTextDragsOnly()
    }

    // Belt and braces, as on the transcript view: even if a file drag does
    // reach this view, it is declined so the drag falls through to the
    // composer's drop target instead of becoming inserted path text.
    private func carriesFiles(_ info: NSDraggingInfo) -> Bool {
        info.draggingPasteboard.canReadObject(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true])
    }
    override func draggingEntered(_ sender: NSDraggingInfo) -> NSDragOperation { carriesFiles(sender) ? [] : super.draggingEntered(sender) }
    override func draggingUpdated(_ sender: NSDraggingInfo) -> NSDragOperation { carriesFiles(sender) ? [] : super.draggingUpdated(sender) }
    override func prepareForDragOperation(_ sender: NSDraggingInfo) -> Bool { carriesFiles(sender) ? false : super.prepareForDragOperation(sender) }
    override func performDragOperation(_ sender: NSDraggingInfo) -> Bool { carriesFiles(sender) ? false : super.performDragOperation(sender) }
}

/// Native AppKit bridge retained for the composer so it keeps normal IME,
/// focus, undo, and accessibility while preventing raw dropped paths from
/// being inserted into the owner's draft.
struct NativeComposerEditor: NSViewRepresentable {
    @Binding var text: String
    let onFocusChange: (Bool) -> Void
    var onSubmit: (() -> Void)? = nil

    func makeCoordinator() -> Coordinator { Coordinator(self) }

    func makeNSView(context: Context) -> NSScrollView {
        let (scrollView, textView) = Self.makeConfiguredEditor(text: text)
        textView.delegate = context.coordinator
        textView.onFocusChange = onFocusChange
        return scrollView
    }

    /// The production editor, exactly as hosted — shared with the self-test
    /// so the test exercises the real configuration, not a lookalike.
    static func makeConfiguredEditor(text: String) -> (NSScrollView, ComposerDropTextView) {
        let textView = ComposerDropTextView()
        textView.acceptTextDragsOnly()
        textView.isRichText = false
        textView.allowsUndo = true
        textView.isAutomaticQuoteSubstitutionEnabled = false
        textView.isAutomaticTextReplacementEnabled = false
        textView.isContinuousSpellCheckingEnabled = true
        textView.font = .systemFont(ofSize: 14, weight: .medium)
        textView.textColor = .white.withAlphaComponent(0.95)
        textView.backgroundColor = .clear
        textView.drawsBackground = false
        textView.textContainerInset = NSSize(width: 4, height: 6)
        textView.isVerticallyResizable = true
        textView.isHorizontallyResizable = false
        textView.textContainer?.widthTracksTextView = true
        textView.string = text

        let scrollView = NSScrollView()
        scrollView.documentView = textView
        scrollView.drawsBackground = false
        scrollView.hasVerticalScroller = true
        scrollView.autohidesScrollers = true
        scrollView.borderType = .noBorder
        return (scrollView, textView)
    }

    func updateNSView(_ scrollView: NSScrollView, context: Context) {
        context.coordinator.parent = self
        guard let textView = scrollView.documentView as? ComposerDropTextView else { return }
        textView.onFocusChange = onFocusChange
        if textView.string != text { textView.string = text }
        if !context.coordinator.requestedInitialFocus, scrollView.window != nil {
            context.coordinator.requestedInitialFocus = true
            DispatchQueue.main.async {
                textView.window?.makeFirstResponder(textView)
            }
        }
    }

    final class Coordinator: NSObject, NSTextViewDelegate {
        var parent: NativeComposerEditor
        var requestedInitialFocus = false

        init(_ parent: NativeComposerEditor) { self.parent = parent }

        /// Return while a Korean syllable is still being composed: the key
        /// monitor hands the event to AppKit so the input method can commit
        /// the syllable, and AppKit then delivers `insertNewline:` here. That
        /// is the send, unless Shift asked for a line break — the owner
        /// types Korean, and a second Return to send was the old behaviour.
        func textView(_ textView: NSTextView, doCommandBy commandSelector: Selector) -> Bool {
            guard commandSelector == #selector(NSResponder.insertNewline(_:)), let submit = parent.onSubmit else { return false }
            let shift = NSApp.currentEvent?.modifierFlags.contains(.shift) ?? false
            guard composerReturnAction(shiftPressed: shift) == .send else { return false }
            submit()
            return true
        }

        func textDidChange(_ notification: Notification) {
            guard let textView = notification.object as? NSTextView, parent.text != textView.string else { return }
            parent.text = textView.string
        }
    }
}

private struct ClodexComposerEditor: View {
    @Binding var text: String
    let onSubmit: () -> Void
    let onCancelVoice: () -> Bool
    @StateObject private var keyMonitor = ComposerKeyMonitor()

    var body: some View {
        NativeComposerEditor(
            text: $text,
            onFocusChange: { focused in keyMonitor.isFocused = focused },
            onSubmit: onSubmit
        )
            .onAppear {
                keyMonitor.submit = onSubmit
                keyMonitor.cancelVoice = onCancelVoice
                keyMonitor.start()
            }
            .onDisappear {
                keyMonitor.isFocused = false
                keyMonitor.stop()
            }
    }
}

private struct VoiceWaveform: View {
    let level: CGFloat

    private let weights: [CGFloat] = [0.44, 0.72, 1, 0.62, 0.86]

    var body: some View {
        HStack(alignment: .center, spacing: 3) {
            ForEach(Array(weights.enumerated()), id: \.offset) { _, weight in
                Capsule()
                    .fill(Theme.pink)
                    .frame(width: 3, height: 6 + (max(0.12, level) * 17 * weight))
            }
        }
        .frame(width: 28, height: 28)
        .animation(.easeOut(duration: 0.09), value: level)
        .accessibilityHidden(true)
    }
}

private struct VoiceDictationControl: View {
    @ObservedObject var controller: VoiceDictationController
    let start: () -> Void
    let finish: () -> Void
    let cancel: () -> Void

    var body: some View {
        Group {
            if controller.isActive {
                HStack(spacing: 6) {
                    Button(action: cancel) {
                        Image(systemName: "xmark")
                            .font(.system(size: 11, weight: .bold))
                            .frame(width: 30, height: 30)
                            .foregroundStyle(Theme.muted)
                    }
                    .buttonStyle(.plain)
                    .help("Cancel and restore the previous text (Esc)")
                    .accessibilityLabel("Cancel voice input")

                    if controller.isAuthorizing || controller.isFinalizing {
                        ProgressView()
                            .controlSize(.small)
                            .tint(Theme.pink)
                            .frame(width: 28, height: 28)
                    } else {
                        VoiceWaveform(level: controller.level)
                    }

                    VStack(alignment: .leading, spacing: 1) {
                        Text(controller.statusLabel)
                            .font(.system(size: 10, weight: .semibold))
                            .foregroundStyle(Theme.text)
                        Text("\(controller.engineLabel) · \(controller.elapsedLabel)")
                            .font(.system(size: 9, weight: .medium))
                            .foregroundStyle(Theme.muted)
                            .fixedSize()
                    }
                    .frame(minWidth: 52, alignment: .leading)

                    Button(action: finish) {
                        Image(systemName: "checkmark")
                            .font(.system(size: 12, weight: .bold))
                            .foregroundStyle(Color.black.opacity(0.86))
                            .frame(width: 32, height: 32)
                            .background(Theme.pink)
                            .clipShape(Circle())
                    }
                    .buttonStyle(.plain)
                    .disabled(controller.isFinalizing)
                    .help("Use this transcript")
                    .accessibilityLabel("Finish voice input")
                }
                .padding(.horizontal, 7)
                .padding(.vertical, 5)
                .background(Theme.panelRaised)
                .overlay(
                    Capsule().stroke(Theme.pink.opacity(0.56), lineWidth: 1)
                )
                .clipShape(Capsule())
                .transition(.opacity.combined(with: .scale(scale: 0.94)))
            } else {
                Button(action: start) {
                    Image(systemName: "mic.fill")
                        .font(.system(size: 13, weight: .semibold))
                        .foregroundStyle(Theme.text)
                        .frame(width: 32, height: 32)
                        .contentShape(Circle())
                }
                .buttonStyle(.plain)
                .help("Dictate task (⌘⇧Space)")
                .accessibilityLabel("Start voice input")
            }
        }
        .animation(.easeInOut(duration: 0.16), value: controller.isActive)
    }
}

/// Lifecycle metadata is NOT assistant speech or a task-success verdict.
/// No model text, tool input/result, reasoning or raw errors enter this model.
private struct NativeProgressPresentation {
    struct Row: Identifiable {
        let id: String
        let receivedAt: Date
        let label: String
        var processing = false
    }
    let counts: String?
    let rows: [Row]
    let receivedAt: Date
    let typed: Bool
    static func safeTool(_ raw: String?) -> String? {
        guard let raw, NativeExecutionProgress.safeToolName(raw) else { return nil }
        return raw
    }
    static func kindLabel(_ raw: String) -> String {
        switch raw {
        case "ready": return os1Tr("네이티브 준비 신호", "Native ready signal")
        case "responseStarted": return os1Tr("응답 시작 신호", "Response started signal")
        case "toolStarted": return os1Tr("도구 요청", "Tool requested")
        case "toolReturned": return os1Tr("도구 반환", "Tool returned")
        case "toolFailed": return os1Tr("도구 오류 반환 신호", "Tool error return signal")
        case "toolWorking": return os1Tr("도구 작업 신호", "Tool working signal")
        case "responseBoundary": return os1Tr("응답 경계 신호", "Response boundary signal")
        case "retrying": return os1Tr("재시도 신호 수신", "Retry signal received")
        case "processing": return os1Tr("모델 생성 신호 수신", "Model generation signal received")
        default: return os1Tr("네이티브 실행 신호", "Native run signal")
        }
    }
    init(activity: RuntimeActivity) {
        if let progress = activity.progress, progress.isValid {
            typed = true; receivedAt = progress.observedAt
            counts = os1Tr("요청 \(progress.toolsRequested) · 반환 \(progress.toolsReturned) · 미반환 \(progress.activeTools)",
                           "Requested \(progress.toolsRequested) · returned \(progress.toolsReturned) · not returned \(progress.activeTools)")
            rows = progress.events.suffix(12).map { event in
                let tool = Self.safeTool(event.tool).map { " · " + $0 } ?? ""
                let scope = event.scope == "main" ? "" : os1Tr(" · 하위 실행", " · subagent run")
                return Row(id: "\(event.sequence)|\(event.scope)|\(event.kind.rawValue)", receivedAt: event.observedAt,
                    label: Self.kindLabel(event.kind.rawValue) + tool + scope, processing: event.kind == .processing)
            }
        } else {
            typed = false; receivedAt = activity.timestamp; counts = nil
            if let tool = Self.safeTool(activity.tool) {
                rows = [Row(id: "legacy", receivedAt: activity.timestamp, label: os1Tr("관측된 도구 신호 · ", "Observed tool signal · ") + tool)]
            } else { rows = [] }
        }
    }
}

/// The backend's own step lines — Claude Code's "doing X" — relayed from its
/// stream. OS-1 adds only a fixed verb tied to the tool ("읽기"), the local
/// receipt time and the time since the request; a return is "반환", never
/// "완료". Labels arrive redacted and are redacted again on decode.
private struct NativeStepPresentation {
    typealias Step = NativeExecutionProgress.Step
    struct Row: Identifiable {
        let id: String
        let receivedAt: Date
        let text: String
        let glyph: String
        let stateText: String
        /// Set only while the step awaits its return in the latest ring.
        let waitingSince: Date?
        let subagent: Bool
        let detail: String?
        let segment: Int
    }
    static let visibleCount = 6

    static func verbText(_ verb: String?) -> String? {
        switch verb {
        case "run": return os1Tr("실행", "Run")
        case "read": return os1Tr("읽기", "Read")
        case "edit": return os1Tr("수정", "Edit")
        case "write": return os1Tr("작성", "Write")
        case "add": return os1Tr("추가", "Add")
        case "delete": return os1Tr("삭제", "Delete")
        case "search": return os1Tr("검색", "Search")
        case "find": return os1Tr("파일 찾기", "Find files")
        case "list": return os1Tr("목록", "List")
        case "fetch": return os1Tr("웹 열기", "Fetch")
        case "webSearch": return os1Tr("웹 검색", "Web search")
        case "agent": return os1Tr("하위 에이전트", "Subagent")
        case "plan": return os1Tr("계획", "Plan")
        case "view": return os1Tr("보기", "View")
        case "mcp": return "MCP"
        default: return nil
        }
    }
    /// "{verb} · {label}", the label alone, or the tool name until a label arrives.
    static func text(_ step: Step) -> String {
        guard let label = step.label, !label.isEmpty else {
            return NativeProgressPresentation.safeTool(step.tool) ?? os1Tr("도구", "Tool")
        }
        return verbText(step.verb).map { $0 + " · " + label } ?? label
    }
    /// A native-public UI line, not assistant narration or a completion claim.
    /// Lifecycle labels depend only on actual received native state.
    static func feedLine(_ step: Step) -> String {
        let state: String
        switch step.state {
        case .observed: state = os1Tr("관측", "observed")
        case .requested: state = os1Tr("요청", "requested")
        case .returned: state = os1Tr("반환", "returned")
        case .failed: state = os1Tr("오류 반환", "returned an error")
        }
        let scope = step.scope == "main" ? "" : os1Tr("하위 에이전트 · ", "Subagent · ")
        let detail = step.childToolUses.map { os1Tr(" · 하위 도구 ", " · child tool calls ") + String($0) } ?? ""
        return scope + text(step) + " — " + state + detail
    }
    /// A feed line without its subagent prefix, for a list that marks
    /// nesting with "↳" instead. Either language's prefix: the line keeps
    /// the language it was received in.
    static func feedText(_ line: String, nested: Bool) -> String {
        guard nested else { return line }
        for prefix in ["하위 에이전트 · ", "Subagent · "] where line.hasPrefix(prefix) { return String(line.dropFirst(prefix.count)) }
        return line
    }
    /// A subagent's call, by its recorded nesting or, in records from
    /// earlier builds, by the prefix its line was received with.
    static func isNested(_ call: NativePublicRunLog.DisplaySegment) -> Bool {
        call.nested || feedText(call.text, nested: true) != call.text
    }
    /// A run of tool calls on one line, as Claude Code and Codex fold them
    /// ("14 tool calls · run 7 · read 5"): the count and the fixed verb
    /// families, never a claim that a call ran or succeeded.
    /// `nested` counts the calls subagents made, kept apart from the turn's
    /// own as Claude Code shows them under the agent ("45 tool uses").
    static func toolSummary(_ verbs: [String?], nested: Int = 0) -> String {
        let families: [(verbs: Set<String>, ko: String, en: String)] = [
            (["run"], "실행", "run"), (["read", "view"], "읽기", "read"), (["edit", "write", "add", "delete"], "수정", "edit"),
            (["search", "find", "list"], "검색", "search"), (["fetch", "webSearch"], "웹", "web"),
            (["agent"], "하위 에이전트", "subagent"), (["plan"], "계획", "plan"), (["mcp"], "MCP", "MCP"),
        ]
        var counts = [Int](repeating: 0, count: families.count), other = 0
        for verb in verbs {
            if let family = families.firstIndex(where: { $0.verbs.contains(verb ?? "") }) { counts[family] += 1 } else { other += 1 }
        }
        var parts = families.indices.filter { counts[$0] > 0 }
            .map { os1Tr("\(families[$0].ko) \(counts[$0])", "\(families[$0].en) \(counts[$0])") }
        // Calls recorded before verbs were kept have none: no "other" alone.
        if !parts.isEmpty, other > 0 { parts.append(os1Tr("기타 \(other)", "other \(other)")) }
        var line = verbs.isEmpty ? [] : [os1Tr("도구 호출 \(verbs.count)회", verbs.count == 1 ? "1 tool call" : "\(verbs.count) tool calls")] + parts
        if nested > 0 {
            line.append(verbs.isEmpty
                ? os1Tr("하위 에이전트 도구 호출 \(nested)회", nested == 1 ? "1 subagent tool call" : "\(nested) subagent tool calls")
                : os1Tr("하위 에이전트 내부 \(nested)회", "\(nested) inside subagents"))
        }
        return line.joined(separator: " · ")
    }
    /// `executing`: the backend process is still running. Once it has
    /// exited (verifying, syncing, recovering) nothing is awaited any more.
    static func rows(_ log: NativeStepLog, executing: Bool) -> [Row] {
        log.entries.map { entry in
            let step = entry.step
            let waiting = step.state == .requested && entry.inLatestRing && entry.segment == log.segment && executing
            let (glyph, state): (String, String)
            switch step.state {
            case .observed: (glyph, state) = ("·", os1Tr("관측", "observed"))
            case .requested where waiting: (glyph, state) = ("◌", os1Tr("반환 대기", "awaiting return"))
            // Left the stream's 24-step ring: its return may have arrived unseen.
            case .requested where !entry.inLatestRing: (glyph, state) = ("·", os1Tr("추적 범위 밖", "outside the tracked window"))
            case .requested: (glyph, state) = ("·", os1Tr("반환 신호 미수신", "no return signal received"))
            case .returned: (glyph, state) = ("↩︎", os1Tr("반환", "returned"))
            case .failed: (glyph, state) = ("⚠︎", os1Tr("오류 반환", "returned an error"))
            }
            let detail = step.childToolUses.map { uses in
                os1Tr("하위 도구 \(uses)회", "\(uses) subagent tool calls") +
                    (step.lastChildTool.flatMap(NativeProgressPresentation.safeTool).map { os1Tr(" · 최근 ", " · latest ") + $0 } ?? "")
            }
            return Row(id: entry.id, receivedAt: step.startedAt, text: text(step), glyph: glyph, stateText: state,
                       waitingSince: waiting ? step.startedAt : nil, subagent: step.scope != "main", detail: detail,
                       segment: entry.segment)
        }
    }
    /// One "thinking" line replaces a run of processing signals.
    static func thinking(_ activity: RuntimeActivity, now: Date) -> Bool {
        guard let progress = activity.progress, progress.isValid, progress.kind == .processing else { return false }
        return now.timeIntervalSince(progress.observedAt) < 3
    }
    static func statusText(_ status: String) -> String? {
        status == "compacting" ? os1Tr("백엔드가 대화를 압축하는 중", "The backend is compacting the conversation") : nil
    }
    /// The newest step still awaiting its return, for the banner and sidebar.
    static func latestWaitingText(_ activity: RuntimeActivity) -> String? {
        guard activity.phase == .executing, let progress = activity.progress, progress.isValid,
              let step = progress.latestWaitingStep else { return nil }
        return text(step)
    }
    static func sidebarLine(_ activity: RuntimeActivity) -> String {
        latestWaitingText(activity).map { activity.label + " · " + $0 } ?? activity.label
    }
    static let clock: DateFormatter = {
        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX"); formatter.dateFormat = "HH:mm:ss"
        return formatter
    }()
    // Masking is heuristic, so the footer names what is masked rather than
    // promising that no secret can appear.
    static var footer: String { os1Tr("백엔드가 보낸 단계 설명을 그대로 표시 · 명령은 알려진 비밀값 형태를 가려 표시 · 도구 결과·사고 내용은 표시하지 않음 · 반환은 과제 완료가 아님",
        "The backend's own step descriptions · commands shown with known secret shapes masked · tool results and thinking are not shown · a return is not task completion") }
}

/// The transcript key of the live run row's own disclosure.
private let liveRunDetailKey = "live-run"

/// The live run as the transcript's last row draws it, read at one whole
/// second of the run: its activity, accumulated steps and clock.
private struct LiveRunPresentation: Equatable {
    let activity: RuntimeActivity
    /// The run's accumulated steps; empty falls back to the latest snapshot.
    let steps: NativeStepLog
    let started: Date
    let stopping: Bool
    /// The second of the run the row shows, never a moment between two.
    let now: Date

    init(activity: RuntimeActivity, steps: NativeStepLog = NativeStepLog(), started: Date, stopping: Bool = false,
         now: Date? = nil) {
        self.activity = activity; self.steps = steps; self.started = started; self.stopping = stopping
        // A tick computed as start + n seconds can land a hair below n.
        let second = ((now ?? started).timeIntervalSince(started) + 0.001).rounded(.down)
        self.now = started.addingTimeInterval(max(0, second))
    }
    func at(_ date: Date) -> Self { Self(activity: activity, steps: steps, started: started, stopping: stopping, now: date) }
    var seconds: Int { Int(now.timeIntervalSince(started).rounded()) }
    var elapsed: String { "\(seconds / 60):" + String(format: "%02d", seconds % 60) }
}

/// A received label on one line: breaks flattened and a long middle elided,
/// so a path keeps both its root and its file name.
private func liveRunClipped(_ text: String, _ limit: Int) -> String {
    let flat = text.components(separatedBy: .newlines).joined(separator: " ")
    guard flat.count > limit, limit > 1 else { return flat }
    let head = (limit - 1) / 2
    return String(flat.prefix(head)) + "…" + String(flat.suffix(limit - 1 - head))
}

/// Key prefix of the live feed's tool-call disclosures. Every part of one
/// run's feed (above and below a steered input) shares it, so an opened
/// group stays open when the owner steers; a new run starts them closed.
private let liveFeedKey = "live-feed"

/// A run's public feed laid out the way Claude Code and Codex show a working
/// turn: the backend's own prose reads as text, and each run of tool calls
/// folds into one gray line that opens in place to the calls themselves.
/// `history` grays the prose too, for a finished run's work opened above its
/// answer. Display only: nothing in it is an adopted answer or a completion
/// claim.
private func publicFeedContent(_ segments: [NativePublicRunLog.DisplaySegment], key: String, toolsKey: String? = nil,
                               caption: String? = nil, expanded: Set<String>, expandAll: Bool,
                               history: Bool = false) -> NSAttributedString {
    let result = NSMutableAttributedString()
    func style(before: CGFloat = 0, after: CGFloat = 0, indent: CGFloat = 0) -> NSParagraphStyle {
        let style = NSMutableParagraphStyle()
        style.lineSpacing = 2; style.paragraphSpacingBefore = before; style.paragraphSpacing = after
        style.firstLineHeadIndent = indent; style.headIndent = indent
        return style
    }
    // A piece is one or more paragraphs; its break carries the previous style.
    func add(_ piece: NSAttributedString, _ paragraph: NSParagraphStyle? = nil) {
        guard piece.length > 0 else { return }
        if result.length > 0 {
            var attributes: [NSAttributedString.Key: Any] = [.font: NSFont.systemFont(ofSize: 11)]
            if let previous = result.attribute(.paragraphStyle, at: result.length - 1, effectiveRange: nil) {
                attributes[.paragraphStyle] = previous
            }
            result.append(NSAttributedString(string: "\n", attributes: attributes))
        }
        let start = result.length
        result.append(piece)
        if let paragraph { result.addAttribute(.paragraphStyle, value: paragraph, range: NSRange(location: start, length: piece.length)) }
    }
    func note(_ text: String, size: CGFloat = 11, color: NSColor = TimelinePalette.muted) -> NSAttributedString {
        NSAttributedString(string: text, attributes: [.font: NSFont.systemFont(ofSize: size), .foregroundColor: color])
    }
    var source = segments.first?.source
    if let caption { add(note((source.map { $0 + " · " } ?? "") + caption), style(after: 4)) }
    // Convergence hands the turn to another route: name it where it starts.
    func follow(_ next: String?) {
        guard let next, next != source else { return }
        add(note(next, size: 10, color: TimelinePalette.detail), style(before: 8))
        source = next
    }
    // Each call is listed once, where it began, at its latest state; a
    // subagent's call (also by its received prefix, for earlier records)
    // sits under the agent.
    func id(_ action: NativePublicRunLog.DisplaySegment) -> String { action.actionID ?? String(action.offset) }
    let nested = NativeStepPresentation.isNested
    var latest: [String: NativePublicRunLog.DisplaySegment] = [:]
    for segment in segments where segment.role == .action { latest[id(segment)] = segment }
    var listed = Set<String>()
    var index = 0
    while index < segments.count {
        let segment = segments[index]
        if segment.role == .action {
            var group: [NativePublicRunLog.DisplaySegment] = []
            while index < segments.count, segments[index].role == .action, segments[index].source == segment.source {
                group.append(segments[index]); index += 1
            }
            let calls = group.compactMap { listed.insert(id($0)).inserted ? latest[id($0)] : nil }
            guard !calls.isEmpty else { continue }
            follow(segment.source)
            let groupKey = "\(toolsKey ?? key)-tools-\(group[0].offset)"
            let open = expandAll || expanded.contains(groupKey)
            let summary = NativeStepPresentation.toolSummary(calls.filter { !nested($0) }.map(\.verb),
                nested: calls.filter(nested).count)
            let toggle = NSMutableAttributedString(attributedString: TranscriptMarkdown.detailLink(
                summary + (open ? "  ▾" : "  ▸"), key: groupKey, color: TimelinePalette.detail))
            toggle.addAttributes([.font: NSFont.systemFont(ofSize: 12),
                .toolTip: open ? os1Tr("도구 호출 접기", "Collapse the tool calls") : os1Tr("도구 호출 펼쳐보기", "Expand the tool calls")],
                range: NSRange(location: 0, length: toggle.length))
            add(toggle, style(before: 3, after: 3))
            if open {
                for call in calls {
                    let inner = nested(call)
                    add(note((inner ? "↳ " : "") + liveRunClipped(NativeStepPresentation.feedText(call.text, nested: inner), 160)),
                        style(after: 1, indent: inner ? 28 : 14))
                }
            }
            continue
        }
        index += 1
        let text = segment.text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { continue }
        follow(segment.source)
        switch segment.role {
        case .candidate: add(note(os1Tr("수신 후보 출력 · 미채택", "Received candidate output · not adopted")), style(before: 6))
        case .unattributed: add(note(os1Tr("출처 미확인 공개 출력 · 미채택", "Public output of unconfirmed origin · not adopted")), style(before: 6))
        default: break
        }
        let prose = NSMutableAttributedString(attributedString:
            TranscriptMarkdown.render(text, key: "\(key)-text-\(segment.offset)", expanded: expanded, expandAll: expandAll))
        if history { prose.addAttribute(.foregroundColor, value: TimelinePalette.detail, range: NSRange(location: 0, length: prose.length)) }
        add(prose)
    }
    return result
}

/// A finished run's work line, folded above its answer as Codex shows
/// "Worked for 4m 12s"; opened, the run's own prose and tool calls in gray.
private func turnWorkContent(_ work: TurnWork, key: String, answer: String, expanded: Set<String>, expandAll: Bool,
                             store: NativePublicRunLogStore) -> NSAttributedString {
    let open = expandAll || expanded.contains(key)
    let calls = NativeStepPresentation.toolSummary(Array(repeating: nil, count: work.toolCalls), nested: work.subagentCalls)
    let summary = os1Tr("\(work.duration) 동안 작업", "Worked for \(work.duration)") + (calls.isEmpty ? "" : " · " + calls)
    let content = NSMutableAttributedString(attributedString: TranscriptMarkdown.detailLink(
        summary + (open ? "  ▾" : "  ▸"), key: key, color: TimelinePalette.detail))
    content.addAttributes([.font: NSFont.systemFont(ofSize: 12),
        .toolTip: open ? os1Tr("작업 과정 접기", "Collapse the work") : os1Tr("작업 과정 펼쳐보기 · 도구 호출과 중간 설명", "Expand the work · tool calls and progress notes")],
        range: NSRange(location: 0, length: content.length))
    guard open else { return content }
    let log = store.load(conversationID: work.conversationID, submissionID: work.submissionID, requestSHA256: work.requestSHA256)
    let segments = turnWorkSegments(log, answer: answer)
    content.append(NSAttributedString(string: "\n", attributes: [.font: NSFont.systemFont(ofSize: 12)]))
    content.append(segments.isEmpty
        ? NSAttributedString(string: os1Tr("이 실행의 작업 기록을 더 이상 찾을 수 없습니다.", "This run's work record is no longer available."),
            attributes: [.font: NSFont.systemFont(ofSize: 11), .foregroundColor: TimelinePalette.muted])
        : publicFeedContent(segments, key: key, expanded: expanded, expandAll: expandAll, history: true))
    return content
}

/// The live run as one transcript line — its state, clock and the step the
/// backend is on — whose label opens it in place into the route, counts and
/// every step of the run, as Codex shows a working turn. All of it is
/// received metadata; none of it is a completion claim.
private func liveRunRow(_ run: LiveRunPresentation, expanded: Bool) -> NSAttributedString {
    let activity = run.activity, now = run.now
    let muted = TimelinePalette.muted, small = NSFont.systemFont(ofSize: 11)
    func piece(_ text: String, _ font: NSFont, _ color: NSColor = TimelinePalette.muted) -> NSAttributedString {
        NSAttributedString(string: text, attributes: [.font: font, .foregroundColor: color])
    }
    let presentation = NativeProgressPresentation(activity: activity)
    let quiet = max(0, Int(now.timeIntervalSince(presentation.receivedAt)))
    let thinking = NativeStepPresentation.thinking(activity, now: now)
    let waitingStep = NativeStepPresentation.latestWaitingText(activity)
    let row = NSMutableAttributedString()

    // The dot breathes with the clock; it holds still while stopping or
    // when the owner reduces motion.
    let dotFont = NSFont.systemFont(ofSize: 9)
    let steady = run.stopping || NSWorkspace.shared.accessibilityDisplayShouldReduceMotion
    row.append(piece("●  ", dotFont, run.stopping ? muted
        : TimelinePalette.pink.withAlphaComponent(steady || run.seconds % 2 == 0 ? 1 : 0.4)))
    let label = run.stopping ? os1Tr("작업 중지 확인 중", "Confirming task stop") : activity.label
    // Gray like Codex's "Working for": the pulse is the dot, not the label.
    let toggle = NSMutableAttributedString(attributedString:
        TranscriptMarkdown.detailLink(label + (expanded ? "  ▾" : "  ▸"), key: liveRunDetailKey, color: TimelinePalette.detail))
    toggle.addAttributes([.font: NSFont.systemFont(ofSize: 13, weight: .medium),
        .toolTip: expanded ? os1Tr("진행 단계 접기", "Collapse the run's steps") : os1Tr("진행 단계 펼쳐보기", "Expand the run's steps")],
        range: NSRange(location: 0, length: toggle.length))
    row.append(toggle)
    row.append(piece("   " + os1Tr("\(run.elapsed) 경과", "\(run.elapsed) elapsed"),
        NSFont.monospacedDigitSystemFont(ofSize: 12, weight: .regular)))
    let meta = NSFont.systemFont(ofSize: 12)
    if let waitingStep {
        // The backend's own words for the call it is on, as Claude Code shows them.
        row.append(piece(" · " + liveRunClipped(waitingStep, 72), meta))
    } else if thinking {
        row.append(piece(" · " + os1Tr("생각 중…", "Thinking…"), meta))
    } else if let tool = NativeProgressPresentation.safeTool(activity.tool) {
        row.append(piece(" · " + os1Tr("최근 도구 관측 · ", "Latest observed tool · ") + tool, meta))
    }
    if activity.phase != .waitingForSource, quiet >= 30 {
        row.append(piece(" · " + os1Tr("마지막 신호 \(quiet)초 전", "last signal \(quiet)s ago"), meta))
    }
    guard expanded else { return row }

    // Opened: one paragraph per line, under the label.
    let indent = piece("●  ", dotFont).size().width
    var previousStyle: NSParagraphStyle?
    func line(_ parts: [NSAttributedString], wrapIndent: CGFloat? = nil, tabs: [CGFloat] = [], before: CGFloat = 0,
              toolTip: String? = nil) {
        let style = NSMutableParagraphStyle()
        style.firstLineHeadIndent = indent; style.headIndent = wrapIndent ?? indent
        style.tabStops = tabs.map { NSTextTab(textAlignment: .left, location: $0) }
        style.lineSpacing = 2; style.paragraphSpacing = 2; style.paragraphSpacingBefore = before
        // A paragraph's break carries that paragraph's own style.
        var breakAttributes: [NSAttributedString.Key: Any] = [.font: small]
        if let previousStyle { breakAttributes[.paragraphStyle] = previousStyle }
        row.append(NSAttributedString(string: "\n", attributes: breakAttributes))
        let start = row.length
        parts.forEach(row.append)
        let range = NSRange(location: start, length: row.length - start)
        row.addAttribute(.paragraphStyle, value: style, range: range)
        if let toolTip { row.addAttribute(.toolTip, value: toolTip, range: range) }
        previousStyle = style
    }
    let route = ExecutionRoutePresentation(activity: activity)
    line([piece(route.governanceLine, small)], before: 6, toolTip: route.detail)
    if let counts = presentation.counts {
        line([piece(counts, NSFont.monospacedDigitSystemFont(ofSize: 11, weight: .regular), TimelinePalette.pink)])
    } else if !presentation.rows.isEmpty {
        line([piece(os1Tr("기존 실행: 도구 이름·수신 시각만 관측 · 누적 횟수/반환 상태 미계측",
                          "Earlier run: only tool names and receipt times observed · cumulative counts/return state not measured"), small)])
    }
    if let status = activity.progress?.backendStatus.flatMap(NativeStepPresentation.statusText) {
        line([piece(status, small)])
    }
    let note: String
    if activity.phase == .waitingForSource {
        note = os1Tr("백엔드는 아직 시작하지 않았습니다 · 요청은 보존되며 소스 수리·업데이트가 끝나면 자동으로 이어갑니다.",
                     "The backend hasn't started yet · the request is preserved and continues automatically after the source repair or update.")
    } else if quiet >= 30 {
        note = os1Tr("마지막 단계 업데이트 \(quiet)초 전 · 실행은 열려 있지만 새 진행 신호를 기다리고 있습니다.",
                     "Last stage update \(quiet)s ago · the run is still open but waiting for a new progress signal.")
    } else if activity.toolProgressLabel != nil {
        note = os1Tr("최근 수신 신호 \(quiet)초 전 · 도구 실행/성공 여부는 별도입니다.",
                     "Last signal received \(quiet)s ago · whether the tool ran or succeeded is separate.")
    } else {
        note = os1Tr("최근 수신 \(quiet)초 전", "Last received \(quiet)s ago")
    }
    line([piece(note, small)])

    let log = run.steps.isEmpty ? NativeStepLog(merging: activity.progress) : run.steps
    let steps = NativeStepPresentation.rows(log, executing: activity.phase == .executing)
    let current = steps.filter { $0.segment == log.segment }, earlier = steps.filter { $0.segment != log.segment }
    let clockFont = NSFont.monospacedDigitSystemFont(ofSize: 10.5, weight: .regular)
    let detailFont = NSFont.systemFont(ofSize: 10.5), heading = NSFont.systemFont(ofSize: 10.5, weight: .semibold)
    // Clock, state glyph and step text each in their own column.
    let glyphColumn = indent + piece("00:00:00", clockFont).size().width + 12
    let columns = [glyphColumn, glyphColumn + 18]
    func stepLine(_ step: NativeStepPresentation.Row) {
        let lead = NSMutableAttributedString(attributedString:
            piece(NativeStepPresentation.clock.string(from: step.receivedAt) + "\t", clockFont))
        lead.append(piece(step.glyph + "\t", small, step.waitingSince == nil ? muted : TimelinePalette.pink))
        let nested = piece("↳ ", small)
        if step.subagent { lead.append(nested) }
        var parts: [NSAttributedString] = [lead, piece(liveRunClipped(step.text, 140), meta, TimelinePalette.text)]
        if let detail = step.detail { parts.append(piece("  " + detail, detailFont)) }
        if let since = step.waitingSince {
            let waited = max(0, Int(now.timeIntervalSince(since)))
            parts.append(piece("  · " + step.stateText + " " + os1Tr("\(waited)초", "\(waited)s"), clockFont, TimelinePalette.pink))
        } else if step.stateText != os1Tr("반환", "returned") {
            parts.append(piece("  · " + step.stateText, detailFont))
        }
        line(parts, wrapIndent: columns[1] + (step.subagent ? nested.size().width : 0), tabs: columns, toolTip: step.stateText)
    }
    if !earlier.isEmpty {
        // A retry, a fallback or another route: all an earlier backend stream.
        line([piece(os1Tr("이전 백엔드 실행", "Earlier backend stream"), heading)], before: 4)
        earlier.forEach(stepLine)
        if !current.isEmpty { line([piece(os1Tr("현재 백엔드 실행", "Current backend stream"), heading)], before: 4) }
    }
    current.forEach(stepLine)
    if current.isEmpty {
        // Processing signals collapse into one thinking line; other lifecycle
        // events stay visible until the backend names a step.
        let signals = presentation.rows.filter { !$0.processing }.suffix(4)
        if !signals.isEmpty {
            for signal in signals {
                line([piece(NativeStepPresentation.clock.string(from: signal.receivedAt) + "\t\t", clockFont),
                      piece(signal.label, meta, TimelinePalette.text)], wrapIndent: columns[1], tabs: columns)
            }
        } else if !thinking {
            line([piece(activity.phase == .waitingForSource
                ? os1Tr("네이티브 실행 전 소스 접근 대기", "Waiting for source access before the native run")
                : os1Tr("현재 단계 · ", "Current stage · ") + activity.label + os1Tr(" · 공개 응답/도구 신호를 기다립니다", " · waiting for public response/tool signals"), small)])
        }
    }
    // The header names the waiting step; the thinking line then sits here.
    if thinking, waitingStep != nil { line([piece(os1Tr("생각 중…", "Thinking…"), small)]) }
    line([piece(NativeStepPresentation.footer, NSFont.systemFont(ofSize: 10))], before: 4)
    return row
}

/// A run with the backend's own step lines: six returned steps, one of them
/// a subagent's, and one awaiting its return. Preview and self-test only.
private func liveRunFixture(started: Date, elapsed: TimeInterval = 58, publicText: String? = nil) -> LiveRunPresentation {
    typealias Step = NativeExecutionProgress.Step
    func at(_ seconds: TimeInterval) -> Date { started.addingTimeInterval(seconds) }
    let steps = [
        Step(id: "00000000000a", sequence: 2, tool: "Bash", scope: "main", verb: "run", label: "which codex claude gh",
             state: .returned, startedAt: at(3), endedAt: at(4)),
        Step(id: "00000000000b", sequence: 4, tool: "Read", scope: "main", verb: "read", label: "Sources/OS1App/OS1App.swift",
             state: .returned, startedAt: at(9), endedAt: at(10)),
        Step(id: "00000000000c", sequence: 6, tool: "Grep", scope: "main", verb: "search", label: "RunActivityBanner",
             state: .returned, startedAt: at(15), endedAt: at(16)),
        Step(id: "00000000000d", sequence: 8, tool: "Agent", scope: "main", verb: "agent", label: "Review the transcript layout",
             childToolUses: 3, lastChildTool: "Read", state: .returned, startedAt: at(20), endedAt: at(41)),
        Step(id: "00000000000e", sequence: 9, tool: "Read", scope: "subagent:0123456789ab", verb: "read",
             label: "Sources/OS1App/TranscriptMarkdown.swift", state: .returned, startedAt: at(24), endedAt: at(25)),
        Step(id: "00000000000f", sequence: 10, tool: "Edit", scope: "main", verb: "edit", label: "Sources/OS1App/OS1App.swift",
             state: .returned, startedAt: at(44), endedAt: at(45)),
        Step(id: "000000000010", sequence: 12, tool: "Bash", scope: "main", verb: "run", label: "swift build", startedAt: at(50)),
    ]
    let progress = NativeExecutionProgress(sequence: 12, kind: .toolStarted, tool: "Bash", scope: "main",
        toolsRequested: 7, toolsReturned: 6, activeTools: 1, observedAt: at(50),
        events: [.init(sequence: 12, kind: .toolStarted, tool: "Bash", scope: "main", observedAt: at(50))],
        steps: steps, stream: "0000000000aa")
    let activity = RuntimeActivity(.executing, provider: "claude", surface: "claude", model: "claude-fixture", effort: "max",
        timestamp: at(50), publicText: publicText, tool: "Bash", progress: progress)
    return LiveRunPresentation(activity: activity, steps: NativeStepLog(merging: progress), started: started, now: at(elapsed))
}

/// The live row exactly as the transcript lays it out, for the preview.
@MainActor
private func liveRunPreviewPNG(_ run: LiveRunPresentation, expanded: Bool, messages: [ChatMessage] = [],
                               width: CGFloat = 1_000) throws -> Data {
    try transcriptPreviewPNG(timelineAttributedDocument(messages: messages, queuedSubmissions: [], isRunning: true, workspace: "/tmp",
        liveRun: run, liveRunExpanded: expanded), width: width)
}

/// A transcript document exactly as the conversation lays it out, for the preview.
@MainActor
private func transcriptPreviewPNG(_ document: NSAttributedString, width: CGFloat = 1_000) throws -> Data {
    let view = ContinuousTranscriptTextView(frame: NSRect(x: 0, y: 0, width: width, height: 200))
    view.drawsBackground = false
    view.linkTextAttributes = TimelinePalette.linkAttributes
    view.isEditable = false
    view.isVerticallyResizable = true
    view.maxSize = NSSize(width: width, height: 100_000)
    view.textContainer?.lineFragmentPadding = 0
    view.textContainer?.heightTracksTextView = false
    view.textContainer?.widthTracksTextView = true
    view.textContainer?.containerSize = NSSize(width: width, height: 100_000)
    view.layoutManager?.allowsNonContiguousLayout = false
    view.textStorage?.setAttributedString(document)
    view.setFrameSize(NSSize(width: width, height: 200))
    guard let layout = view.layoutManager, let container = view.textContainer else { throw SourceContextError.invalid }
    layout.ensureLayout(for: container)
    let height = ceil(layout.usedRect(for: container).height + 2 * view.textContainerInset.height)
    view.setFrameSize(NSSize(width: width, height: height))
    let surface = TranscriptSnapshotSurface(frame: view.bounds)
    surface.addSubview(view)
    guard let bitmap = surface.bitmapImageRepForCachingDisplay(in: surface.bounds) else { throw SourceContextError.invalid }
    surface.cacheDisplay(in: surface.bounds, to: bitmap)
    guard let png = bitmap.representation(using: .png, properties: [:]) else { throw SourceContextError.invalid }
    return png
}

/// The run's activity is the transcript's last row: one line until opened,
/// opened in place, and on each second of its clock redrawn alone.
@MainActor
private func liveRunRowSelfTest() throws {
    var checks = 0
    func check(_ ok: Bool, _ why: String) throws {
        guard ok else { throw RunnerError.message("Live run row: " + why) }; checks += 1
    }
    func roles(_ document: NSAttributedString) -> [String] {
        var found: [String] = []
        document.enumerateAttribute(.os1TimelineRole, in: NSRange(location: 0, length: document.length)) { value, _, _ in
            if let role = value as? String, found.last != role { found.append(role) }
        }
        return found
    }
    let started = Date(timeIntervalSince1970: 1_800_000_000)
    let run = liveRunFixture(started: started, publicText: "PRIVATE_PROMPT THINKING TOOL_ARGS TOOL_RESULT")
    func second(_ value: TimeInterval) -> Date { started.addingTimeInterval(value) }

    // The clock shows the run's whole second, never the one before or a negative one.
    try check(run.at(second(3.9995)).elapsed == "0:04" && run.at(second(4.3)).elapsed == "0:04" &&
        run.at(second(65)).elapsed == "1:05" && run.at(second(-5)).elapsed == "0:00", "elapsed clock is not the run's whole second")
    let ticks = LiveRunTicks(started: started).entries(from: second(2.5), mode: .normal)
    try check([ticks.next(), ticks.next(), ticks.next()] == [second(2), second(3), second(4)],
        "ticks are not one per whole second of the run")
    let idleTicks = LiveRunTicks(started: nil).entries(from: started, mode: .normal)
    try check(idleTicks.next() == started && idleTicks.next() == nil, "an idle transcript keeps ticking")

    // Collapsed: one line of state, clock and the step the backend is on.
    let collapsed = liveRunRow(run, expanded: false), open = liveRunRow(run, expanded: true)
    let rows = NativeStepPresentation.rows(run.steps, executing: true)
    let waiting = rows.filter { $0.waitingSince != nil }
    try check(rows.count == 7 && waiting.count == 1 && NativeStepPresentation.latestWaitingText(run.activity) == waiting[0].text,
        "fixture does not have one waiting step among seven")
    try check(!collapsed.string.contains("\n") && collapsed.string.contains(run.activity.label) &&
        collapsed.string.contains("0:58 경과") && collapsed.string.contains(waiting[0].text),
        "collapsed row is not one line of state, clock and the current step")
    try check(rows.filter { $0.waitingSince == nil }.allSatisfy { !collapsed.string.contains($0.text) } &&
        !collapsed.string.contains(NativeStepPresentation.footer), "collapsed row lists finished steps or the footer")
    var links: [URL] = []
    collapsed.enumerateAttribute(.link, in: NSRange(location: 0, length: collapsed.length)) { value, _, _ in
        if let url = value as? URL { links.append(url) }
    }
    let toggle = URL(string: "os1-detail://toggle/" + liveRunDetailKey)!
    try check(links == [toggle], "collapsed row has no single disclosure of its own")
    // Opened: route, counts, every step with its state, and the footer.
    try check(open.string.hasPrefix(collapsed.string.replacingOccurrences(of: "▸", with: "▾")), "opening the row changed its first line")
    try check(open.string.contains(ExecutionRoutePresentation(activity: run.activity).governanceLine) &&
        open.string.contains("요청 7 · 반환 6 · 미반환 1") && open.string.contains("↳ ") &&
        open.string.contains("반환 대기 8초") && open.string.contains(NativeStepPresentation.footer),
        "opened row lacks the route, counts, subagent nesting, waiting time or footer")
    try check(rows.allSatisfy { open.string.contains(liveRunClipped($0.text, 140)) }, "opened row omits a step")
    try check(![collapsed.string, open.string.replacingOccurrences(of: NativeStepPresentation.footer, with: "")].contains {
        $0.contains("완료") || $0.contains("PRIVATE") || $0.contains("TOOL_RESULT") }, "row claims completion or shows private content")
    let stopping = liveRunRow(LiveRunPresentation(activity: run.activity, steps: run.steps, started: started, stopping: true,
        now: run.now), expanded: false)
    try check(stopping.string.contains("작업 중지 확인 중") && !stopping.string.contains(run.activity.label), "a stop request is not shown")
    let quiet = LiveRunPresentation(activity: RuntimeActivity(.executing, provider: "codex", timestamp: started), started: started,
        now: second(65))
    try check(liveRunRow(quiet, expanded: false).string.contains("마지막 신호 65초 전"), "a quiet run hides how long since its last signal")
    let source = LiveRunPresentation(activity: RuntimeActivity(.waitingForSource, provider: "codex", timestamp: started, tool: "Bash"),
        started: started)
    try check(liveRunRow(source, expanded: true).string.contains("백엔드는 아직 시작하지 않았습니다") &&
        !liveRunRow(source, expanded: true).string.contains("요청 "), "a source wait claims backend work")

    // The row is the transcript's one last block, only while the run is live.
    let history = [ChatMessage(role: .user, text: "LIVE_ROW_REQUEST_SENTINEL")]
    let document = timelineAttributedDocument(messages: history, queuedSubmissions: [], isRunning: true, workspace: "/tmp",
        publicProgress: "PUBLIC_PROGRESS_SENTINEL", liveRun: run)
    try check(roles(document) == ["user", "assistant", "liveRun"], "live row is not the transcript's last row: \(roles(document))")
    try check(!roles(timelineAttributedDocument(messages: history, queuedSubmissions: [], isRunning: false, workspace: "/tmp",
        liveRun: run)).contains("liveRun"), "a finished run keeps its live row")

    // A tick rebuilds only the row: history and live output keep their rendering.
    let cache = TranscriptRenderCache()
    var input = TranscriptRenderInput(sessionID: UUID(), messages: history, queued: [], isRunning: true, workspace: "/tmp",
        publicProgress: "PUBLIC_PROGRESS_SENTINEL")
    var firstPrefix: NSAttributedString?, firstProgress: NSAttributedString?
    for tick in 58...61 {
        input.liveRun = run.at(second(Double(tick)))
        let parts = cache.parts(input, expanded: [])
        if tick == 58 { firstPrefix = parts.prefix; firstProgress = parts.progress }
        try check(parts.prefix === firstPrefix && parts.progress === firstProgress && (tick == 58 || !parts.rebuilt),
            "a clock tick rebuilt the history or the live output")
        let joined = NSMutableAttributedString(attributedString: parts.prefix); joined.append(parts.tail)
        let reference = timelineAttributedDocument(messages: history, queuedSubmissions: [], isRunning: true, workspace: "/tmp",
            publicProgress: input.publicProgress, liveRun: input.liveRun)
        try check(joined.isEqual(to: reference), "cached live row differs from a full render at \(tick)s")
        try check(joined.string.contains(input.liveRun!.elapsed + " 경과"), "a tick did not advance the clock")
    }
    try check(cache.prefixBuildCount == 1 && cache.progressBuildCount == 1, "ticks reparsed the history or live output")

    // The actual transcript view: a click opens and closes the row in place.
    let coordinator = ContinuousTranscriptView.Coordinator()
    let scroll = ContinuousTranscriptView.makeScrollView(delegate: coordinator)
    scroll.frame = NSRect(x: 0, y: 0, width: 1_000, height: 700)
    guard let textView = scroll.documentView as? ContinuousTranscriptTextView else { throw RunnerError.message("Live run row: no transcript view") }
    let sessionID = UUID()
    func view(_ tick: Int, running: Bool = true) -> ContinuousTranscriptView {
        ContinuousTranscriptView(sessionID: sessionID, messages: history, queuedSubmissions: [], isRunning: running, workspace: "/tmp",
            publicProgress: running ? "PUBLIC_PROGRESS_SENTINEL" : nil, liveRun: running ? run.at(second(Double(tick))) : nil)
    }
    func full(_ tick: Int, expanded: Bool) -> String {
        timelineAttributedDocument(messages: history, queuedSubmissions: [], isRunning: true, workspace: "/tmp",
            publicProgress: "PUBLIC_PROGRESS_SENTINEL", liveRun: run.at(second(Double(tick))), liveRunExpanded: expanded).string
    }
    let footer = NativeStepPresentation.footer
    coordinator.render(view(58), in: scroll)
    try check(textView.string == full(58, expanded: false), "the live row does not start collapsed")
    try check(coordinator.textView(textView, clickedOnLink: toggle, at: 0) && textView.string == full(58, expanded: true),
        "clicking the row did not open it in place")
    coordinator.render(view(59), in: scroll)
    try check(textView.string == full(59, expanded: true), "a tick closed the opened row or left a stale clock")
    try check(coordinator.textView(textView, clickedOnLink: toggle, at: 0) && textView.string == full(59, expanded: false),
        "clicking again did not collapse the row")
    coordinator.render(view(60), in: scroll)
    try check(textView.string == full(60, expanded: false) && !textView.string.contains(footer), "a tick reopened the row")
    try check(coordinator.renderCache.prefixBuildCount == 1 && coordinator.renderCache.progressBuildCount == 1,
        "opening, closing or a tick re-rendered the history")
    coordinator.render(view(61, running: false), in: scroll)
    try check(!textView.string.contains("경과") && textView.string.contains("LIVE_ROW_REQUEST_SENTINEL"), "the live row outlived its run")
    print("Live run row: \(checks) checks PASS; one line at the transcript end, opens in place, row-only redraw per second; model calls 0")
}

/// A run's public feed as the backend reports it: prose, twelve calls of
/// three verb families (each requested, then labelled and returned), a
/// subagent's call, prose again and one call still waiting. Preview and
/// self-test only.
private func publicFeedFixture(now: Date, conversationID: UUID = UUID(), submissionID: UUID = UUID()) -> NativePublicRunLog {
    var log = NativePublicRunLog(conversationID: conversationID, submissionID: submissionID,
        requestSHA256: SourceContextStore.digest(Data("public feed fixture".utf8)))
    let first = os1Tr("PROSE_ONE 먼저 대화 화면이 진행 출력을 어떻게 그리는지 확인하겠습니다.",
                      "PROSE_ONE First I'll check how the conversation view draws the live output.")
    _ = log.observe(provider: "claude", surface: "claude", stream: "s", text: first, candidate: false,
        origin: .nativeAssistant, receivedAt: now)
    let calls: [(String, String)] = [
        ("run", "git status --short"), ("read", "Sources/OS1App/OS1App.swift"), ("search", "appendLiveProgress"),
        ("read", "Sources/OS1Context/NativePublicRunLog.swift"), ("run", "swift build"), ("read", "Sources/OS1App/TranscriptMarkdown.swift"),
        ("search", "linkTextAttributes"), ("run", "swift build --product OS1App"), ("read", "Tests/OS1ContextTests/NativePublicRunLogFixture.swift"),
        ("run", ".build/debug/OS1ContextTests"), ("run", ".build/debug/OS1App --self-test"), ("run", "git diff --stat"),
    ]
    for (index, call) in calls.enumerated() {
        let id = "0|" + String(format: "%012x", index + 1)
        _ = log.observeAction(id: id, provider: "claude", surface: "claude", text: "Bash — " + os1Tr("요청", "requested"), receivedAt: now)
        _ = log.observeAction(id: id, provider: "claude", surface: "claude",
            text: "TOOL_LINE_\(index) " + (NativeStepPresentation.verbText(call.0) ?? "") + " · " + call.1 + " — " + os1Tr("반환", "returned"),
            verb: call.0, receivedAt: now)
    }
    _ = log.observeAction(id: "0|00000000aaaa", provider: "claude", surface: "claude",
        text: os1Tr("하위 에이전트 · ", "Subagent · ") + "NESTED_LINE " + os1Tr("읽기", "Read") + " · README.md — " + os1Tr("반환", "returned"),
        verb: "read", nested: true, receivedAt: now)
    _ = log.observe(provider: "claude", surface: "claude", stream: "s",
        text: first + os1Tr(" PROSE_TWO 진행 출력은 회색 한 줄로 접고, 설명만 본문으로 남기겠습니다.",
                            " PROSE_TWO I'll fold the tool calls into one gray line and keep the explanation as text."),
        candidate: false, origin: .nativeAssistant, receivedAt: now)
    _ = log.observeAction(id: "0|00000000bbbb", provider: "claude", surface: "claude",
        text: "SWIFT_BUILD " + os1Tr("실행", "Run") + " · swift build — " + os1Tr("요청", "requested"), verb: "run", receivedAt: now)
    return log
}

/// Owner, 2026-10-05: "출력은 해 돌아가고 있는 건 알겠어 근데 그 필수값이
/// 아니잖아" — the live output drew every native action as a full line
/// (a real run: 795 entries, 46,362 points of "Bash — requested"). As Claude
/// Code and Codex show a turn, the backend's prose reads as text, its tool
/// calls fold into gray lines that open in place, and a finished run keeps its
/// work folded above the natural-language answer.
@MainActor
private func publicFeedPresentationSelfTest() throws {
    var checks = 0
    func check(_ ok: Bool, _ why: String) throws {
        guard ok else { throw RunnerError.message("Public feed presentation: " + why) }; checks += 1
    }
    func links(_ document: NSAttributedString) -> [String] {
        var found: [String] = []
        document.enumerateAttribute(.link, in: NSRange(location: 0, length: document.length)) { value, _, _ in
            if let url = value as? URL, url.scheme == "os1-detail" { found.append(url.lastPathComponent) }
        }
        return found
    }
    func color(_ marker: String, in document: NSAttributedString) -> NSColor? {
        let range = (document.string as NSString).range(of: marker)
        guard range.location != NSNotFound else { return nil }
        return document.attribute(.foregroundColor, at: range.location, effectiveRange: nil) as? NSColor
    }
    let now = Date(timeIntervalSince1970: 1_800_000_000)
    var log = publicFeedFixture(now: now)
    let history = [ChatMessage(role: .user, text: "FEED_REQUEST_SENTINEL")]
    func live(_ feed: String, expanded: Set<String> = []) -> NSAttributedString {
        timelineAttributedDocument(messages: history, queuedSubmissions: [], isRunning: true, workspace: "/tmp",
            expanded: expanded, publicProgress: feed)
    }

    // Folded: the prose reads as text, each run of calls is one gray line.
    let feed = log.displayText, folded = live(feed)
    try check(folded.string.contains("PROSE_ONE") && folded.string.contains("PROSE_TWO"), "the backend's prose is not shown as text")
    try check(!folded.string.contains("TOOL_LINE_") && !folded.string.contains("NESTED_LINE") && !folded.string.contains("SWIFT_BUILD") &&
        !folded.string.contains("Bash —"), "tool calls are not folded")
    try check(!folded.string.contains("네이티브 동작") && !folded.string.contains("공개 진행 출력"), "every entry still has its own heading")
    try check(folded.string.contains("도구 호출 12회 · 실행 6 · 읽기 4 · 검색 2 · 하위 에이전트 내부 1회") &&
        folded.string.contains("도구 호출 1회 · 실행 1"), "a run of calls is not summarized by count and verb family")
    try check(folded.string.contains(ProviderSurface.claude.routeTitle + " · 진행 중 · 아직 검증되지 않은 출력"),
        "the feed lost its route or its not-yet-verified label")
    let groups = links(folded)
    try check(groups.count == 2 && groups.allSatisfy { $0.hasPrefix(liveFeedKey + "-tools-") } && Set(groups).count == 2,
        "each run of calls does not have one disclosure of its own")
    try check(color("도구 호출 12회", in: folded) == TimelinePalette.detail && color("PROSE_TWO", in: folded) == TranscriptMarkdown.ink,
        "secondary lines are not gray or the prose is not readable")
    let lines = folded.string.components(separatedBy: CharacterSet(charactersIn: "\n\u{2028}")).filter { !$0.isEmpty }.count
    try check(lines <= 8, "the folded feed takes \(lines) lines")

    // Opened in place: each call once, at its latest state; nesting kept.
    let opened = live(feed, expanded: [groups[0]])
    try check((0..<12).allSatisfy { opened.string.contains("TOOL_LINE_\($0) ") } && !opened.string.contains("Bash —"),
        "an opened group does not list each call once at its latest state")
    try check(opened.string.contains("↳ NESTED_LINE") && !opened.string.contains(os1Tr("하위 에이전트 · ", "Subagent · ") + "NESTED_LINE"),
        "a subagent's call is not nested under the turn")
    try check(!opened.string.contains("SWIFT_BUILD") && color("TOOL_LINE_0", in: opened) == TimelinePalette.muted,
        "opening one group opened another, or its calls are not gray")
    // The feed only grows: an opened group keeps its key and stays open.
    _ = log.observe(provider: "claude", surface: "claude", stream: "s", text: "PROSE_THREE 빌드를 확인합니다.", candidate: false,
        origin: .nativeAssistant, receivedAt: now)
    let grownFeed = log.displayText, grown = live(grownFeed, expanded: [groups[0]])
    try check(grown.string.contains("TOOL_LINE_0 ") && grown.string.contains("PROSE_THREE") && links(grown).prefix(2).elementsEqual(groups),
        "new output moved or closed an opened group")
    // A call that straddles prose is listed once, where it began.
    var straddle = NativePublicRunLog(conversationID: UUID(), submissionID: UUID(), requestSHA256: log.requestSHA256)
    _ = straddle.observeAction(id: "0|000000000001", provider: "claude", surface: "claude", text: "Bash — 요청", receivedAt: now)
    _ = straddle.observe(provider: "claude", surface: "claude", stream: "s", text: "MIDDLE_PROSE", candidate: false,
        origin: .nativeAssistant, receivedAt: now)
    _ = straddle.observeAction(id: "0|000000000001", provider: "claude", surface: "claude", text: "STRADDLE_CALL — 반환",
        verb: "run", receivedAt: now)
    let straddled = live(straddle.displayText, expanded: Set(links(live(straddle.displayText))))
    try check(straddled.string.components(separatedBy: "STRADDLE_CALL").count == 2 && links(straddled).count == 1 &&
        !straddled.string.contains("Bash —"), "a call that straddles prose is listed twice or at an old state")
    // A received candidate and unattributed text keep their not-adopted labels.
    _ = log.observe(provider: "claude", surface: "claude", stream: "s", text: "CANDIDATE_TEXT", candidate: true,
        origin: .nativeAssistant, receivedAt: now)
    try check(live(log.displayText).string.contains("수신 후보 출력 · 미채택\nCANDIDATE_TEXT"), "a candidate lost its not-adopted label")
    // Raw public text (no headings) still reads as before.
    try check(live("RAW_PUBLIC_TEXT").string.contains("진행 중 · 아직 검증되지 않은 출력\nRAW_PUBLIC_TEXT"), "raw public text is not shown")
    // A real run's size: 400 calls between two sentences stay one line.
    var heavy = NativePublicRunLog(conversationID: UUID(), submissionID: UUID(), requestSHA256: log.requestSHA256)
    _ = heavy.observe(provider: "codex", surface: "codex", stream: "c", text: "HEAVY_START", candidate: false, origin: .nativeAssistant, receivedAt: now)
    for index in 0..<400 {
        _ = heavy.observeAction(id: "0|" + String(format: "%012x", index + 1), provider: "codex", surface: "codex",
            text: "HEAVY_CALL_\(index) — 반환", verb: index % 2 == 0 ? "run" : "read", receivedAt: now)
    }
    _ = heavy.observe(provider: "codex", surface: "codex", stream: "c", text: "HEAVY_START HEAVY_END", candidate: false,
        origin: .nativeAssistant, receivedAt: now)
    let heavyDocument = live(heavy.displayText)
    try check(heavyDocument.string.contains("도구 호출 400회 · 실행 200 · 읽기 200") && !heavyDocument.string.contains("HEAVY_CALL_") &&
        heavyDocument.string.contains("HEAVY_END") && heavyDocument.string.components(separatedBy: "\n").count < 12,
        "400 calls did not fold into one line")
    // Convergence: a second route is named where it takes over.
    var converged = NativePublicRunLog(conversationID: UUID(), submissionID: UUID(), requestSHA256: log.requestSHA256)
    _ = converged.observe(provider: "claude", surface: "claude", stream: "a", text: "CLAUDE_PART", candidate: false, origin: .nativeAssistant, receivedAt: now)
    _ = converged.observe(provider: "codex", surface: "codex", stream: "b", text: "CODEX_PART", candidate: false, origin: .nativeAssistant, receivedAt: now)
    let both = live(converged.displayText).string
    try check(both.contains(ProviderSurface.claude.routeTitle + " · 진행 중") && both.contains(ProviderSurface.codex.routeTitle + "\nCODEX_PART"),
        "a converged run does not name the route that took over")

    // The real transcript view: a click opens a group in place, new output
    // keeps it open, and the next run starts folded again.
    let coordinator = ContinuousTranscriptView.Coordinator()
    let scroll = ContinuousTranscriptView.makeScrollView(delegate: coordinator)
    scroll.frame = NSRect(x: 0, y: 0, width: 1_000, height: 700)
    guard let textView = scroll.documentView as? ContinuousTranscriptTextView else { throw RunnerError.message("Public feed presentation: no transcript view") }
    let sessionID = UUID()
    func view(_ text: String?, running: Bool = true) -> ContinuousTranscriptView {
        ContinuousTranscriptView(sessionID: sessionID, messages: history, queuedSubmissions: [], isRunning: running, workspace: "/tmp",
            publicProgress: text, liveRun: running ? liveRunFixture(started: now) : nil)
    }
    coordinator.render(view(feed), in: scroll)
    try check(!textView.string.contains("TOOL_LINE_0 ") && textView.string.contains("PROSE_TWO"), "the transcript does not start folded")
    try check(coordinator.textView(textView, clickedOnLink: URL(string: "os1-detail://toggle/" + groups[0])!, at: 0) &&
        textView.string.contains("TOOL_LINE_0 ") && !textView.string.contains("SWIFT_BUILD"), "a click did not open the group in place")
    coordinator.render(view(grownFeed), in: scroll)
    try check(textView.string.contains("TOOL_LINE_0 ") && textView.string.contains("PROSE_THREE") &&
        textView.string == timelineAttributedDocument(messages: history, queuedSubmissions: [], isRunning: true, workspace: "/tmp",
            expanded: [groups[0]], publicProgress: grownFeed, liveRun: liveRunFixture(started: now)).string,
        "new output closed the opened group or the cached feed differs from a full render")
    coordinator.render(view(nil, running: false), in: scroll)
    coordinator.render(view(feed), in: scroll)
    try check(!textView.string.contains("TOOL_LINE_0 "), "a new run inherited the last run's opened group")

    // A finished run: its work folds above the answer, as Codex's "Worked for".
    let root = FileManager.default.temporaryDirectory.appendingPathComponent("os1-feed-work-" + UUID().uuidString)
    defer { try? FileManager.default.removeItem(at: root) }
    let store = NativePublicRunLogStore(root: root)
    try store.save(log)
    let answerText = "FINAL_ANSWER_SENTINEL 진행 출력을 회색 한 줄로 접었습니다. CANDIDATE_TEXT"
    guard let work = TurnWork(log: log, started: now, answer: answerText, now: now.addingTimeInterval(252)) else {
        throw RunnerError.message("Public feed presentation: a run with tool calls kept no work")
    }
    try check(work.toolCalls == 13 && work.subagentCalls == 1 && work.seconds == 252 && work.duration == "4분 12초",
        "work counts or duration")
    var answer = ChatMessage(role: .assistant, text: answerText, provider: "claude", executionSurface: "claude", timestamp: now)
    answer.work = work
    let receipt = ChatMessage(role: .receipt, text: "RECEIPT_SENTINEL", provider: "claude", nativeRecordVerified: true)
    let finished = history + [answer, receipt]
    func done(_ expanded: Set<String> = [], store: NativePublicRunLogStore = store) -> NSAttributedString {
        timelineAttributedDocument(messages: finished, queuedSubmissions: [], isRunning: false, workspace: "/tmp",
            expanded: expanded, workLogStore: store)
    }
    let closed = done(), workKey = answer.id.uuidString + "-work"
    let text = closed.string as NSString
    try check(closed.string.contains("4분 12초 동안 작업 · 도구 호출 13회 · 하위 에이전트 내부 1회") && !closed.string.contains("PROSE_ONE") &&
        !closed.string.contains("TOOL_LINE_") && text.range(of: "동안 작업").location < text.range(of: "FINAL_ANSWER_SENTINEL").location,
        "the finished run's work is not one folded line above the answer")
    try check(color("4분 12초", in: closed) == TimelinePalette.detail && color("실행 기록 확인됨", in: closed) == TimelinePalette.detail &&
        color("FINAL_ANSWER_SENTINEL", in: closed) == TranscriptMarkdown.ink, "secondary lines are not gray around a readable answer")
    try check(links(closed) == [workKey, receipt.id.uuidString + "-receipt"], "the work line has no disclosure of its own")
    let shown = done([workKey])
    try check(shown.string.contains("PROSE_ONE") && shown.string.contains("PROSE_THREE") && shown.string.contains("도구 호출 12회") &&
        !shown.string.contains("TOOL_LINE_0 ") && shown.string.components(separatedBy: "CANDIDATE_TEXT").count == 2,
        "opened work does not show the run's prose and folded calls, or repeats the answer")
    try check(color("PROSE_ONE", in: shown) == TimelinePalette.detail, "opened work prose is not gray")
    let nestedKey = links(shown).first { $0.hasPrefix(workKey + "-tools-") }
    try check(nestedKey.map { done([workKey, $0]).string.contains("TOOL_LINE_0 ") } == true, "opened work's calls do not open in place")
    try check(done([workKey], store: NativePublicRunLogStore(root: root.appendingPathComponent("missing"))).string
        .contains("이 실행의 작업 기록을 더 이상 찾을 수 없습니다."), "a missing work record is not named")
    // Nothing to show: a run whose only text is its answer keeps no work line.
    var bare = NativePublicRunLog(conversationID: UUID(), submissionID: UUID(), requestSHA256: log.requestSHA256)
    _ = bare.observe(provider: "codex", surface: "gpt-chat", stream: "c", text: "ONLY_ANSWER", candidate: false, origin: .nativeAssistant, receivedAt: now)
    try check(TurnWork(log: bare, started: now, answer: "ONLY_ANSWER") == nil, "a run with nothing beside its answer keeps a work line")
    // Stored with the answer; earlier answers decode without it.
    let decoded = try JSONDecoder().decode(ChatMessage.self, from: JSONEncoder().encode(answer))
    var legacy = try JSONSerialization.jsonObject(with: JSONEncoder().encode(answer)) as! [String: Any]
    legacy.removeValue(forKey: "work")
    let older = try JSONDecoder().decode(ChatMessage.self, from: JSONSerialization.data(withJSONObject: legacy))
    try check(decoded == answer && decoded.work == work && older.work == nil && older.text == answer.text,
        "work does not survive storage or an earlier answer does not load")
    print("Public feed presentation: \(checks) checks PASS; prose as text, tool calls folded gray and opened in place, finished work folded above the answer; model calls 0")
}

private func nativeProgressPresentationSelfTest() throws {
    var checks = 0
    func check(_ value: Bool, _ label: String) throws {
        guard value else { throw RunnerError.message("Native progress presentation: " + label) }; checks += 1
    }
    let stamp = Date(timeIntervalSince1970: 1_800_000_000)
    let events = (17...28).map { i in
        NativeExecutionProgress.Event(sequence: i, kind: i == 28 ? .toolReturned : .processing,
            tool: i == 28 ? "Bash" : "Read", scope: "main", observedAt: stamp.addingTimeInterval(Double(i)))
    }
    let progress = NativeExecutionProgress(sequence: 28, kind: .toolReturned, tool: "Bash", scope: "main",
        toolsRequested: 2, toolsReturned: 1, activeTools: 1, observedAt: stamp.addingTimeInterval(28), events: events)
    let activity = RuntimeActivity(.executing, provider: "claude", timestamp: stamp.addingTimeInterval(90),
        publicText: "PRIVATE_PROMPT THINKING TOOL_ARGS TOOL_RESULT", tool: "Bash", progress: progress)
    let view = NativeProgressPresentation(activity: activity)
    try check(view.typed && view.rows.count == 12, "bounded real lifecycle window")
    try check(view.counts == "요청 2 · 반환 1 · 미반환 1", "request/returned not claimed running")
    try check(view.receivedAt == progress.observedAt && view.rows.last?.receivedAt == progress.observedAt,
        "phase/poll timestamp substituted for receipt timestamp")
    try check(view.rows.last?.label == "도구 반환 · Bash", "return called success")
    try check(!view.rows.map(\.label).joined().contains("PRIVATE") && !view.rows.map(\.label).joined().contains("완료"),
        "private content or completion invented")
    let same = NativeProgressPresentation(activity: activity)
    try check(same.receivedAt == view.receivedAt && same.rows.map(\.id) == view.rows.map(\.id),
        "poll generated independent observations")
    let legacy = NativeProgressPresentation(activity: RuntimeActivity(.executing, provider: "claude", timestamp: stamp, tool: "Edit"))
    try check(!legacy.typed && legacy.counts == nil && legacy.receivedAt == stamp,
        "legacy counts/timing invented")
    try check(legacy.rows.map(\.label) == ["관측된 도구 신호 · Edit"], "legacy request called running or returned")
    let absent = NativeProgressPresentation(activity: RuntimeActivity(.executing, provider: "claude", timestamp: stamp))
    try check(absent.rows.isEmpty && absent.counts == nil, "fake greeting/event for absent telemetry")
    let waiting = NativeProgressPresentation(activity: RuntimeActivity(.waitingForSource, provider: "claude", tool: "Bash", progress: progress))
    try check(waiting.rows.isEmpty && waiting.counts == nil, "source wait inherited native work")
    try check(NativeProgressPresentation.safeTool("Bash --password secret") == nil,
        "tool argument used as tool name")
    try check(NativeProgressPresentation.kindLabel("processing") == "모델 생성 신호 수신" &&
        NativeProgressPresentation.kindLabel("retrying") == "재시도 신호 수신" &&
        NativeProgressPresentation.kindLabel("toolFailed") == "도구 오류 반환 신호", "liveness/retry/error invented prose")

    // Step lines: the backend's own words, accumulated per run by step id.
    typealias Step = NativeExecutionProgress.Step
    func snapshot(_ sequence: Int, kind: NativeExecutionProgress.Kind = .toolStarted, at seconds: Double = 0,
                  stream: String? = nil, _ steps: [Step]) -> NativeExecutionProgress {
        NativeExecutionProgress(sequence: sequence, kind: kind, tool: nil, scope: "main", toolsRequested: steps.count,
            toolsReturned: steps.filter { $0.state != .requested }.count, activeTools: steps.filter { $0.state == .requested }.count,
            observedAt: stamp.addingTimeInterval(seconds),
            events: [.init(sequence: sequence, kind: kind, tool: nil, scope: "main", observedAt: stamp.addingTimeInterval(seconds))], steps: steps,
            stream: stream)
    }
    let bash = Step(id: "00000000000a", sequence: 2, tool: "Bash", scope: "main", startedAt: stamp)
    let first = snapshot(2, [bash])
    let labelled = Step(id: bash.id, sequence: 2, tool: "Bash", scope: "main", label: "Check available CLIs",
                        state: .returned, startedAt: stamp, endedAt: stamp.addingTimeInterval(4))
    let child = Step(id: "00000000000b", sequence: 5, tool: "Read", scope: "subagent:0123456789ab", verb: "read",
                     label: "Sources/App.swift", startedAt: stamp.addingTimeInterval(5))
    let second = snapshot(5, at: 5, [labelled, child])
    var log = NativeStepLog()
    log.merge(first); log.merge(second)
    try check(log.entries.count == 2 && log.entries[0].step.label == "Check available CLIs" && log.entries[0].step.state == .returned,
        "steps not merged by id across snapshots")
    log.merge(snapshot(6, at: 6, [bash, child]))
    try check(log.entries.count == 2 && log.entries[0].step.state == .returned && log.entries[0].step.label != nil && log.segment == 0,
        "an older copy of a step reverted its later state/label or split the run")
    let rows = NativeStepPresentation.rows(log, executing: true)
    try check(rows.map(\.text) == ["Check available CLIs", NativeStepPresentation.verbText("read")! + " · Sources/App.swift"],
        "backend text not relayed verbatim with a fixed verb")
    try check(rows[1].subagent && rows[1].waitingSince == child.startedAt && rows[0].waitingSince == nil &&
        rows[0].stateText == os1Tr("반환", "returned"), "subagent indent / waiting elapsed / return state")
    try check(!rows.flatMap { [$0.text, $0.stateText] }.joined().contains("완료") && !NativeStepPresentation.footer.contains("과제 완료함"),
        "step lines invented a completion claim")
    try check(NativeStepPresentation.text(Step(id: "00000000000c", sequence: 6, tool: "Bash", scope: "main", startedAt: stamp)) == "Bash" &&
        NativeStepPresentation.text(Step(id: "00000000000d", sequence: 7, tool: "Bash", scope: "main", verb: "teleport",
                                         label: "future verb", startedAt: stamp)) == "future verb",
        "unlabelled step not shown by tool name, or unknown verb invented")
    let working = RuntimeActivity(.executing, provider: "claude", timestamp: stamp, progress: second)
    try check(NativeStepPresentation.latestWaitingText(working) == rows[1].text &&
        NativeStepPresentation.sidebarLine(working) == working.label + " · " + rows[1].text,
        "banner/sidebar do not show the latest waiting step")
    let verifying = RuntimeActivity(.verifying, provider: "claude", timestamp: stamp, progress: second)
    try check(NativeStepPresentation.latestWaitingText(verifying) == nil && NativeStepPresentation.sidebarLine(verifying) == verifying.label,
        "a step line outlived the executing phase")
    let restarted = snapshot(1, [Step(id: "00000000000e", sequence: 1, tool: "commandExecution", scope: "main", verb: "run",
                                      label: "swift build", startedAt: stamp.addingTimeInterval(9))])
    log.merge(restarted)
    try check(log.segment == 1 && NativeStepPresentation.rows(log, executing: true).filter { $0.segment == 1 }.count == 1 &&
        NativeStepPresentation.rows(log, executing: true).filter { $0.segment == 0 }.count == 2,
        "a writer without stream identity: a lower sequence did not start a new segment")
    try check(NativeStepPresentation.rows(log, executing: true).first { $0.segment == 0 && $0.subagent }?.waitingSince == nil,
        "an earlier attempt's unreturned step still counts as waiting")
    // Stream identity: a new stream starts a segment even at a higher
    // sequence; a stale snapshot of the same stream is ignored.
    let streamA = "0000000000aa", streamB = "0000000000bb"
    let waitingRead = Step(id: "00000000001a", sequence: 3, tool: "Read", scope: "main", verb: "read", label: "a.swift",
                           startedAt: stamp.addingTimeInterval(20))
    var streamed = NativeStepLog()
    streamed.merge(snapshot(3, at: 20, stream: streamA, [waitingRead]))
    streamed.merge(snapshot(2, at: 21, stream: streamA, [Step(id: "00000000001b", sequence: 2, tool: "Bash", scope: "main",
                                                               label: "stale", startedAt: stamp.addingTimeInterval(19))]))
    try check(streamed.segment == 0 && streamed.entries.map(\.step.label) == ["a.swift"] && streamed.entries[0].inLatestRing,
        "a stale snapshot of the same stream changed the log or started a segment")
    streamed.merge(snapshot(9, at: 30, stream: streamB, [Step(id: "00000000001c", sequence: 9, tool: "Bash", scope: "main",
                                                              label: "next route", startedAt: stamp.addingTimeInterval(30))]))
    try check(streamed.segment == 1 && streamed.entries.last?.segment == 1 && streamed.entries.first?.segment == 0,
        "a new stream at a higher sequence was merged into the earlier stream's segment")
    let after = NativeStepPresentation.rows(log, executing: false)
    try check(after.allSatisfy { $0.waitingSince == nil } &&
        after.contains { $0.stateText == os1Tr("반환 신호 미수신", "no return signal received") },
        "a step still shows a live wait after the backend exited")
    var ring = NativeStepLog()
    ring.merge(snapshot(3, stream: streamA, [waitingRead]))
    ring.merge(snapshot(4, stream: streamA, [Step(id: "00000000001d", sequence: 4, tool: "Bash", scope: "main", label: "later",
                                                  startedAt: stamp)]))
    let outside = NativeStepPresentation.rows(ring, executing: true).first { $0.text.hasSuffix("a.swift") }
    try check(outside?.waitingSince == nil && outside?.stateText == os1Tr("추적 범위 밖", "outside the tracked window"),
        "a step that left the ring is claimed as never returned or still waiting")
    let thinkingProgress = snapshot(9, kind: .processing, at: 10, [])
    let thinkingActivity = RuntimeActivity(.executing, provider: "claude", timestamp: stamp, progress: thinkingProgress)
    try check(NativeStepPresentation.thinking(thinkingActivity, now: stamp.addingTimeInterval(11)) &&
        !NativeStepPresentation.thinking(thinkingActivity, now: stamp.addingTimeInterval(14)) &&
        !NativeStepPresentation.thinking(working, now: stamp.addingTimeInterval(5)), "thinking line timing")
    try check(NativeProgressPresentation(activity: activity).rows.filter { !$0.processing }.count == 1,
        "processing signals not collapsed out of the visible rows")
    try check(NativeStepPresentation.clock.string(from: Date(timeIntervalSince1970: 0)).count == 8, "HH:mm:ss receipt time")
    print("Native progress presentation: \(checks) checks PASS; receipt metadata, backend step lines, legacy/unknown/privacy; model calls 0")
}

private struct QueueEditSheet: View {
    @ObservedObject var store: SessionStore
    let submission: PendingSubmission
    @Environment(\.dismiss) private var dismiss
    @State private var text: String
    init(store: SessionStore, submission: PendingSubmission) {
        self.store = store; self.submission = submission
        _text = State(initialValue: submission.request)
    }
    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            Text(os1Tr("대기 요청 편집", "Edit queued request")).font(.headline)
            Text(os1Tr("대기 순서와 입력 중인 초안은 그대로 유지됩니다. 현재 작업은 중단하지 않습니다.",
                       "Queue order and the draft you're typing stay as they are. The current task isn't interrupted."))
                .font(.caption).foregroundStyle(Theme.muted)
            TextEditor(text: $text).font(.body).frame(minWidth: 440, minHeight: 140)
                .accessibilityLabel(os1Tr("대기 요청 내용", "Queued request text"))
            HStack {
                Spacer()
                Button(os1Tr("취소", "Cancel")) { dismiss() }.keyboardShortcut(.cancelAction)
                Button(os1Tr("대기열에 저장", "Save to queue")) {
                    if store.updateQueued(submission.id, request: text) { dismiss() }
                }.keyboardShortcut(.defaultAction)
                    .disabled(text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
        }.padding(20)
    }
}

private struct ConversationQueueView: View {
    @ObservedObject var store: SessionStore
    let session: ConversationSession
    @State private var editing: PendingSubmission?
    @State private var editLease: UUID?
    private var items: [PendingSubmission] { store.queuedSubmissions.filter { $0.sessionID == session.id } }
    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            HStack {
                Text(session.queuePaused == true ? os1Tr("대기 메시지 \(items.count) · 일시정지", "\(items.count) queued · paused") : os1Tr("대기 메시지 \(items.count)", "\(items.count) queued"))
                    .font(.system(size: 11, weight: .medium)).foregroundStyle(Theme.muted)
                    .accessibilityIdentifier("os1.queue.header")
                Spacer()
                Menu {
                    if store.canResumeQueue(session.id) {
                        Button(os1Tr("대기열 계속 실행", "Resume queue")) { store.resumeQueue(session.id) }
                    } else if session.queuePaused != true {
                        Button(os1Tr("대기열 일시정지", "Pause queue")) { store.pauseQueue(session.id) }
                    }
                    Text(store.queueReason(session.id))
                } label: { Image(systemName: "ellipsis").frame(width: 26, height: 22) }
                    .menuStyle(.borderlessButton).menuIndicator(.hidden).fixedSize()
                    .help(store.queueReason(session.id)).accessibilityLabel(os1Tr("대기열 옵션", "Queue options"))
            }
            if store.globalSlotWait(session.id) != nil ||
                (store.activeRuns[session.id]?.cancellationRequested != true && session.lastFailure == nil) {
                // The actual blocker, visible without opening the menu: the
                // global slot cap reads differently from this chat's own order.
                Text(store.queueReason(session.id))
                    .font(.system(size: 11, weight: store.globalSlotWait(session.id) != nil ? .medium : .regular))
                    .foregroundStyle(store.globalSlotWait(session.id) != nil ? Theme.pink : Theme.muted)
                    .fixedSize(horizontal: false, vertical: true)
                    .accessibilityIdentifier("os1.queue.reason")
            }
            if store.globalSlotWait(session.id) == nil,
               store.activeRuns[session.id]?.cancellationRequested == true || session.lastFailure != nil {
                Text(store.activeRuns[session.id]?.cancellationRequested == true
                    ? os1Tr("실행이 끝나는 대로 선택한 요청을 시작합니다", "Starts the selected request as soon as the run ends")
                    : os1Tr("이전 작업은 보존되며 다시 실행하지 않습니다. 새 메시지를 보내거나 화살표를 누르면 이어서 실행하고, 다음 작업이 실제 상태를 먼저 확인합니다.",
                            "The previous task is preserved and won't run again. Send a new message or press the arrow to continue; the next task checks the actual state first."))
                    .font(.system(size: 11)).foregroundStyle(Theme.muted)
                    .fixedSize(horizontal: false, vertical: true)
            }
            ScrollView {
                VStack(spacing: 2) {
                    ForEach(Array(items.enumerated()), id: \.element.id) { rank, item in
                        HStack(alignment: .center, spacing: 6) {
                            Text(item.request).lineLimit(2).frame(maxWidth: .infinity, alignment: .leading)
                                .help(item.request)
                            Button { store.advanceQueued(item.id, ownerRequested: true) } label: {
                                Image(systemName: "arrow.up").frame(width: 26, height: 26)
                            }.buttonStyle(.plain)
                                .disabled(!store.canSteerQueued(item) && !store.canAdvanceQueued(item) && !store.canReconcileQueued(item))
                                .help(store.queueActionLabel(item))
                                .accessibilityLabel(os1Tr("대기 요청 \(rank + 1) · \(store.queueActionLabel(item))",
                                                          "Queued request \(rank + 1) · \(store.queueActionLabel(item))"))
                                .accessibilityIdentifier("os1.queue.steer.\(item.id)")
                            Button {
                                if store.beginQueueEdit(item.id) { editLease = item.id; editing = item }
                            } label: { Image(systemName: "pencil").frame(width: 26, height: 26) }
                                .buttonStyle(.plain).help(os1Tr("대기 요청 편집 · 순서 유지", "Edit queued request · keeps its place"))
                                .accessibilityLabel(os1Tr("대기 요청 \(rank + 1) 편집", "Edit queued request \(rank + 1)"))
                            Button { store.removeQueued(item.id) } label: { Image(systemName: "xmark").frame(width: 26, height: 26) }
                                .buttonStyle(.plain).help(os1Tr("이 대기 요청만 취소", "Cancel only this queued request")).accessibilityLabel(os1Tr("대기 요청 \(rank + 1) 취소", "Cancel queued request \(rank + 1)"))
                        }.font(.system(size: 12)).padding(.horizontal, 6).padding(.vertical, 4)
                            .contentShape(Rectangle())
                            .contextMenu {
                                Button(os1Tr("위로 이동", "Move up")) { store.shiftQueued(item.id, down: false) }.disabled(rank == 0)
                                Button(os1Tr("아래로 이동", "Move down")) { store.shiftQueued(item.id, down: true) }.disabled(rank == items.count - 1)
                                Button(os1Tr("다음 차례로 이동", "Move to next")) { store.prioritizeQueued(item.id) }.disabled(rank == 0)
                                Button(os1Tr("입력창으로 가져오기", "Move to composer")) { store.editQueued(item.id) }
                                    .disabled(!store.composer.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                            }
                            .onDrag { NSItemProvider(object: "os1-queue:\(item.id.uuidString)" as NSString) }
                            .onDrop(of: [UTType.plainText], isTargeted: nil) { providers in
                                acceptSidebarDrop(providers, prefix: "os1-queue") { value in
                                    if let id = UUID(uuidString: value) { store.moveQueued(id, before: item.id) }
                                }
                            }
                    }
                }
            }.frame(height: min(126, CGFloat(items.count) * 42))
        }.padding(.horizontal, 12).padding(.vertical, 8).foregroundStyle(Theme.text)
            .background(Theme.panelRaised.opacity(0.7), in: RoundedRectangle(cornerRadius: 14))
            .accessibilityIdentifier("os1.queue.pending")
            .sheet(item: $editing, onDismiss: {
                if let id = editLease { store.endQueueEdit(id) }; editLease = nil
            }) { item in QueueEditSheet(store: store, submission: item) }
            .onDisappear { if let id = editLease { store.endQueueEdit(id) }; editLease = nil }
    }
}



private struct ComposerPrimaryButton: View {
    let action: ComposerPrimaryAction
    let activate: () -> Void
    var body: some View {
        Button(action: activate) {
            Image(systemName: action.icon)
                .font(.system(size: 14, weight: .bold))
                .foregroundStyle(Color.black.opacity(0.86))
                .frame(width: 32, height: 32)
                .background(Theme.pink.opacity(action.enabled ? 1 : 0.45))
                .clipShape(Circle())
        }
        .buttonStyle(.plain).disabled(!action.enabled)
        .help(action.help).accessibilityLabel(action.label)
        .accessibilityIdentifier("os1.composer.primary")
    }
}

private struct ComposerView: View {
    @ObservedObject var store: SessionStore
    let session: ConversationSession
    @State private var editorWidth: CGFloat = 560
    @State private var isFileDropTargeted: Bool = false

    private var editorHeight: CGFloat {
        let text = store.composer + " "
        let bounds = (text as NSString).boundingRect(
            with: NSSize(width: max(40, editorWidth - 16), height: .greatestFiniteMagnitude),
            options: [.usesLineFragmentOrigin, .usesFontLeading],
            attributes: [.font: NSFont.systemFont(ofSize: 14, weight: .medium)])
        return min(160, max(48, ceil(bounds.height) + 24))
    }

    var body: some View {
        VStack(spacing: 8) {
            // The live run is the transcript's last row (LiveRunPresentation),
            // not a panel docked here: the composer keeps its own height.
            if !store.isSessionRunning(session.id), session.lastFailure != nil {
                if let failure = session.lastBackendFailure {
                    Text(failure.blocker.message)
                        .font(.system(size: 12)).foregroundStyle(Theme.muted)
                        .textSelection(.enabled).frame(maxWidth: .infinity, alignment: .leading)
                }
                Button(session.lastFailure?.savedResultNeedsReview == true ? os1Tr("저장된 결과·현재 상태 검토 · 변경 재실행 없음", "Review saved result and current state · no changes re-run") : session.lastFailure?.deliveryID != nil ? os1Tr("저장된 결과 전달 · 모델 재실행 없음", "Deliver saved result · no model re-run") : session.lastBackendFailure?.requiresReadback == true
                    ? os1Tr("현재 상태 확인 · 재실행하지 않음", "Check current state · no re-run") : os1Tr("OS-1에서 다시 확인하고 시도", "Recheck in OS-1 and retry")) { store.retrySelectedFailure() }
                    .font(.system(size: 12, weight: .medium))
                    .disabled(store.activeRuns.count >= store.maximumConcurrentSessions)
                    .help(store.activeRuns.count >= store.maximumConcurrentSessions
                        ? os1Tr("동시 실행 \(store.activeRuns.count)/\(store.maximumConcurrentSessions) 사용 중 · 다른 작업이 끝나면 누를 수 있습니다",
                                "\(store.activeRuns.count)/\(store.maximumConcurrentSessions) parallel runs in use · available when another task finishes") : "")
            }
            if store.selectedSessionQueueCount > 0 || session.queuePaused == true {
                ConversationQueueView(store: store, session: session)
            }
            if store.isRunning {
                TimelineView(.periodic(from: .now, by: 0.5)) { _ in
                    if let label = store.correctionDeliveryLabel {
                        Text(label).font(.system(size: 12)).foregroundStyle(Theme.muted)
                            .frame(maxWidth: .infinity, alignment: .leading).textSelection(.enabled)
                    }
                }
            }

            VStack(spacing: 4) {
                if !store.composerAttachments.isEmpty {
                    ComposerAttachmentStrip(store: store)
                        .padding(.horizontal, 12).padding(.top, 10)
                }
                ClodexComposerEditor(
                    text: $store.composer,
                    onSubmit: store.send,
                    onCancelVoice: store.cancelVoiceDictation
                )
                    .frame(height: editorHeight)
                    .background(GeometryReader { geometry in
                        Color.clear.onAppear { editorWidth = geometry.size.width }
                            .onChange(of: geometry.size.width) { editorWidth = $0 }
                    })
                    .padding(.horizontal, 12).padding(.top, 10)
                    .overlay(alignment: .topLeading) {
                        if store.composer.isEmpty {
                            Text(store.isRunning ? os1Tr("다음 지시를 입력하세요…", "Type your next instruction…") : os1Tr("작업을 요청하세요…", "Request a task…"))
                                .font(.system(size: 14)).foregroundStyle(Theme.muted)
                                .padding(.leading, 17).padding(.top, 17).allowsHitTesting(false)
                        }
                    }
                HStack(spacing: 12) {
                    Button { store.chooseContextFiles() } label: {
                        Image(systemName: "plus").frame(width: 24, height: 28)
                    }.buttonStyle(.plain).help(os1Tr("파일 경로를 입력에 추가 · 전송 전 확인", "Add file paths to the input · review before sending"))
                        .accessibilityLabel(os1Tr("파일 경로 추가", "Add file paths"))
                    ExecutionMenu(store: store, session: session)
                    if session.sourceContext != nil {
                        Image(systemName: "paperclip").foregroundStyle(Theme.pink)
                            .help(os1Tr("검증 자료가 연결되어 있습니다. 원본과 해시는 실행 경로에서 유지됩니다.",
                                        "Verified source material is attached. The original and its hash are kept along the execution path."))
                    }
                    Spacer(minLength: 4)
                    VoiceDictationControl(controller: store.voiceDictation, start: store.toggleVoiceDictation,
                        finish: store.finishVoiceDictation, cancel: { _ = store.cancelVoiceDictation() })
                    if store.isRunning, !store.composer.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                        Button { store.sendCorrectionToCurrentRun() } label: {
                            Image(systemName: "arrow.turn.up.right").frame(width: 28, height: 28)
                        }.buttonStyle(.plain).disabled(store.isStopping)
                            .help(store.canSteerSelectedRun ? os1Tr("현재 작업에 반영", "Apply to current task") : os1Tr("현재 작업을 중지하고 추가 지시로 이어가기", "Stop the current task and continue with the new instruction"))
                            .accessibilityLabel(store.canSteerSelectedRun ? os1Tr("현재 작업에 반영", "Apply to current task") : os1Tr("중지 후 추가 지시로 이어가기", "Stop and continue with the new instruction"))
                            .accessibilityIdentifier("os1.composer.steer")
                    }
                    ComposerPrimaryButton(action: store.primaryAction) { store.performPrimaryAction() }
                        .contextMenu {
                            Button(store.canSteerSelectedRun ? os1Tr("현재 작업에 반영", "Apply to current task") : os1Tr("중지 후 추가 지시로 이어가기", "Stop and continue with the new instruction")) { store.sendCorrectionToCurrentRun() }
                                .disabled(!store.isRunning || store.isStopping || store.composer.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                            Button(os1Tr("현재 작업 중지 · ⌘.", "Stop current task · ⌘.")) { store.cancelSelectedRun() }.disabled(!store.isRunning || store.isStopping)
                        }
                }.font(.system(size: 13)).foregroundStyle(Theme.muted).padding(.horizontal, 12).padding(.bottom, 10)
            }
            .background(Theme.panel)
            .clipShape(RoundedRectangle(cornerRadius: 18))
            .overlay(RoundedRectangle(cornerRadius: 18).stroke(isFileDropTargeted ? Theme.pink : Theme.borderStrong, lineWidth: isFileDropTargeted ? 2 : 1))
            .overlay {
                if isFileDropTargeted {
                    RoundedRectangle(cornerRadius: 18)
                        .fill(Theme.pink.opacity(0.08))
                        .overlay(
                            Label(os1Tr("여기에 놓으면 첨부됩니다 · 이미지는 미리보기, 파일은 칩",
                                        "Drop to attach · images as previews, files as chips"), systemImage: "tray.and.arrow.down")
                                .font(.system(size: 12, weight: .medium))
                                .foregroundStyle(Theme.text)
                        )
                        .allowsHitTesting(false)
                        .transition(.opacity)
                }
            }
            .animation(.easeInOut(duration: 0.12), value: isFileDropTargeted)
            .onDrop(of: [UTType.fileURL], isTargeted: $isFileDropTargeted) { providers in
                store.handleComposerDrop(providers)
            }
            HStack(spacing: 6) {
                Button { store.chooseWorkspace() } label: {
                    Label(URL(fileURLWithPath: session.workspace).lastPathComponent, systemImage: "folder")
                        .lineLimit(1).truncationMode(.middle)
                }.buttonStyle(.plain).disabled(store.isRunning).help(session.workspace)
                Spacer(minLength: 8)
                Text(store.isRunning ? os1Tr("↩ 대기열 · ⇧↩ 줄바꿈", "↩ queue · ⇧↩ new line") : os1Tr("↩ 보내기 · ⇧↩ 줄바꿈", "↩ send · ⇧↩ new line"))
            }.font(.system(size: 10)).foregroundStyle(Theme.muted).padding(.horizontal, 4)
        }
        .padding(.horizontal, 24).padding(.top, 8).padding(.bottom, 14)
        .frame(maxWidth: Theme.conversationWidth + 48)
        .frame(maxWidth: .infinity)
        .background(Theme.background)
        .onDisappear { store.stopVoiceDictation() }
    }
}
